let file = """{"version":3,"file":"WorkspaceSettingsPanelContent-DkMNaFMh.js","names":["$t","$t","$t","$emit","$t","$t","$t","$t","$emit","$t","$t","$t"],"sources":["../../src/platform/workspace/composables/useTeamPlan.ts","../../src/platform/workspace/composables/usePlanEnded.ts","../../src/platform/workspace/composables/useBillingBanner.ts","../../src/platform/workspace/composables/useResubscribe.ts","../../src/platform/workspace/components/dialogs/settings/BillingStatusBanner.vue","../../src/platform/workspace/components/dialogs/settings/BillingStatusBanner.vue","../../src/platform/workspace/components/dialogs/settings/PartnerNodeAccessPanel.vue","../../src/platform/workspace/components/dialogs/settings/PartnerNodeAccessPanel.vue","../../src/platform/cloud/subscription/composables/useSubscriptionActions.ts","../../src/platform/cloud/subscription/components/SubscriptionFooterLinks.vue","../../src/platform/cloud/subscription/components/SubscriptionFooterLinks.vue","../../src/platform/cloud/subscription/utils/tierBenefits.ts","../../src/platform/workspace/composables/useWorkspaceMenuItems.ts","../../src/platform/workspace/composables/useWorkspacePlanPricing.ts","../../src/platform/workspace/components/SubscriptionPanelContentWorkspace.vue","../../src/platform/workspace/components/SubscriptionPanelContentWorkspace.vue","../../src/composables/billing/useNextInvoice.ts","../../src/platform/workspace/components/dialogs/settings/WorkspaceInvoicesContent.vue","../../src/platform/workspace/components/dialogs/settings/WorkspaceInvoicesContent.vue","../../src/platform/workspace/components/dialogs/settings/PlanCreditsPanelContent.vue","../../src/platform/workspace/components/dialogs/settings/PlanCreditsPanelContent.vue","../../src/platform/workspace/composables/useMembersPanel.ts","../../src/platform/workspace/components/dialogs/settings/WorkspaceMenuButton.vue","../../src/platform/workspace/components/dialogs/settings/WorkspaceMenuButton.vue","../../src/platform/workspace/components/dialogs/settings/MemberListItem.vue","../../src/platform/workspace/components/dialogs/settings/MemberListItem.vue","../../src/platform/workspace/components/dialogs/settings/MemberUpsellBanner.vue","../../src/platform/workspace/components/dialogs/settings/MemberUpsellBanner.vue","../../src/platform/workspace/components/dialogs/settings/PendingInvitesList.vue","../../src/platform/workspace/components/dialogs/settings/PendingInvitesList.vue","../../src/platform/workspace/components/dialogs/settings/MembersPanelContent.vue","../../src/platform/workspace/components/dialogs/settings/MembersPanelContent.vue","../../src/platform/workspace/components/dialogs/settings/WorkspaceMembersPanelContent.vue","../../src/platform/workspace/components/dialogs/settings/WorkspaceMembersPanelContent.vue","../../src/platform/workspace/components/dialogs/settings/WorkspaceSettingsPanelContent.vue","../../src/platform/workspace/components/dialogs/settings/WorkspaceSettingsPanelContent.vue"],"sourcesContent":["import { computed } from 'vue'\n\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\n\nexport function useTeamPlan() {\n  const {\n    canAccessSubscriptionFeatures,\n    isInitialized,\n    isTeamPlan,\n    maxSeats,\n    subscription\n  } = useBillingContext()\n\n  const isCancelled = computed(() => subscription.value?.isCancelled ?? false)\n  const isOnTeamPlan = computed(\n    () =>\n      isTeamPlan.value &&\n      canAccessSubscriptionFeatures.value &&\n      !isCancelled.value\n  )\n  const hasMemberSeats = computed(\n    () => maxSeats.value === 0 || (maxSeats.value ?? 0) > 1\n  )\n  const isPlanLoading = computed(() => !isInitialized.value)\n\n  return {\n    maxSeats,\n    hasTeamPlan: isTeamPlan,\n    isOnTeamPlan,\n    isCancelled,\n    hasMemberSeats,\n    isPlanLoading\n  }\n}\n","import { computed } from 'vue'\n\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { isSalesManagedTier } from '@/platform/cloud/subscription/constants/tierPricing'\nimport { useTeamPlan } from '@/platform/workspace/composables/useTeamPlan'\n\nexport function usePlanEnded() {\n  const { subscription, subscriptionStatus, canAccessSubscriptionFeatures } =\n    useBillingContext()\n  const { hasTeamPlan } = useTeamPlan()\n\n  // Ended (billing_status inactive) is the only member-management freeze.\n  // A cancel-scheduled subscription stays active until cancel_at and the\n  // backend permits seat adds the whole time — capability, invite endpoint,\n  // and Stripe write path all allow it (DES-1200; verified on cloud/main\n  // 2026-09-23) — so cancelled workspaces keep invites live. Two payload\n  // shapes report a terminal plan: subscription_status 'ended', and a\n  // cancelled row whose access has already closed (the backend reconciles\n  // that shape into 'ended' on read, but a stale payload can still carry\n  // it). Scoped by subscription shape, not seat capacity: when a plan\n  // truly ends the backend collapses max_seats to the no-plan default of 1\n  // (observed on test: ended + ENTERPRISE + max_seats 1), so a seat gate\n  // reads the flagship ended workspace as \"seatless\" and hides the very\n  // explanation this state exists to show. A lapsed personal subscription\n  // stays out via the team/sales-managed gate instead.\n  const isPlanTerminal = computed(\n    () =>\n      subscriptionStatus.value === 'ended' ||\n      (subscriptionStatus.value === 'canceled' &&\n        !canAccessSubscriptionFeatures.value)\n  )\n  // Qualifying for the treatment needs a KNOWN signal — the team classifier\n  // or a real tier that is sales-managed. A terminal payload with no tier\n  // and no team signal is most plausibly a lapsed personal subscription,\n  // which belongs to the upgrade banner. (The nullish fail-close in\n  // isSalesManagedPlan below governs only the route back once a workspace\n  // is already in the treatment.)\n  const isPlanEnded = computed(() => {\n    if (!isPlanTerminal.value) return false\n    if (hasTeamPlan.value) return true\n    const tier = subscription.value?.tier\n    return tier != null && isSalesManagedTier(tier)\n  })\n  // Sales-managed, not strictly ENTERPRISE: isSalesManagedTier() treats an\n  // unrecognized tier as sales-managed too, so an ended unknown/future plan\n  // routes to Contact sales rather than borrowing the self-serve Reactivate\n  // claim (the same fail-closed contract the pricing surfaces follow). A\n  // missing tier is equally unidentifiable, so it fails closed to the sales\n  // route too — never a self-serve Resume the capability would refuse.\n  const isSalesManagedPlan = computed(() => {\n    const tier = subscription.value?.tier\n    return tier == null ? true : isSalesManagedTier(tier)\n  })\n  // Strict: drives the contactSales copy only — an unrecognized tier keeps\n  // the sales route but gets plan-neutral wording.\n  const isEnterprisePlan = computed(\n    () => subscription.value?.tier === 'ENTERPRISE'\n  )\n\n  return { isPlanEnded, isPlanTerminal, isSalesManagedPlan, isEnterprisePlan }\n}\n","import {\n  createSharedComposable,\n  useEventListener,\n  useTimestamp\n} from '@vueuse/core'\nimport { computed, ref, watch } from 'vue'\n\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { isWithinEnterpriseEndingNotice } from '@/platform/cloud/subscription/constants/tierPricing'\nimport { isCloud } from '@/platform/distribution/types'\nimport type { SubscriptionInfo } from '@/composables/billing/types'\nimport type {\n  SubscriptionTier,\n  BillingStatus\n} from '@/platform/workspace/api/workspaceApi'\nimport { usePlanEnded } from '@/platform/workspace/composables/usePlanEnded'\nimport { useWorkspaceUI } from '@/platform/workspace/composables/useWorkspaceUI'\n\nexport type BillingBannerKind =\n  | 'paused'\n  | 'paymentFailed'\n  | 'planEnded'\n  | 'outOfCredits'\n  | 'ending'\n  | 'planChange'\n\nexport type BillingBannerAudience = 'team' | 'personal'\n\nexport interface BillingBannerInputs {\n  billingControlEnabled: boolean\n  v1PaymentRecovery: boolean\n  isTeamPlan: boolean\n  isEnterprise: boolean\n  isKnownPersonalTier: boolean\n  hasRenewalInvoice: boolean\n  isInvoiceRecoverableTier: boolean\n  isLoaded: boolean\n  canAccessSubscriptionFeatures: boolean\n  billingStatus: BillingStatus | null\n  hasFunds: boolean | null\n  isCancelled: boolean\n  endDate: string | null\n  canManage: boolean\n  isPlanEnded: boolean\n  isPlanTerminal: boolean\n  planEndedDismissed: boolean\n  outOfCreditsDismissed: boolean\n  planChangeDismissed: boolean\n  hasScheduledChange: boolean\n}\n\n// An Enterprise cancel_at is an agreed end date — an operator pilot term or\n// a sales-mediated cancellation. The two are deliberately not distinguished:\n// cancel_at alone cannot tell them apart (cloud's\n// common/repository/billing/repository.go), and the rendering is truthful\n// for both — quiet until the 14-day window, then the ending notice.\n// Decision recorded on FE-2035. Enterprise payment and credit lifecycles\n// are handled by sales, so paused/paymentFailed/outOfCredits never apply.\nfunction deriveEnterpriseBanner(\n  inputs: BillingBannerInputs,\n  now: number\n): BillingBannerKind | null {\n  if (!inputs.canAccessSubscriptionFeatures) return null\n  if (!inputs.billingControlEnabled) return null\n  const withinEndingNotice =\n    inputs.isCancelled && isWithinEnterpriseEndingNotice(inputs.endDate, now)\n  return withinEndingNotice ? 'ending' : null\n}\n\n// The personal tiers whose payment-recovery claim is known-good. An\n// unrecognized server tier reads as \"not team, not Enterprise\" and would\n// otherwise borrow the personal claim — the module's unknown-tier policy is\n// fail-closed, so recovery is granted only to tiers on this list. An\n// outstanding renewal invoice also qualifies for FREE or no tier, which is how\n// past-due legacy subscribers are reported; other unrecognized tiers stay out.\nconst PERSONAL_RECOVERY_TIERS: ReadonlySet<SubscriptionTier> = new Set([\n  'STANDARD',\n  'CREATOR',\n  'PRO',\n  'FOUNDERS_EDITION'\n])\n\n// Payment recovery reaches personal workspaces too. Its rollout gate is\n// independent of billing control.\nfunction derivePaymentRecoveryBanner(\n  inputs: BillingBannerInputs\n): BillingBannerKind | null {\n  if (!inputs.v1PaymentRecovery) return null\n  if (\n    !inputs.isTeamPlan &&\n    !inputs.isKnownPersonalTier &&\n    !(inputs.hasRenewalInvoice && inputs.isInvoiceRecoverableTier)\n  ) {\n    return null\n  }\n  if (inputs.billingStatus === 'paused') return 'paused'\n  if (inputs.billingStatus === 'payment_failed') return 'paymentFailed'\n  return null\n}\n\n// The self-serve plans the billing-control notices speak to. Enterprise and\n// unrecognized tiers have no audience, so they fail closed to no notice.\nfunction billingBannerAudience(\n  inputs: Pick<\n    BillingBannerInputs,\n    'isTeamPlan' | 'isEnterprise' | 'isKnownPersonalTier'\n  >\n): BillingBannerAudience | null {\n  if (inputs.isEnterprise) return null\n  if (inputs.isTeamPlan) return 'team'\n  return inputs.isKnownPersonalTier ? 'personal' : null\n}\n\n// A self-serve cancellation is user-initiated news, so its ending notice\n// shows at once. A scheduled change is suppressed while cancelled — the\n// ending notice already owns that window — and is owner-only. It has no\n// personal design yet, so it stays team-only.\nfunction deriveLifecycleNotice(\n  inputs: BillingBannerInputs,\n  audience: BillingBannerAudience\n): BillingBannerKind | null {\n  if (inputs.isCancelled && inputs.endDate) return 'ending'\n  const showsPlanChange =\n    audience === 'team' &&\n    inputs.hasScheduledChange &&\n    !inputs.isCancelled &&\n    inputs.canManage &&\n    !inputs.planChangeDismissed\n  return showsPlanChange ? 'planChange' : null\n}\n\nfunction deriveNoticeBanner(\n  inputs: BillingBannerInputs,\n  audience: BillingBannerAudience\n): BillingBannerKind | null {\n  if (!inputs.canAccessSubscriptionFeatures) return null\n  if (!inputs.billingControlEnabled) return null\n  if (inputs.hasFunds === false && !inputs.outOfCreditsDismissed) {\n    return 'outOfCredits'\n  }\n  return deriveLifecycleNotice(inputs, audience)\n}\n\n// usePlanEnded covers team and sales-managed plans only; a terminal personal\n// plan is read here so the Members panel keeps its personal upsell.\nfunction hasPlanEnded(\n  inputs: BillingBannerInputs,\n  audience: BillingBannerAudience | null\n): boolean {\n  return (\n    inputs.isPlanEnded || (audience === 'personal' && inputs.isPlanTerminal)\n  )\n}\n\n// The single billing banner slot, in priority order: paused > paymentFailed >\n// planEnded > outOfCredits > ending > planChange. The Enterprise policy takes\n// precedence over any team-plan reading of the same subscription. Plan ended\n// ships without a rollout flag.\nexport function deriveBillingBanner(\n  inputs: BillingBannerInputs,\n  now: number = Date.now()\n): BillingBannerKind | null {\n  if (!inputs.isLoaded) return null\n  const recovery = inputs.isEnterprise\n    ? null\n    : derivePaymentRecoveryBanner(inputs)\n  if (recovery) return recovery\n  const audience = billingBannerAudience(inputs)\n  if (hasPlanEnded(inputs, audience)) {\n    return inputs.planEndedDismissed ? null : 'planEnded'\n  }\n  if (inputs.isEnterprise) return deriveEnterpriseBanner(inputs, now)\n  return audience ? deriveNoticeBanner(inputs, audience) : null\n}\n\nfunction classifyTier(\n  tier: SubscriptionTier | null | undefined\n): Pick<\n  BillingBannerInputs,\n  'isEnterprise' | 'isKnownPersonalTier' | 'isInvoiceRecoverableTier'\n> {\n  return {\n    isEnterprise: tier === 'ENTERPRISE',\n    isInvoiceRecoverableTier: tier == null || tier === 'FREE',\n    isKnownPersonalTier: tier != null && PERSONAL_RECOVERY_TIERS.has(tier)\n  }\n}\n\nfunction readSubscriptionInputs(\n  subscription: SubscriptionInfo | null\n): Pick<\n  BillingBannerInputs,\n  | 'isEnterprise'\n  | 'isKnownPersonalTier'\n  | 'isInvoiceRecoverableTier'\n  | 'isLoaded'\n  | 'hasFunds'\n  | 'isCancelled'\n  | 'endDate'\n  | 'hasScheduledChange'\n> {\n  return {\n    ...classifyTier(subscription?.tier),\n    isLoaded: subscription !== null,\n    hasFunds: subscription?.hasFunds ?? null,\n    isCancelled: subscription?.isCancelled ?? false,\n    endDate: subscription?.endDate ?? null,\n    hasScheduledChange: subscription?.scheduledChange != null\n  }\n}\n\nfunction useBillingBannerInternal() {\n  const {\n    canAccessSubscriptionFeatures,\n    billingStatus,\n    subscription,\n    isTeamPlan,\n    renewalInvoice,\n    fetchStatus,\n    fetchBalance\n  } = useBillingContext()\n  const { permissions } = useWorkspaceUI()\n  const { flags } = useFeatureFlags()\n\n  const { isPlanEnded, isPlanTerminal } = usePlanEnded()\n  const planEndedDismissed = ref(false)\n  const outOfCreditsDismissed = ref(false)\n  const planChangeDismissed = ref(false)\n\n  // Coarse shared clock so the enterprise notice window opens mid-session\n  // instead of waiting for an unrelated billing ref to change.\n  const now = useTimestamp({ interval: 60_000 })\n\n  const bannerInputs = computed<BillingBannerInputs>(() => ({\n    billingControlEnabled: flags.billingControlEnabled,\n    v1PaymentRecovery: flags.v1PaymentRecovery,\n    isTeamPlan: isTeamPlan.value,\n    hasRenewalInvoice: renewalInvoice.value != null,\n    canAccessSubscriptionFeatures: canAccessSubscriptionFeatures.value,\n    billingStatus: billingStatus.value,\n    canManage: permissions.value.canManageSubscription,\n    isPlanEnded: isPlanEnded.value,\n    isPlanTerminal: isPlanTerminal.value,\n    planEndedDismissed: planEndedDismissed.value,\n    outOfCreditsDismissed: outOfCreditsDismissed.value,\n    planChangeDismissed: planChangeDismissed.value,\n    ...readSubscriptionInputs(subscription.value)\n  }))\n\n  const kind = computed<BillingBannerKind | null>(() =>\n    isCloud ? deriveBillingBanner(bannerInputs.value, now.value) : null\n  )\n  const audience = computed(() => billingBannerAudience(bannerInputs.value))\n\n  // Out-of-credits dismissal lasts one exhaustion episode: reset once the\n  // workspace is funded again so a later exhaustion re-shows. Plan ended and\n  // plan change dismissals last the session. Shared state, so both survive the settings\n  // panel unmounting when the dialog closes.\n  const hasExhaustedFunds = computed(\n    () => subscription.value?.hasFunds === false\n  )\n  watch(hasExhaustedFunds, (exhausted) => {\n    if (!exhausted) outOfCreditsDismissed.value = false\n  })\n\n  useEventListener(window, 'focus', () => {\n    if (kind.value !== 'paymentFailed' && kind.value !== 'paused') return\n    void Promise.allSettled([fetchStatus(), fetchBalance()])\n  })\n\n  function dismiss() {\n    if (kind.value === 'planEnded') planEndedDismissed.value = true\n    if (kind.value === 'outOfCredits') outOfCreditsDismissed.value = true\n    if (kind.value === 'planChange') planChangeDismissed.value = true\n  }\n\n  return { kind, audience, dismiss }\n}\n\nexport const useBillingBanner = createSharedComposable(useBillingBannerInternal)\n","import { useToast } from '@/components/ui/toast/toastStore'\nimport { ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useBillingRouting } from '@/composables/billing/useBillingRouting'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { categorizeBillingApiError } from '@/platform/telemetry/utils/billingFailureCategory'\nimport { useWorkspaceUI } from '@/platform/workspace/composables/useWorkspaceUI'\n\n/**\n * Reactivates a cancelled-but-still-active subscription and surfaces success or\n * failure as a toast, tracking the in-flight state for the calling button.\n */\nexport function useResubscribe() {\n  const { t } = useI18n()\n  const toast = useToast()\n  const { resubscribe } = useBillingContext()\n  const { shouldUseWorkspaceBilling } = useBillingRouting()\n  const { canReactivatePlan } = useWorkspaceUI()\n\n  const isResubscribing = ref(false)\n\n  async function handleResubscribe() {\n    if (!canReactivatePlan.value) return\n\n    const source = 'settings_billing_panel' as const\n    const startedAt = Date.now()\n    const isWorkspaceResubscribe = shouldUseWorkspaceBilling.value\n\n    useTelemetry()?.trackResubscribeClicked({ source })\n    // Emitted before the awaited call so a failure always has a preceding\n    // `started` — emitting it only after the call meant a failure produced a\n    // `failed` with no matching `started`, pushing failed/started over 100%.\n    useTelemetry()?.trackBillingEvent({\n      operation: 'resubscribe',\n      stage: 'started',\n      outcome: 'pending',\n      source\n    })\n    isResubscribing.value = true\n    try {\n      await resubscribe({ source })\n      // Workspace's resubscribe() call is itself the terminal reactivation, so it\n      // gets an immediate `succeeded` here. Legacy only opens a Stripe checkout\n      // tab, which isn't terminal — its `succeeded` is emitted later, from\n      // useSubscription.ts's pending-checkout recovery, once a status poll\n      // confirms the payment actually went through.\n      if (isWorkspaceResubscribe) {\n        useTelemetry()?.trackBillingEvent({\n          operation: 'resubscribe',\n          stage: 'succeeded',\n          outcome: 'success',\n          source,\n          duration_ms: Date.now() - startedAt\n        })\n      }\n      toast.success(t('subscription.resubscribeSuccess'), { duration: 5000 })\n    } catch (error) {\n      const detail =\n        error instanceof Error && error.message.trim()\n          ? error.message\n          : t('subscription.resubscribeFailed')\n      useTelemetry()?.trackBillingEvent({\n        operation: 'resubscribe',\n        stage: 'failed',\n        outcome: 'failure',\n        source,\n        failure_category: categorizeBillingApiError(error),\n        ...(isWorkspaceResubscribe && {\n          duration_ms: Date.now() - startedAt\n        })\n      })\n      toast.error(t('g.error'), { description: detail })\n    } finally {\n      isResubscribing.value = false\n    }\n  }\n\n  return { isResubscribing, handleResubscribe }\n}\n","<template>\n  <div v-if=\"banner\" class=\"@container\">\n    <div\n      role=\"status\"\n      class=\"flex flex-col gap-3 rounded-2xl border border-interface-stroke/60 bg-base-background p-4 @2xl:flex-row @2xl:items-center @2xl:gap-2\"\n    >\n      <div class=\"flex min-w-0 flex-1 flex-col gap-1\">\n        <div class=\"flex items-center gap-2\">\n          <i\n            :class=\"\n              cn(\n                'size-4 shrink-0',\n                banner.muted\n                  ? 'icon-[lucide--circle-alert] text-muted-foreground'\n                  : 'icon-[lucide--triangle-alert] text-warning-background'\n              )\n            \"\n          />\n          <span class=\"text-sm text-base-foreground\">{{ banner.title }}</span>\n        </div>\n        <p class=\"m-0 pl-6 text-sm text-muted-foreground\">{{ banner.body }}</p>\n      </div>\n      <div\n        v-if=\"banner.dismissible || banner.action\"\n        class=\"flex shrink-0 flex-wrap items-center gap-2 pl-6 @2xl:pl-0\"\n      >\n        <Button\n          v-if=\"banner.dismissible\"\n          variant=\"textonly\"\n          size=\"lg\"\n          @click=\"dismiss\"\n        >\n          {{ $t('workspacePanel.billingStatus.outOfCredits.dismiss') }}\n        </Button>\n        <Button\n          v-if=\"banner.action === 'addCredits'\"\n          variant=\"secondary\"\n          size=\"lg\"\n          @click=\"handleAddCredits\"\n        >\n          {{ $t('workspacePanel.billingStatus.outOfCredits.addCredits') }}\n        </Button>\n        <Button\n          v-else-if=\"banner.action === 'reactivate'\"\n          variant=\"secondary\"\n          size=\"lg\"\n          :loading=\"isResubscribing\"\n          @click=\"handleResubscribe\"\n        >\n          {{ $t('workspacePanel.billingStatus.ending.reactivate') }}\n        </Button>\n        <Button\n          v-else-if=\"banner.action === 'resubscribe'\"\n          variant=\"secondary\"\n          size=\"lg\"\n          @click=\"handleResubscribePlan\"\n        >\n          {{ $t('workspacePanel.members.resubscribe') }}\n        </Button>\n        <Button\n          v-else-if=\"banner.action === 'contactSales'\"\n          variant=\"secondary\"\n          size=\"lg\"\n          @click=\"handleContactSales\"\n        >\n          {{ $t('workspacePanel.billingStatus.ending.contactSales') }}\n        </Button>\n        <template v-else-if=\"banner.action === 'updatePayment'\">\n          <Button\n            v-if=\"banner.payInvoiceUrl\"\n            variant=\"inverted\"\n            size=\"lg\"\n            @click=\"handlePayInvoice(banner.payInvoiceUrl)\"\n          >\n            {{ $t('workspacePanel.billingStatus.payInvoice') }}\n          </Button>\n          <Button\n            :variant=\"banner.payInvoiceUrl ? 'secondary' : 'inverted'\"\n            size=\"lg\"\n            @click=\"handleUpdatePayment\"\n          >\n            {{ $t('workspacePanel.billingStatus.updatePayment') }}\n          </Button>\n        </template>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { ENTERPRISE_URL } from '@/platform/cloud/subscription/constants/tierPricing'\nimport { useSubscriptionDialog } from '@/platform/cloud/subscription/composables/useSubscriptionDialog'\nimport { useBillingBanner } from '@/platform/workspace/composables/useBillingBanner'\nimport type {\n  BillingBannerAudience,\n  BillingBannerKind\n} from '@/platform/workspace/composables/useBillingBanner'\nimport { useBillingCapabilities } from '@/platform/workspace/composables/useBillingCapabilities'\nimport { usePlanEnded } from '@/platform/workspace/composables/usePlanEnded'\nimport { useResubscribe } from '@/platform/workspace/composables/useResubscribe'\nimport { useScheduledPlanChange } from '@/platform/workspace/composables/useScheduledPlanChange'\nimport { useWorkspaceTierLabel } from '@/platform/workspace/composables/useWorkspaceTierLabel'\nimport { useWorkspaceUI } from '@/platform/workspace/composables/useWorkspaceUI'\nimport { useBillingDialogs } from '@/composables/billing/useBillingDialogs'\n\ntype BannerAction =\n  | 'addCredits'\n  | 'reactivate'\n  | 'resubscribe'\n  | 'contactSales'\n  | 'updatePayment'\n\nconst { section } = defineProps<{\n  section?: 'planCredits' | 'members' | 'allowlist'\n}>()\n\nconst { t, d } = useI18n()\nconst { renewalDate, renewalInvoice, subscription, manageSubscription } =\n  useBillingContext()\nconst { permissions, canReactivatePlan, workspaceType } = useWorkspaceUI()\nconst { canTopUp } = useBillingCapabilities()\nconst { kind, audience, dismiss } = useBillingBanner()\nconst { formatTierName } = useWorkspaceTierLabel()\nconst { isResubscribing, handleResubscribe } = useResubscribe()\nconst {\n  scheduledChange,\n  planName: scheduledPlanName,\n  isDisplayable: canShowScheduledChange\n} = useScheduledPlanChange()\nconst { showTopUpCreditsDialog } = useBillingDialogs()\nconst subscriptionDialog = useSubscriptionDialog()\nconst { isSalesManagedPlan, isEnterprisePlan: isEndedEnterprisePlan } =\n  usePlanEnded()\n\nconst canManage = computed(() => permissions.value.canManageSubscription)\n// Strictly ENTERPRISE: an unrecognized tier must not borrow Enterprise copy\n// (isUnknownTier's contract) nor lose its Reactivate path.\nconst isEnterprisePlan = computed(\n  () => subscription.value?.tier === 'ENTERPRISE'\n)\nfunction longDate(raw: string | null | undefined): string {\n  const date = raw ? new Date(raw) : null\n  if (!date || Number.isNaN(date.getTime())) return ''\n  return d(date, { year: 'numeric', month: 'long', day: 'numeric' })\n}\nconst cycleResetDate = computed(() => longDate(renewalDate.value))\nconst planEndDate = computed(() => longDate(subscription.value?.endDate))\nconst planName = computed(() => formatTierName(subscription.value?.tier, false))\n\ninterface BannerView {\n  muted: boolean\n  title: string\n  body: string\n  action: BannerAction | null\n  dismissible: boolean\n  payInvoiceUrl?: string\n}\n\nconst bs = 'workspacePanel.billingStatus'\n\nconst audienceCopy = {\n  team: {\n    outOfCreditsBody: `${bs}.outOfCredits.body`,\n    outOfCreditsBodyNoDate: `${bs}.outOfCredits.bodyNoDate`,\n    endingTitle: `${bs}.ending.title`,\n    endingBody: `${bs}.ending.body`\n  },\n  personal: {\n    outOfCreditsBody: `${bs}.outOfCredits.personalBody`,\n    outOfCreditsBodyNoDate: `${bs}.outOfCredits.personalBodyNoDate`,\n    endingTitle: `${bs}.ending.personalTitle`,\n    endingBody: `${bs}.ending.personalBody`\n  }\n} satisfies Record<BillingBannerAudience, Record<string, string>>\n\nconst copy = computed(() => audienceCopy[audience.value ?? 'team'])\n\nconst PLAN_LIFECYCLE_KINDS: ReadonlySet<BillingBannerKind> = new Set([\n  'planEnded',\n  'ending',\n  'planChange'\n])\n\n// A personal workspace's Members tab carries its own upgrade pitch, so the\n// plan lifecycle notices stay on the Plan & Credits tab.\nconst isHiddenOnSection = computed(\n  () =>\n    section === 'members' &&\n    workspaceType.value === 'personal' &&\n    kind.value !== null &&\n    PLAN_LIFECYCLE_KINDS.has(kind.value)\n)\n\n// Only an https payment page is opened; anything else hides the action.\nfunction safeInvoiceUrl(value: string | undefined): string | undefined {\n  if (!value) return undefined\n  try {\n    return new URL(value).protocol === 'https:' ? value : undefined\n  } catch {\n    return undefined\n  }\n}\n\nconst pausedView = (): BannerView => ({\n  muted: !canManage.value,\n  title: t(`${bs}.paused.title`),\n  body: canManage.value ? t(`${bs}.paused.body`) : t(`${bs}.paused.memberBody`),\n  action: canManage.value ? 'updatePayment' : null,\n  dismissible: false,\n  payInvoiceUrl: safeInvoiceUrl(renewalInvoice.value?.hosted_invoice_url)\n})\n\n// Sales-managed plans (Enterprise, and unrecognized tiers, which fail closed\n// to sales) return through sales; only a strict ENTERPRISE tier is named.\nfunction planEndedCopy(): {\n  title: string\n  ownerBody: string\n  memberBody: string\n} {\n  const date = planEndDate.value\n  if (audience.value === 'personal') {\n    const plan = planName.value\n    const body = t(`${bs}.planEnded.personalBody`)\n    return {\n      title: date\n        ? t(`${bs}.planEnded.personalTitle`, { plan, date })\n        : t(`${bs}.planEnded.personalTitleNoDate`, { plan }),\n      ownerBody: body,\n      memberBody: body\n    }\n  }\n  if (!isSalesManagedPlan.value) {\n    return {\n      title: date\n        ? t(`${bs}.planEnded.teamTitle`, { date })\n        : t('workspacePanel.members.endedTeamTitle'),\n      ownerBody: t(`${bs}.planEnded.teamBody`),\n      memberBody: t(`${bs}.planEnded.teamMemberBody`)\n    }\n  }\n  const named = isEndedEnterprisePlan.value\n  return {\n    title: date\n      ? t(`${bs}.planEnded.${named ? 'enterpriseTitle' : 'planTitle'}`, {\n          date\n        })\n      : t(\n          `workspacePanel.members.${named ? 'endedEnterpriseTitle' : 'endedPlanTitle'}`\n        ),\n    ownerBody: t(`${bs}.planEnded.${named ? 'enterpriseBody' : 'salesBody'}`),\n    memberBody: t(`${bs}.planEnded.salesMemberBody`)\n  }\n}\n\nconst planEndedView = (): BannerView => {\n  const copy = planEndedCopy()\n  const ownerAction =\n    audience.value !== 'personal' && isSalesManagedPlan.value\n      ? 'contactSales'\n      : 'resubscribe'\n  return {\n    muted: true,\n    title: copy.title,\n    body: canManage.value ? copy.ownerBody : copy.memberBody,\n    action: canManage.value ? ownerAction : null,\n    dismissible: true\n  }\n}\n\nconst outOfCreditsBody = (key: string, noDateKey: string): string =>\n  cycleResetDate.value ? t(key, { date: cycleResetDate.value }) : t(noDateKey)\n\n// An owner who cannot top up only reaches this once the plan has ended, which\n// the plan ended notice covers, so that case shows nothing.\nconst outOfCreditsView = (): BannerView | null => {\n  if (!canManage.value) {\n    return {\n      muted: false,\n      title: t(`${bs}.outOfCredits.title`),\n      body: outOfCreditsBody(\n        `${bs}.outOfCredits.memberBody`,\n        `${bs}.outOfCredits.memberBodyNoDate`\n      ),\n      action: null,\n      dismissible: true\n    }\n  }\n  if (!canTopUp.value) return null\n  return {\n    muted: false,\n    title: t(`${bs}.outOfCredits.title`),\n    body: outOfCreditsBody(\n      copy.value.outOfCreditsBody,\n      copy.value.outOfCreditsBodyNoDate\n    ),\n    action: 'addCredits',\n    dismissible: true\n  }\n}\n\n// An Enterprise contract renews through sales, not self-serve reactivation,\n// so it gets its own copy and never a Reactivate action — even where the\n// legacy rail would resolve canReactivatePlan true.\nconst enterpriseEndingView = (): BannerView => ({\n  muted: true,\n  title: t(`${bs}.ending.enterpriseTitle`, { date: planEndDate.value }),\n  body: canManage.value\n    ? t(`${bs}.ending.enterpriseBody`)\n    : t(`${bs}.ending.memberBody`),\n  action: canManage.value ? 'contactSales' : null,\n  dismissible: false\n})\n\nconst selfServeEndingView = (): BannerView => ({\n  muted: true,\n  title: t(copy.value.endingTitle, {\n    plan: planName.value,\n    date: planEndDate.value\n  }),\n  body: canManage.value\n    ? t(copy.value.endingBody)\n    : t(`${bs}.ending.memberBody`),\n  action: canManage.value && canReactivatePlan.value ? 'reactivate' : null,\n  dismissible: false\n})\n\nconst endingView = (): BannerView =>\n  isEnterprisePlan.value ? enterpriseEndingView() : selfServeEndingView()\n\nconst planChangeView = (): BannerView | null =>\n  canShowScheduledChange.value\n    ? {\n        muted: true,\n        title: t(`${bs}.planChange.title`, {\n          plan: scheduledPlanName.value,\n          date: longDate(scheduledChange.value?.effective_at)\n        }),\n        body: t(`${bs}.planChange.body`),\n        action: null,\n        dismissible: true\n      }\n    : null\n\n// Runs are already blocked on payment_failed, so it reads as paused.\nconst bannerViews: Record<BillingBannerKind, () => BannerView | null> = {\n  paused: pausedView,\n  paymentFailed: pausedView,\n  planEnded: planEndedView,\n  outOfCredits: outOfCreditsView,\n  ending: endingView,\n  planChange: planChangeView\n}\n\nconst banner = computed<BannerView | null>(() =>\n  kind.value && !isHiddenOnSection.value ? bannerViews[kind.value]() : null\n)\n\nfunction handleAddCredits() {\n  void showTopUpCreditsDialog()\n}\nfunction handleResubscribePlan() {\n  subscriptionDialog.show({\n    planMode: audience.value === 'personal' ? 'personal' : 'team',\n    reason: 'settings_billing_panel'\n  })\n}\nfunction handleContactSales() {\n  window.open(ENTERPRISE_URL, '_blank', 'noopener,noreferrer')\n}\nfunction handlePayInvoice(url: string) {\n  window.open(url, '_blank', 'noopener,noreferrer')\n}\nfunction handleUpdatePayment() {\n  void manageSubscription()\n}\n</script>\n","<template>\n  <div v-if=\"banner\" class=\"@container\">\n    <div\n      role=\"status\"\n      class=\"flex flex-col gap-3 rounded-2xl border border-interface-stroke/60 bg-base-background p-4 @2xl:flex-row @2xl:items-center @2xl:gap-2\"\n    >\n      <div class=\"flex min-w-0 flex-1 flex-col gap-1\">\n        <div class=\"flex items-center gap-2\">\n          <i\n            :class=\"\n              cn(\n                'size-4 shrink-0',\n                banner.muted\n                  ? 'icon-[lucide--circle-alert] text-muted-foreground'\n                  : 