\n      ownerBody: body,\n      memberBody: body\n    }\n  }\n  if (!isSalesManagedPlan.value) {\n    return {\n      title: date\n        ? t(`${bs}.planEnded.teamTitle`, { date })\n        : t('workspacePanel.members.endedTeamTitle'),\n      ownerBody: t(`${bs}.planEnded.teamBody`),\n      memberBody: t(`${bs}.planEnded.teamMemberBody`)\n    }\n  }\n  const named = isEndedEnterprisePlan.value\n  return {\n    title: date\n      ? t(`${bs}.planEnded.${named ? 'enterpriseTitle' : 'planTitle'}`, {\n          date\n        })\n      : t(\n          `workspacePanel.members.${named ? 'endedEnterpriseTitle' : 'endedPlanTitle'}`\n        ),\n    ownerBody: t(`${bs}.planEnded.${named ? 'enterpriseBody' : 'salesBody'}`),\n    memberBody: t(`${bs}.planEnded.salesMemberBody`)\n  }\n}\n\nconst planEndedView = (): BannerView => {\n  const copy = planEndedCopy()\n  const ownerAction =\n    audience.value !== 'personal' && isSalesManagedPlan.value\n      ? 'contactSales'\n      : 'resubscribe'\n  return {\n    muted: true,\n    title: copy.title,\n    body: canManage.value ? copy.ownerBody : copy.memberBody,\n    action: canManage.value ? ownerAction : null,\n    dismissible: true\n  }\n}\n\nconst outOfCreditsBody = (key: string, noDateKey: string): string =>\n  cycleResetDate.value ? t(key, { date: cycleResetDate.value }) : t(noDateKey)\n\n// An owner who cannot top up only reaches this once the plan has ended, which\n// the plan ended notice covers, so that case shows nothing.\nconst outOfCreditsView = (): BannerView | null => {\n  if (!canManage.value) {\n    return {\n      muted: false,\n      title: t(`${bs}.outOfCredits.title`),\n      body: outOfCreditsBody(\n        `${bs}.outOfCredits.memberBody`,\n        `${bs}.outOfCredits.memberBodyNoDate`\n      ),\n      action: null,\n      dismissible: true\n    }\n  }\n  if (!canTopUp.value) return null\n  return {\n    muted: false,\n    title: t(`${bs}.outOfCredits.title`),\n    body: outOfCreditsBody(\n      copy.value.outOfCreditsBody,\n      copy.value.outOfCreditsBodyNoDate\n    ),\n    action: 'addCredits',\n    dismissible: true\n  }\n}\n\n// An Enterprise contract renews through sales, not self-serve reactivation,\n// so it gets its own copy and never a Reactivate action — even where the\n// legacy rail would resolve canReactivatePlan true.\nconst enterpriseEndingView = (): BannerView => ({\n  muted: true,\n  title: t(`${bs}.ending.enterpriseTitle`, { date: planEndDate.value }),\n  body: canManage.value\n    ? t(`${bs}.ending.enterpriseBody`)\n    : t(`${bs}.ending.memberBody`),\n  action: canManage.value ? 'contactSales' : null,\n  dismissible: false\n})\n\nconst selfServeEndingView = (): BannerView => ({\n  muted: true,\n  title: t(copy.value.endingTitle, {\n    plan: planName.value,\n    date: planEndDate.value\n  }),\n  body: canManage.value\n    ? t(copy.value.endingBody)\n    : t(`${bs}.ending.memberBody`),\n  action: canManage.value && canReactivatePlan.value ? 'reactivate' : null,\n  dismissible: false\n})\n\nconst endingView = (): BannerView =>\n  isEnterprisePlan.value ? enterpriseEndingView() : selfServeEndingView()\n\nconst planChangeView = (): BannerView | null =>\n  canShowScheduledChange.value\n    ? {\n        muted: true,\n        title: t(`${bs}.planChange.title`, {\n          plan: scheduledPlanName.value,\n          date: longDate(scheduledChange.value?.effective_at)\n        }),\n        body: t(`${bs}.planChange.body`),\n        action: null,\n        dismissible: true\n      }\n    : null\n\n// Runs are already blocked on payment_failed, so it reads as paused.\nconst bannerViews: Record<BillingBannerKind, () => BannerView | null> = {\n  paused: pausedView,\n  paymentFailed: pausedView,\n  planEnded: planEndedView,\n  outOfCredits: outOfCreditsView,\n  ending: endingView,\n  planChange: planChangeView\n}\n\nconst banner = computed<BannerView | null>(() =>\n  kind.value && !isHiddenOnSection.value ? bannerViews[kind.value]() : null\n)\n\nfunction handleAddCredits() {\n  void showTopUpCreditsDialog()\n}\nfunction handleResubscribePlan() {\n  subscriptionDialog.show({\n    planMode: audience.value === 'personal' ? 'personal' : 'team',\n    reason: 'settings_billing_panel'\n  })\n}\nfunction handleContactSales() {\n  window.open(ENTERPRISE_URL, '_blank', 'noopener,noreferrer')\n}\nfunction handlePayInvoice(url: string) {\n  window.open(url, '_blank', 'noopener,noreferrer')\n}\nfunction handleUpdatePayment() {\n  void manageSubscription()\n}\n</script>\n","<template>\n  <section\n    class=\"flex min-h-0 grow flex-col gap-6 overflow-auto\"\n    aria-labelledby=\"partner-node-access-title\"\n    @scroll=\"handlePanelScroll\"\n  >\n    <h2 id=\"partner-node-access-title\" class=\"sr-only\">\n      {{ $t('workspacePanel.partnerNodes.title') }}\n    </h2>\n\n    <div\n      class=\"flex items-start gap-4 rounded-2xl border border-interface-stroke p-4 font-inter\"\n    >\n      <span class=\"shrink-0\" @click.prevent=\"requestAccessModeToggle\">\n        <Switch\n          :model-value=\"!isRestricted\"\n          readonly\n          :disabled=\"!isGated && (!canEditPolicy || isSaving)\"\n          :aria-label=\"$t('workspacePanel.partnerNodes.accessMode')\"\n          :class=\"\n            cn('transition-transform active:scale-90', isGated && 'opacity-60')\n          \"\n        />\n      </span>\n      <div class=\"min-w-0 flex-1\">\n        <div class=\"flex h-6 items-center gap-2\">\n          <p\n            class=\"m-0 text-sm leading-[normal] font-normal text-base-foreground\"\n          >\n            {{ $t('workspacePanel.partnerNodes.allowAll') }}\n          </p>\n          <span\n            v-if=\"isGated\"\n            class=\"rounded-full bg-secondary-background px-2 py-0.5 text-xs text-base-foreground\"\n          >\n            {{ $t('workspacePanel.partnerNodes.enterpriseBadge') }}\n          </span>\n        </div>\n        <p\n          v-if=\"isGated\"\n          class=\"m-0 mt-1 text-sm leading-[normal] font-normal text-muted-foreground\"\n        >\n          {{ $t('workspacePanel.partnerNodes.gatedHint') }}\n        </p>\n        <p\n          v-else-if=\"isPolicyLoaded && !isRestricted\"\n          class=\"m-0 mt-1 text-sm leading-[normal] font-normal text-muted-foreground\"\n        >\n          {{ $t('workspacePanel.partnerNodes.allowAllOnHint') }}\n        </p>\n        <p\n          v-else-if=\"isPolicyLoaded\"\n          class=\"m-0 mt-1 flex items-center gap-2 text-sm/4 font-normal text-muted-foreground\"\n        >\n          <i\n            class=\"icon-[lucide--circle-alert] size-4 shrink-0 text-warning-background\"\n            aria-hidden=\"true\"\n          />\n          <span>{{ $t('workspacePanel.partnerNodes.allowAllOffHint') }}</span>\n        </p>\n      </div>\n      <Button\n        v-if=\"isGated\"\n        variant=\"inverted\"\n        size=\"lg\"\n        class=\"shrink-0 self-center\"\n        @click=\"openEnterprisePage\"\n      >\n        {{ $t('workspacePanel.partnerNodes.contactUs') }}\n      </Button>\n    </div>\n\n    <p v-if=\"isReadOnly\" class=\"text-sm text-muted-foreground\">\n      {{ $t('workspacePanel.partnerNodes.ownerOnly') }}\n    </p>\n\n    <div\n      v-if=\"status === 'loading'\"\n      :aria-label=\"$t('workspacePanel.partnerNodes.loading')\"\n      class=\"space-y-3\"\n    >\n      <Skeleton class=\"h-10 w-full\" />\n      <Skeleton v-for=\"index in 5\" :key=\"index\" class=\"h-12 w-full\" />\n    </div>\n\n    <div\n      v-else-if=\"status === 'error'\"\n      role=\"alert\"\n      class=\"flex min-h-48 flex-col items-center justify-center gap-3 rounded-2xl border border-interface-stroke p-6 text-center\"\n    >\n      <p class=\"text-sm text-muted-foreground\">\n        {{ $t('workspacePanel.partnerNodes.loadError') }}\n      </p>\n      <Button variant=\"secondary\" @click=\"loadPolicy\">\n        {{ $t('workspacePanel.partnerNodes.retry') }}\n      </Button>\n    </div>\n\n    <div\n      v-else-if=\"(status === 'ineligible' && !isGated) || status === 'inactive'\"\n      role=\"status\"\n      class=\"flex min-h-48 items-center justify-center rounded-2xl border border-interface-stroke p-6 text-center\"\n    >\n      <p class=\"text-sm text-muted-foreground\">\n        {{ $t('workspacePanel.partnerNodes.unavailable') }}\n      </p>\n    </div>\n\n    <template v-else>\n      <div class=\"flex flex-wrap items-center justify-between gap-3\">\n        <label class=\"w-full max-w-64\">\n          <span class=\"sr-only\">\n            {{ $t('workspacePanel.partnerNodes.searchPlaceholder') }}\n          </span>\n          <SearchInput\n            v-model=\"searchQuery\"\n            :placeholder=\"$t('workspacePanel.partnerNodes.searchPlaceholder')\"\n            size=\"lg\"\n            class=\"w-full\"\n          />\n        </label>\n        <Menu v-if=\"isRestricted\" :items=\"bulkMenuEntries\" :modal=\"false\">\n          <template #trigger>\n            <Button\n              variant=\"secondary\"\n              size=\"lg\"\n              :disabled=\"isSaving || !canEditPolicy\"\n            >\n              {{ $t('workspacePanel.partnerNodes.disableAll') }}\n              <i\n                class=\"icon-[lucide--chevron-down] size-4\"\n                aria-hidden=\"true\"\n              />\n            </Button>\n          </template>\n        </Menu>\n      </div>\n\n      <p\n        v-if=\"saveError\"\n        role=\"alert\"\n        class=\"rounded-lg bg-destructive-background/10 px-4 py-3 text-sm text-destructive-background\"\n      >\n        {{ $t('workspacePanel.partnerNodes.saveError') }}\n      </p>\n\n      <div\n        role=\"table\"\n        :aria-label=\"$t('workspacePanel.partnerNodes.tableLabel')\"\n        class=\"flex min-h-0 grow flex-col rounded-2xl border border-interface-stroke px-4 py-3\"\n      >\n        <div class=\"min-h-0 grow scrollbar-gutter-stable overflow-y-auto\">\n          <div\n            role=\"row\"\n            :class=\"\n              cn(\n                'sticky -top-px z-10 grid h-10 items-center gap-2 border-b border-border-default bg-base-background px-2 text-sm text-muted-foreground',\n                rowGridClass\n              )\n            \"\n          >\n            <span\n              role=\"columnheader\"\n              :aria-sort=\"sortField === 'provider' ? sortDirection : 'none'\"\n            >\n              <Button\n                variant=\"textonly\"\n                size=\"unset\"\n                class=\"-m-2 gap-2 p-2 text-sm font-normal text-muted-foreground\"\n                @click=\"sortBy('provider')\"\n              >\n                {{ $t('workspacePanel.partnerNodes.columns.provider') }}\n                <i\n                  :class=\"\n                    cn('size-4 transition-transform', sortIcon('provider'))\n                  \"\n                  aria-hidden=\"true\"\n                />\n              </Button>\n            </span>\n            <span\n              role=\"columnheader\"\n              :aria-sort=\"sortField === 'models' ? sortDirection : 'none'\"\n              class=\"hidden lg:block\"\n            >\n              <Button\n                variant=\"textonly\"\n                size=\"unset\"\n                class=\"-m-2 gap-2 p-2 text-sm font-normal text-muted-foreground\"\n                @click=\"sortBy('models')\"\n              >\n                {{ $t('workspacePanel.partnerNodes.columns.models') }}\n                <i\n                  :class=\"cn('size-4 transition-transform', sortIcon('models'))\"\n                  aria-hidden=\"true\"\n                />\n              </Button>\n            </span>\n            <span\n              role=\"columnheader\"\n              :aria-sort=\"sortField === 'state' ? sortDirection : 'none'\"\n              class=\"hidden lg:flex lg:justify-end\"\n            >\n              <Button\n                v-if=\"isRestricted\"\n                variant=\"textonly\"\n                size=\"unset\"\n                class=\"-m-2 gap-2 p-2 text-sm font-normal text-muted-foreground\"\n                @click=\"sortBy('state')\"\n              >\n                {{ $t('workspacePanel.partnerNodes.columns.state') }}\n                <i\n                  :class=\"cn('size-4 transition-transform', sortIcon('state'))\"\n                  aria-hidden=\"true\"\n                />\n              </Button>\n            </span>\n          </div>\n\n          <template v-for=\"provider in sortedProviders\" :key=\"provider.id\">\n            <div\n              role=\"row\"\n              :class=\"\n                cn(\n                  'grid h-10 items-center gap-2 border-b border-secondary-background px-2 last:border-b-0 hover:bg-secondary-background/40',\n                  rowGridClass\n                )\n              \"\n            >\n              <div role=\"cell\" class=\"min-w-0\">\n                <Button\n                  variant=\"textonly\"\n                  size=\"unset\"\n                  class=\"h-10 w-full justify-start gap-2 p-0 text-left font-normal hover:bg-transparent\"\n                  :aria-expanded=\"isProviderExpanded(provider)\"\n                  @click=\"toggleExpanded(provider.id)\"\n                >\n                  <i\n                    :class=\"\n                      cn(\n                        'size-4 shrink-0 text-muted-foreground transition-transform',\n                        'icon-[lucide--chevron-down]',\n                        !isProviderExpanded(provider) && '-rotate-90'\n                      )\n                    \"\n                    aria-hidden=\"true\"\n                  />\n                  <span\n                    class=\"flex size-5 shrink-0 items-center justify-center rounded-full bg-interface-panel-hover-surface\"\n                    aria-hidden=\"true\"\n                  >\n                    <i\n                      :class=\"\n                        cn(\n                          getProviderIcon(\n                            provider.nodeCategories[0] ?? provider.displayName\n                          ),\n                          'size-3'\n                        )\n                      \"\n                    />\n                  </span>\n                  <span class=\"truncate\">{{ provider.displayName }}</span>\n                </Button>\n              </div>\n              <span\n                role=\"cell\"\n                class=\"hidden text-sm text-muted-foreground lg:block\"\n              >\n                {{\n                  provider.totalModelCount !== undefined &&\n                  provider.nodes.length < provider.totalModelCount\n                    ? $t(\n                        'workspacePanel.partnerNodes.matchedModelCount',\n                        {\n                          matched: provider.nodes.length,\n                          total: provider.totalModelCount\n                        },\n                        provider.nodes.length\n                      )\n                    : $t(\n                        'workspacePanel.partnerNodes.modelCount',\n                        provider.nodes.length\n                      )\n                }}\n              </span>\n              <div\n                role=\"cell\"\n                class=\"flex h-8 items-center justify-end justify-self-end\"\n              >\n                <Switch\n                  v-if=\"isRestricted\"\n                  :model-value=\"provider.enabled\"\n                  :disabled=\"isSaving || !canEditPolicy\"\n                  :aria-label=\"\n                    $t('workspacePanel.partnerNodes.toggleProvider', {\n                      provider: provider.displayName\n                    })\n                  \"\n                  class=\"transition-transform active:scale-90\"\n                  @update:model-value=\"saveProviderChange(provider.id, $event)\"\n                />\n              </div>\n            </div>\n\n            <div\n              v-for=\"node in isProviderExpanded(provider) ? provider.nodes : []\"\n              :key=\"node.id\"\n              role=\"row\"\n              :class=\"\n                cn(\n                  'grid h-10 items-center gap-2 border-b border-secondary-background px-2 text-sm last:border-b-0',\n                  rowGridClass\n                )\n              \"\n            >\n              <span role=\"cell\" class=\"truncate pl-17 text-muted-foreground\">\n                {{ node.name }}\n              </span>\n              <span role=\"cell\" class=\"hidden lg:block\" />\n              <span role=\"cell\" />\n            </div>\n          </template>\n\n          <div\n            v-if=\"sortedProviders.length === 0\"\n            class=\"flex min-h-40 items-center justify-center p-6 text-sm text-muted-foreground\"\n          >\n            {{ $t('workspacePanel.partnerNodes.noResults') }}\n          </div>\n        </div>\n\n        <div\n          v-if=\"sortedProviders.length > 0\"\n          class=\"mt-2 flex shrink-0 justify-end border-t border-border-default px-2 pt-3 text-sm text-base-foreground\"\n        >\n          <i18n-t\n            keypath=\"workspacePanel.partnerNodes.allowedSummary\"\n            tag=\"span\"\n            scope=\"global\"\n          >\n            <template #count>\n              <span class=\"font-bold\">{{\n                isRestricted\n                  ? enabledModelCount\n                  : $t('workspacePanel.partnerNodes.allowedSummaryAll')\n              }}</span>\n            </template>\n          </i18n-t>\n        </div>\n      </div>\n    </template>\n  </section>\n</template>\n\n<script setup lang=\"ts\">\nimport { useSettingsHeaderCollapse } from '@/platform/settings/composables/useSettingsHeaderCollapse'\nimport { storeToRefs } from 'pinia'\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport type { MenuItem } from '@/components/ui/menu/types'\n\nimport { showConfirmDialog } from '@/components/dialog/confirm/confirmDialog'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport SearchInput from '@/components/ui/search-input/SearchInput.vue'\nimport Skeleton from '@/components/ui/skeleton/Skeleton.vue'\nimport Switch from '@/components/ui/switch/Switch.vue'\nimport { useWorkspaceUI } from '@/platform/workspace/composables/useWorkspaceUI'\nimport { usePartnerNodeGovernanceStore } from '@/platform/workspace/stores/partnerNodeGovernanceStore'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport { getProviderIcon, getProviderName } from '@/utils/categoryUtil'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { handlePanelScroll } = useSettingsHeaderCollapse()\n\nconst governanceStore = usePartnerNodeGovernanceStore()\nconst { governedWorkspaceId, isSaving, policy, providers, status } =\n  storeToRefs(governanceStore)\nconst {\n  isProviderEnabled,\n  loadPolicy,\n  setAllProvidersEnabled,\n  setEnforcementEnabled,\n  setProviderEnabled,\n  setProvidersEnabled\n} = governanceStore\nconst nodeDefStore = useNodeDefStore()\nconst { nodeDefsByName } = storeToRefs(nodeDefStore)\nconst dialogStore = useDialogStore()\nconst { workspaceRole } = useWorkspaceUI()\nconst { t } = useI18n()\n\nconst searchQuery = ref('')\nconst isSearching = computed(() => searchQuery.value.trim().length > 0)\nconst expandedProviderIds = ref(new Set<string>())\nconst saveError = ref(false)\ntype SortDirection = 'ascending' | 'descending'\ntype SortField = 'provider' | 'models' | 'state'\n\nconst sortField = ref<SortField>('provider')\nconst sortDirection = ref<SortDirection>('ascending')\n\nconst isRestricted = computed(() => policy.value?.enforcementEnabled === true)\nconst isPolicyLoaded = computed(\n  () => status.value === 'configured' || status.value === 'unconfigured'\n)\nconst isGated = computed(\n  () => status.value === 'ineligible' && providers.value.length > 0\n)\nconst isReadOnly = computed(() => workspaceRole.value !== 'owner')\nconst canEditPolicy = computed(() => !isReadOnly.value && isPolicyLoaded.value)\n\nconst rowGridClass =\n  'grid-cols-[minmax(0,1fr)_2.5rem] lg:grid-cols-[minmax(0,1fr)_12rem_5rem]'\n\nconst providerRows = computed(() =>\n  providers.value\n    .filter(({ nodeCategories }) => nodeCategories.length > 0)\n    .map((provider) => {\n      const nodes = Object.values(nodeDefsByName.value)\n        .filter(\n          (nodeDef) =>\n            nodeDef.api_node &&\n            provider.nodeCategories.includes(getProviderName(nodeDef.category))\n        )\n        .map((nodeDef) => ({\n          id: nodeDef.name,\n          name: nodeDef.display_name || nodeDef.name\n        }))\n        .sort((a, b) => a.name.localeCompare(b.name))\n\n      return {\n        ...provider,\n        enabled: isProviderEnabled(provider.id),\n        nodes\n      }\n    })\n)\n\nconst enabledModelCount = computed(() =>\n  providerRows.value.reduce(\n    (total, { enabled, nodes }) => total + (enabled ? nodes.length : 0),\n    0\n  )\n)\n\ntype FilteredProvider = (typeof providerRows)['value'][number] & {\n  totalModelCount?: number\n}\n\nconst filteredProviders = computed<FilteredProvider[]>(() => {\n  const query = searchQuery.value.trim().toLocaleLowerCase()\n  if (!query) return providerRows.value\n\n  return providerRows.value.flatMap((provider): FilteredProvider[] => {\n    if (provider.displayName.toLocaleLowerCase().includes(query)) {\n      return [provider]\n    }\n\n    const nodes = provider.nodes.filter(({ name }) =>\n      name.toLocaleLowerCase().includes(query)\n    )\n    return nodes.length > 0\n      ? [{ ...provider, nodes, totalModelCount: provider.nodes.length }]\n      : []\n  })\n})\n\nconst bulkMenuEntries = computed<MenuItem[]>(() => {\n  const rows = filteredProviders.value\n  const providerIds = rows.map(({ id }) => id)\n  const locked = isSaving.value || !canEditPolicy.value || rows.length === 0\n\n  return [\n    {\n      label: isSearching.value\n        ? t('workspacePanel.partnerNodes.disableMatchingCount', rows.length)\n        : t('workspacePanel.partnerNodes.disableAllCount', rows.length),\n      disabled: locked || rows.every(({ enabled }) => !enabled),\n      command: () => handleBulkDisable(providerIds)\n    },\n    {\n      label: isSearching.value\n        ? t('workspacePanel.partnerNodes.enableMatchingCount', rows.length)\n        : t('workspacePanel.partnerNodes.enableAllCount', rows.length),\n      disabled: locked || rows.every(({ enabled }) => enabled),\n      command: () =>\n        void performSave(() => setProvidersEnabled(providerIds, true))\n    }\n  ]\n})\n\nconst sortedProviders = computed(() =>\n  [...filteredProviders.value].sort((a, b) => {\n    const result =\n      sortField.value === 'provider'\n        ? a.displayName.localeCompare(b.displayName)\n        : sortField.value === 'models'\n          ? a.nodes.length - b.nodes.length\n          : Number(a.enabled) - Number(b.enabled)\n    const directedResult =\n      sortDirection.value === 'ascending' ? result : -result\n    return directedResult || a.displayName.localeCompare(b.displayName)\n  })\n)\n\nfunction sortBy(field: SortField) {\n  if (sortField.value === field) {\n    sortDirection.value =\n      sortDirection.value === 'ascending' ? 'descending' : 'ascending'\n    return\n  }\n\n  sortField.value = field\n  sortDirection.value = field === 'provider' ? 'ascending' : 'descending'\n}\n\nfunction sortIcon(field: SortField) {\n  return cn(\n    sortField.value === field\n      ? 'icon-[lucide--arrow-down]'\n      : 'icon-[lucide--arrow-up-down]',\n    sortField.value === field &&\n      sortDirection.value === 'descending' &&\n      'rotate-180'\n  )\n}\n\nfunction toggleExpanded(providerId: string) {\n  const nextIds = new Set(expandedProviderIds.value)\n  if (nextIds.has(providerId)) nextIds.delete(providerId)\n  else nextIds.add(providerId)\n  expandedProviderIds.value = nextIds\n}\n\nfunction isProviderExpanded(provider: { id: string }) {\n  return expandedProviderIds.value.has(provider.id)\n}\n\nasync function performSave(action: () => Promise<void>) {\n  saveError.value = false\n  try {\n    await action()\n  } catch {\n    saveError.value = true\n  }\n}\n\nfunction saveProviderChange(providerId: string, enabled: boolean) {\n  void performSave(() => setProviderEnabled(providerId, enabled))\n}\n\nfunction handleBulkDisable(providerIds: string[]) {\n  if (isSearching.value) {\n    void performSave(() => setProvidersEnabled(providerIds, false))\n    return\n  }\n  confirmDisableAll()\n}\n\nfunction createPolicyConfirmationGuard() {\n  const sourceWorkspaceId = governedWorkspaceId.value\n  const sourcePolicy = policy.value\n  if (!sourceWorkspaceId) return null\n\n  return () =>\n    workspaceRole.value === 'owner' &&\n    governedWorkspaceId.value === sourceWorkspaceId &&\n    policy.value === sourcePolicy\n}\n\nfunction confirmDisableAll() {\n  const canConfirm = createPolicyConfirmationGuard()\n  if (!canConfirm) return\n\n  const dialog = showConfirmDialog({\n    headerProps: { title: t('workspacePanel.partnerNodes.disableAllTitle') },\n    props: { promptText: t('workspacePanel.partnerNodes.disableAllMessage') },\n    footerProps: {\n      confirmText: t('workspacePanel.partnerNodes.disableAll'),\n      confirmVariant: 'destructive',\n      optionsDisabled: isSaving,\n      onCancel: () => dialogStore.closeDialog(dialog),\n      onConfirm: async () => {\n        if (!canConfirm()) {\n          dialogStore.closeDialog(dialog)\n          return\n        }\n        await performSave(() => setAllProvidersEnabled(false))\n        dialogStore.closeDialog(dialog)\n      }\n    }\n  })\n}\n\nfunction requestAccessModeToggle() {\n  if (isGated.value) {\n    confirmEnterpriseUpsell()\n    return\n  }\n  if (!canEditPolicy.value || isSaving.value) return\n\n  const enabled = !isRestricted.value\n  confirmAccessModeChange(enabled, () => setEnforcementEnabled(enabled))\n}\n\nfunction openEnterprisePage() {\n  window.open('https://comfy.org/cloud/enterprise/', '_blank')\n}\n\nfunction confirmEnterpriseUpsell() {\n  const dialog = showConfirmDialog({\n    headerProps: {\n      title: t('workspacePanel.partnerNodes.gatedDialogTitle')\n    },\n    props: {\n      promptText: t('workspacePanel.partnerNodes.gatedDialogMessage')\n    },\n    footerProps: {\n      cancelText: t('workspacePanel.partnerNodes.notNow'),\n      confirmText: t('workspacePanel.partnerNodes.contactUs'),\n      confirmVariant: 'inverted',\n      onCancel: () => dialogStore.closeDialog(dialog),\n      onConfirm: () => {\n        openEnterprisePage()\n        dialogStore.closeDialog(dialog)\n      }\n    }\n  })\n}\n\nfunction confirmAccessModeChange(\n  enabled: boolean,\n  action: () => Promise<void>\n) {\n  const canConfirm = createPolicyConfirmationGuard()\n  if (!canConfirm) return\n\n  const key = enabled ? 'restrictAccess' : 'allowAllAccess'\n  const dialog = showConfirmDialog({\n    headerProps: {\n      title: t(`workspacePanel.partnerNodes.${key}Title`)\n    },\n    props: {\n      promptText: `${t(`workspacePanel.partnerNodes.${key}Message`)} ${t(\n        `workspacePanel.partnerNodes.${key}Hint`\n      )}`\n    },\n    footerProps: {\n      confirmText: t('g.confirm'),\n      confirmVariant: 'secondary',\n      optionsDisabled: isSaving,\n      onCancel: () => dialogStore.closeDialog(dialog),\n      onConfirm: async () => {\n        if (!canConfirm()) {\n          dialogStore.closeDialog(dialog)\n          return\n        }\n        await performSave(action)\n        dialogStore.closeDialog(dialog)\n      }\n    }\n  })\n}\n</script>\n","<template>\n  <section\n    class=\"flex min-h-0 grow flex-col gap-6 overflow-auto\"\n    aria-labelledby=\"partner-node-access-title\"\n    @scroll=\"handlePanelScroll\"\n  >\n    <h2 id=\"partner-node-access-title\" class=\"sr-only\">\n      {{ $t('workspacePanel.partnerNodes.title') }}\n    </h2>\n\n    <div\n      class=\"flex items-start gap-4 rounded-2xl border border-interface-stroke p-4 font-inter\"\n    >\n      <span class=\"shrink-0\" @click.prevent=\"requestAccessModeToggle\">\n        <Switch\n          :model-value=\"!isRestricted\"\n          readonly\n          :disabled=\"!isGated && (!canEditPolicy || isSaving)\"\n          :aria-label=\"$t('workspacePanel.partnerNodes.accessMode')\"\n          :class=\"\n            cn('transition-transform active:scale-90', isGated && 'opacity-60')\n          \"\n        />\n      </span>\n      <div class=\"min-w-0 flex-1\">\n        <div class=\"flex h-6 items-center gap-2\">\n          <p\n            class=\"m-0 text-sm leading-[normal] font-normal text-base-foreground\"\n          >\n            {{ $t('workspacePanel.partnerNodes.allowAll') }}\n          </p>\n          <span\n            v-if=\"isGated\"\n            class=\"rounded-full bg-secondary-background px-2 py-0.5 text-xs text-base-foreground\"\n          >\n            {{ $t('workspacePanel.partnerNodes.enterpriseBadge') }}\n          </span>\n        </div>\n        <p\n          v-if=\"isGated\"\n          class=\"m-0 mt-1 text-sm leading-[normal] font-normal text-muted-foreground\"\n        >\n          {{ $t('workspacePanel.partnerNodes.gatedHint') }}\n        </p>\n        <p\n          v-else-if=\"isPolicyLoaded && !isRestricted\"\n          class=\"m-0 mt-1 text-sm leading-[normal] font-normal text-muted-foreground\"\n        >\n          {{ $t('workspacePanel.partnerNodes.allowAllOnHint') }}\n        </p>\n        <p\n          v-else-if=\"isPolicyLoaded\"\n          class=\"m-0 mt-1 flex items-center gap-2 text-sm/4 font-normal text-muted-foreground\"\n        >\n          <i\n            class=\"icon-[lucide--circle-alert] size-4 shrink-0 text-warning-background\"\n            aria-hidden=\"true\"\n          />\n          <span>{{ $t('workspacePanel.partnerNodes.allowAllOffHint') }}</span>\n        </p>\n      </div>\n      <Button\n        v-if=\"isGated\"\n        variant=\"inverted\"\n        size=\"lg\"\n        class=\"shrink-0 self-center\"\n        @click=\"openEnterprisePage\"\n      >\n        {{ $t('workspacePanel.partnerNodes.contactUs') }}\n      </Button>\n    </div>\n\n    <p v-if=\"isReadOnly\" class=\"text-sm text-muted-foreground\">\n      {{ $t('workspacePanel.partnerNodes.ownerOnly') }}\n    </p>\n\n    <div\n      v-if=\"status === 'loading'\"\n      :aria-label=\"$t('workspacePanel.partnerNodes.loading')\"\n      class=\"space-y-3\"\n    >\n      <Skeleton class=\"h-10 w-full\" />\n      <Skeleton v-for=\"index in 5\" :key=\"index\" class=\"h-12 w-full\" />\n    </div>\n\n    <div\n      v-else-if=\"status === 'error'\"\n      role=\"alert\"\n      class=\"flex min-h-48 flex-col items-center justify-center gap-3 rounded-2xl border border-interface-stroke p-6 text-center\"\n    >\n      <p class=\"text-sm text-muted-foreground\">\n        {{ $t('workspacePanel.partnerNodes.loadError') }}\n      </p>\n      <Button variant=\"secondary\" @click=\"loadPolicy\">\n        {{ $t('workspacePanel.partnerNodes.retry') }}\n      </Button>\n    </div>\n\n    <div\n      v-else-if=\"(status === 'ineligible' && !isGated) || status === 'inactive'\"\n      role=\"status\"\n      class=\"flex min-h-48 items-center justify-center rounded-2xl border border-interface-stroke p-6 text-center\"\n    >\n      <p class=\"text-sm text-muted-foreground\">\n        {{ $t('workspacePanel.partnerNodes.unavailable') }}\n      </p>\n    </div>\n\n    <template v-else>\n      <div class=\"flex flex-wrap items-center justify-between gap-3\">\n        <label class=\"w-full max-w-64\">\n          <span class=\"sr-only\">\n            {{ $t('workspacePanel.partnerNodes.searchPlaceholder') }}\n          </span>\n          <SearchInput\n            v-model=\"searchQuery\"\n            :placeholder=\"$t('workspacePanel.partnerNodes.searchPlaceholder')\"\n            size=\"lg\"\n            class=\"w-full\"\n          />\n        </label>\n        <Menu v-if=\"isRestricted\" :items=\"bulkMenuEntries\" :modal=\"false\">\n          <template #trigger>\n            <Button\n              variant=\"secondary\"\n              size=\"lg\"\n              :disabled=\"isSaving || !canEditPolicy\"\n            >\n              {{ $t('workspacePanel.partnerNodes.disableAll') }}\n              <i\n                class=\"icon-[lucide--chevron-down] size-4\"\n                aria-hidden=\"true\"\n              />\n            </Button>\n          </template>\n        </Menu>\n      </div>\n\n      <p\n        v-if=\"saveError\"\n        role=\"alert\"\n        class=\"rounded-lg bg-destructive-background/10 px-4 py-3 text-sm text-destructive-background\"\n      >\n        {{ $t('workspacePanel.partnerNodes.saveError') }}\n      </p>\n\n      <div\n        role=\"table\"\n        :aria-label=\"$t('workspacePanel.partnerNodes.tableLabel')\"\n        class=\"flex min-h-0 grow flex-col rounded-2xl border border-interface-stroke px-4 py-3\"\n      >\n        <div class=\"min-h-0 grow scrollbar-gutter-stable overflow-y-auto\">\n          <div\n            role=\"row\"\n            :class=\"\n              cn(\n                'sticky -top-px z-10 grid h-10 items-center gap-2 border-b border-border-default bg-base-background px-2 text-sm text-muted-foreground',\n                rowGridClass\n              )\n            \"\n          >\n            <span\n              role=\"columnheader\"\n              :aria-sort=\"sortField === 'provider' ? sortDirection : 'none'\"\n            >\n              <Button\n                variant=\"textonly\"\n                size=\"unset\"\n                class=\"-m-2 gap-2 p-2 text-sm font-normal text-muted-foreground\"\n                @click=\"sortBy('provider')\"\n              >\n                {{ $t('workspacePanel.partnerNodes.columns.provider') }}\n                <i\n                  :class=\"\n                    cn('size-4 transition-transform', sortIcon('provider'))\n                  \"\n                  aria-hidden=\"true\"\n                />\n              </Button>\n            </span>\n            <span\n              role=\"columnheader\"\n              :aria-sort=\"sortField === 'models' ? sortDirection : 'none'\"\n              class=\"hidden lg:block\"\n            >\n              <Button\n                variant=\"textonly\"\n                size=\"unset\"\n                class=\"-m-2 gap-2 p-2 text-sm font-normal text-muted-foreground\"\n                @click=\"sortBy('models')\"\n              >\n                {{ $t('workspacePanel.partnerNodes.columns.models') }}\n                <i\n                  :class=\"cn('size-4 transition-transform', sortIcon('models'))\"\n                  aria-hidden=\"true\"\n                />\n              </Button>\n            </span>\n            <span\n              role=\"columnheader\"\n              :aria-sort=\"sortField === 'state' ? sortDirection : 'none'\"\n              class=\"hidden lg:flex lg:justify-end\"\n            >\n              <Button\n                v-if=\"isRestricted\"\n                variant=\"textonly\"\n                size=\"unset\"\n                class=\"-m-2 gap-2 p-2 text-sm font-normal text-muted-foreground\"\n                @click=\"sortBy('state')\"\n              >\n                {{ $t('workspacePanel.partnerNodes.columns.state') }}\n                <i\n                  :class=\"cn('size-4 transition-transform', sortIcon('state'))\"\n                  aria-hidden=\"true\"\n                />\n              </Button>\n            </span>\n          </div>\n\n          <template v-for=\"provider in sortedProviders\" :key=\"provider.id\">\n            <div\n              role=\"row\"\n              :class=\"\n                cn(\n                  'grid h-10 items-center gap-2 border-b border-secondary-background px-2 last:border-b-0 hover:bg-secondary-background/40',\n                  rowGridClass\n                )\n              \"\n            >\n              <div role=\"cell\" class=\"min-w-0\">\n                <Button\n                  variant=\"textonly\"\n                  size=\"unset\"\n                  class=\"h-10 w-full justify-start gap-2 p-0 text-left font-normal hover:bg-transparent\"\n                  :aria-expanded=\"isProviderExpanded(provider)\"\n                  @click=\"toggleExpanded(provider.id)\"\n                >\n                  <i\n                    :class=\"\n                      cn(\n                        'size-4 shrink-0 text-muted-foreground transition-transform',\n                        'icon-[lucide--chevron-down]',\n                        !isProviderExpanded(provider) && '-rotate-90'\n                      )\n                    \"\n                    aria-hidden=\"true\"\n                  />\n                  <span\n                    class=\"flex size-5 shrink-0 items-center justify-center rounded-full bg-interface-panel-hover-surface\"\n                    aria-hidden=\"true\"\n                  >\n                    <i\n                      :class=\"\n                        cn(\n                          getProviderIcon(\n                            provider.nodeCategories[0] ?? provider.displayName\n                          ),\n                          'size-3'\n                        )\n                      \"\n                    />\n                  </span>\n                  <span class=\"truncate\">{{ provider.displayName }}</span>\n                </Button>\n              </div>\n              <span\n                role=\"cell\"\n                class=\"hidden text-sm text-muted-foreground lg:block\"\n              >\n                {{\n                  provider.totalModelCount !== undefined &&\n                  provider.nodes.length < provider.totalModelCount\n                    ? $t(\n                        'workspacePanel.partnerNodes.matchedModelCount',\n                        {\n                          matched: provider.nodes.length,\n                          total: provider.totalModelCount\n                        },\n                        provider.nodes.length\n                      )\n                    : $t(\n                        'workspacePanel.partnerNodes.modelCount',\n                        provider.nodes.length\n                      )\n                }}\n              </span>\n              <div\n                role=\"cell\"\n                class=\"flex h-8 items-center justify-end justify-self-end\"\n              >\n                <Switch\n                  v-if=\"isRestricted\"\n                  :model-value=\"provider.enabled\"\n                  :disabled=\"isSaving || !canEditPolicy\"\n                  :aria-label=\"\n                    $t('workspacePanel.partnerNodes.toggleProvider', {\n                      provider: provider.displayName\n                    })\n                  \"\n                  class=\"transition-transform active:scale-90\"\n                  @update:model-value=\"saveProviderChange(provider.id, $event)\"\n                />\n              </div>\n            </div>\n\n            <div\n              v-for=\"node in isProviderExpanded(provider) ? provider.nodes : []\"\n              :key=\"node.id\"\n              role=\"row\"\n              :class=\"\n                cn(\n                  'grid h-10 items-center gap-2 border-b border-secondary-background px-2 text-sm last:border-b-0',\n                  rowGridClass\n                )\n              \"\n            >\n              <span role=\"cell\" class=\"truncate pl-17 text-muted-foreground\">\n                {{ node.name }}\n              </span>\n              <span role=\"cell\" class=\"hidden lg:block\" />\n              <span role=\"cell\" />\n            </div>\n          </template>\n\n          <div\n            v-if=\"sortedProviders.length === 0\"\n            class=\"flex min-h-40 items-center justify-center p-6 text-sm text-muted-foreground\"\n          >\n            {{ $t('workspacePanel.partnerNodes.noResults') }}\n          </div>\n        </div>\n\n        <div\n          v-if=\"sortedProviders.length > 0\"\n          class=\"mt-2 flex shrink-0 justify-end border-t border-border-default px-2 pt-3 text-sm text-base-foreground\"\n        >\n          <i18n-t\n            keypath=\"workspacePanel.partnerNodes.allowedSummary\"\n            tag=\"span\"\n            scope=\"global\"\n          >\n            <template #count>\n              <span class=\"font-bold\">{{\n                isRestricted\n                  ? enabledModelCount\n                  : $t('workspacePanel.partnerNodes.allowedSummaryAll')\n              }}</span>\n            </template>\n          </i18n-t>\n        </div>\n      </div>\n    </template>\n  </section>\n</template>\n\n<script setup lang=\"ts\">\nimport { useSettingsHeaderCollapse } from '@/platform/settings/composables/useSettingsHeaderCollapse'\nimport { storeToRefs } from 'pinia'\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport type { MenuItem } from '@/components/ui/menu/types'\n\nimport { showConfirmDialog } from '@/components/dialog/confirm/confirmDialog'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport SearchInput from '@/components/ui/search-input/SearchInput.vue'\nimport Skeleton from '@/components/ui/skeleton/Skeleton.vue'\nimport Switch from '@/components/ui/switch/Switch.vue'\nimport { useWorkspaceUI } from '@/platform/workspace/composables/useWorkspaceUI'\nimport { usePartnerNodeGovernanceStore } from '@/platform/workspace/stores/partnerNodeGovernanceStore'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport { getProviderIcon, getProviderName } from '@/utils/categoryUtil'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { handlePanelScroll } = useSettingsHeaderCollapse()\n\nconst governanceStore = usePartnerNodeGovernanceStore()\nconst { governedWorkspaceId, isSaving, policy, providers, status } =\n  storeToRefs(governanceStore)\nconst {\n  isProviderEnabled,\n  loadPolicy,\n  setAllProvidersEnabled,\n  setEnforcementEnabled,\n  setProviderEnabled,\n  setProvidersEnabled\n} = governanceStore\nconst nodeDefStore = useNodeDefStore()\nconst { nodeDefsByName } = storeToRefs(nodeDefStore)\nconst dialogStore = useDialogStore()\nconst { workspaceRole } = useWorkspaceUI()\nconst { t } = useI18n()\n\nconst searchQuery = ref('')\nconst isSearching = computed(() => searchQuery.value.trim().length > 0)\nconst expandedProviderIds = ref(new Set<string>())\nconst saveError = ref(false)\ntype SortDirection = 'ascending' | 'descending'\ntype SortField = 'provider' | 'models' | 'state'\n\nconst sortField = ref<SortField>('provider')\nconst sortDirection = ref<SortDirection>('ascending')\n\nconst isRestricted = computed(() => policy.value?.enforcementEnabled === true)\nconst isPolicyLoaded = computed(\n  () => status.value === 'configured' || status.value === 'unconfigured'\n)\nconst isGated = computed(\n  () => status.value === 'ineligible' && providers.value.length > 0\n)\nconst isReadOnly = computed(() => workspaceRole.value !== 'owner')\nconst canEditPolicy = computed(() => !isReadOnly.value && isPolicyLoaded.value)\n\nconst rowGridClass =\n  'grid-cols-[minmax(0,1fr)_2.5rem] lg:grid-cols-[minmax(0,1fr)_12rem_5rem]'\n\nconst providerRows = computed(() =>\n  providers.value\n    .filter(({ nodeCategories }) => nodeCategories.length > 0)\n    .map((provider) => {\n      const nodes = Object.values(nodeDefsByName.value)\n        .filter(\n          (nodeDef) =>\n            nodeDef.api_node &&\n            provider.nodeCategories.includes(getProviderName(nodeDef.category))\n        )\n        .map((nodeDef) => ({\n          id: nodeDef.name,\n          name: nodeDef.display_name || nodeDef.name\n        }))\n        .sort((a, b) => a.name.localeCompare(b.name))\n\n      return {\n        ...provider,\n        enabled: isProviderEnabled(provider.id),\n        nodes\n      }\n    })\n)\n\nconst enabledModelCount = computed(() =>\n  providerRows.value.reduce(\n    (total, { enabled, nodes }) => total + (enabled ? nodes.length : 0),\n    0\n  )\n)\n\ntype FilteredProvider = (typeof providerRows)['value'][number] & {\n  totalModelCount?: number\n}\n\nconst filteredProviders = computed<FilteredProvider[]>(() => {\n  const query = searchQuery.value.trim().toLocaleLowerCase()\n  if (!query) return providerRows.value\n\n  return providerRows.value.flatMap((provider): FilteredProvider[] => {\n    if (provider.displayName.toLocaleLowerCase().includes(query)) {\n      return [provider]\n    }\n\n    const nodes = provider.nodes.filter(({ name }) =>\n      name.toLocaleLowerCase().includes(query)\n    )\n    return nodes.length > 0\n      ? [{ ...provider, nodes, totalModelCount: provider.nodes.length }]\n      : []\n  })\n})\n\nconst bulkMenuEntries = computed<MenuItem[]>(() => {\n  const rows = filteredProviders.value\n  const providerIds = rows.map(({ id }) => id)\n  const locked = isSaving.value || !canEditPolicy.value || rows.length === 0\n\n  return [\n    {\n      label: isSearching.value\n        ? t('workspacePanel.partnerNodes.disableMatchingCount', rows.length)\n        : t('workspacePanel.partnerNodes.disableAllCount', rows.length),\n      disabled: locked || rows.every(({ enabled }) => !enabled),\n      command: () => handleBulkDisable(providerIds)\n    },\n    {\n      label: isSearching.value\n        ? t('workspacePanel.partnerNodes.enableMatchingCount', rows.length)\n        : t('workspacePanel.partnerNodes.enableAllCount', rows.length),\n      disabled: locked || rows.every(({ enabled }) => enabled),\n      command: () =>\n        void performSave(() => setProvidersEnabled(providerIds, true))\n    }\n  ]\n})\n\nconst sortedProviders = computed(() =>\n  [...filteredProviders.value].sort((a, b) => {\n    const result =\n      sortField.value === 'provider'\n        ? a.displayName.localeCompare(b.displayName)\n        : sortField.value === 'models'\n          ? a.nodes.length - b.nodes.length\n          : Number(a.enabled) - Number(b.enabled)\n    const directedResult =\n      sortDirection.value === 'ascending' ? result : -result\n    return directedResult || a.displayName.localeCompare(b.displayName)\n  })\n)\n\nfunction sortBy(field: SortField) {\n  if (sortField.value === field) {\n    sortDirection.value =\n      sortDirection.value === 'ascending' ? 'descending' : 'ascending'\n    return\n  }\n\n  sortField.value = field\n  sortDirection.value = field === 'provider' ? 'ascending' : 'descending'\n}\n\nfunction sortIcon(field: SortField) {\n  return cn(\n    sortField.value === field\n      ? 'icon-[lucide--arrow-down]'\n      : 'icon-[lucide--arrow-up-down]',\n    sortField.value === field &&\n      sortDirection.value === 'descending' &&\n      'rotate-180'\n  )\n}\n\nfunction toggleExpanded(providerId: string) {\n  const nextIds = new Set(expandedProviderIds.value)\n  if (nextIds.has(providerId)) nextIds.delete(providerId)\n  else nextIds.add(providerId)\n  expandedProviderIds.value = nextIds\n}\n\nfunction isProviderExpanded(provider: { id: string }) {\n  return expandedProviderIds.value.has(provider.id)\n}\n\nasync function performSave(action: () => Promise<void>) {\n  saveError.value = false\n  try {\n    await action()\n  } catch {\n    saveError.value = true\n  }\n}\n\nfunction saveProviderChange(providerId: string, enabled: boolean) {\n  void performSave(() => setProviderEnabled(providerId, enabled))\n}\n\nfunction handleBulkDisable(providerIds: string[]) {\n  if (isSearching.value) {\n    void performSave(() => setProvidersEnabled(providerIds, false))\n    return\n  }\n  confirmDisableAll()\n}\n\nfunction createPolicyConfirmationGuard() {\n  const sourceWorkspaceId = governedWorkspaceId.value\n  const sourcePolicy = policy.value\n  if (!sourceWorkspaceId) return null\n\n  return () =>\n    workspaceRole.value === 'owner' &&\n    governedWorkspaceId.value === sourceWorkspaceId &&\n    policy.value === sourcePolicy\n}\n\nfunction confirmDisableAll() {\n  const canConfirm = createPolicyConfirmationGuard()\n  if (!canConfirm) return\n\n  const dialog = showConfirmDialog({\n    headerProps: { title: t('workspacePanel.partnerNodes.disableAllTitle') },\n    props: { promptText: t('workspacePanel.partnerNodes.disableAllMessage') },\n    footerProps: {\n      confirmText: t('workspacePanel.partnerNodes.disableAll'),\n      confirmVariant: 'destructive',\n      optionsDisabled: isSaving,\n      onCancel: () => dialogStore.closeDialog(dialog),\n      onConfirm: async () => {\n        if (!canConfirm()) {\n          dialogStore.closeDialog(dialog)\n          return\n        }\n        await performSave(() => setAllProvidersEnabled(false))\n        dialogStore.closeDialog(dialog)\n      }\n    }\n  })\n}\n\nfunction requestAccessModeToggle() {\n  if (isGated.value) {\n    confirmEnterpriseUpsell()\n    return\n  }\n  if (!canEditPolicy.value || isSaving.value) return\n\n  const enabled = !isRestricted.value\n  confirmAccessModeChange(enabled, () => setEnforcementEnabled(enabled))\n}\n\nfunction openEnterprisePage() {\n  window.open('https://comfy.org/cloud/enterprise/', '_blank')\n}\n\nfunction confirmEnterpriseUpsell() {\n  const dialog = showConfirmDialog({\n    headerProps: {\n      title: t('workspacePanel.partnerNodes.gatedDialogTitle')\n    },\n    props: {\n      promptText: t('workspacePanel.partnerNodes.gatedDialogMessage')\n    },\n    footerProps: {\n      cancelText: t('workspacePanel.partnerNodes.notNow'),\n      confirmText: t('workspacePanel.partnerNodes.contactUs'),\n      confirmVariant: 'inverted',\n      onCancel: () => dialogStore.closeDialog(dialog),\n      onConfirm: () => {\n        openEnterprisePage()\n        dialogStore.closeDialog(dialog)\n      }\n    }\n  })\n}\n\nfunction confirmAccessModeChange(\n  enabled: boolean,\n  action: () => Promise<void>\n) {\n  const canConfirm = createPolicyConfirmationGuard()\n  if (!canConfirm) return\n\n  const key = enabled ? 'restrictAccess' : 'allowAllAccess'\n  const dialog = showConfirmDialog({\n    headerProps: {\n      title: t(`workspacePanel.partnerNodes.${key}Title`)\n    },\n    props: {\n      promptText: `${t(`workspacePanel.partnerNodes.${key}Message`)} ${t(\n        `workspacePanel.partnerNodes.${key}Hint`\n      )}`\n    },\n    footerProps: {\n      confirmText: t('g.confirm'),\n      confirmVariant: 'secondary',\n      optionsDisabled: isSaving,\n      onCancel: () => dialogStore.closeDialog(dialog),\n      onConfirm: async () => {\n        if (!canConfirm()) {\n          dialogStore.closeDialog(dialog)\n          return\n        }\n        await performSave(action)\n        dialogStore.closeDialog(dialog)\n      }\n    }\n  })\n}\n</script>\n","import { onMounted, ref } from 'vue'\n\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { paymentIntentSourceForAddCreditsClick } from '@/platform/telemetry/utils/paymentIntentSource'\nimport { useBillingDialogs } from '@/composables/billing/useBillingDialogs'\nimport { useCommandStore } from '@/stores/commandStore'\n\n/**\n * Composable for handling subscription panel actions and loading states\n */\nexport function useSubscriptionActions() {\n  const { showTopUpCreditsDialog } = useBillingDialogs()\n  const commandStore = useCommandStore()\n  const telemetry = useTelemetry()\n  const { fetchBalance, fetchStatus } = useBillingContext()\n  const { wrapWithErrorHandlingAsync, toastErrorHandler } = useErrorHandling()\n\n  const isLoadingSupport = ref(false)\n\n  onMounted(() => {\n    void handleRefresh()\n  })\n\n  const handleAddApiCredits = () => {\n    telemetry?.trackAddApiCreditButtonClicked({\n      source: 'settings_billing_panel'\n    })\n    void showTopUpCreditsDialog({\n      source: paymentIntentSourceForAddCreditsClick('settings_billing_panel')\n    })\n  }\n\n  // A user who cannot reach support cannot tell us that they cannot reach\n  // support, so this failure has to report itself.\n  const reportSupportFailure = (error: unknown) => {\n    reportError(error, {\n      surface: 'billing',\n      errorType: 'contact_support_failed'\n    })\n    toastErrorHandler(error)\n  }\n\n  const handleMessageSupport = wrapWithErrorHandlingAsync(\n    async () => {\n      isLoadingSupport.value = true\n      telemetry?.trackHelpResourceClicked({\n        resource_type: 'help_feedback',\n        is_external: true,\n        source: 'subscription'\n      })\n      await commandStore.execute('Comfy.ContactSupport')\n    },\n    reportSupportFailure,\n    () => {\n      isLoadingSupport.value = false\n    }\n  )\n\n  const handleRefresh = async () => {\n    try {\n      await Promise.all([fetchBalance(), fetchStatus()])\n    } catch (error) {\n      console.error('[useSubscriptionActions] Error refreshing data:', error)\n    }\n  }\n\n  const handleLearnMoreClick = () => {\n    window.open('https://docs.comfy.org/get_started/cloud', '_blank')\n  }\n\n  return {\n    isLoadingSupport,\n    handleAddApiCredits,\n    handleMessageSupport,\n    handleRefresh,\n    handleLearnMoreClick\n  }\n}\n","<template>\n  <div class=\"flex items-center justify-between pt-3 pb-6\">\n    <div class=\"flex gap-2\">\n      <Button\n        v-if=\"showUsageActivity\"\n        variant=\"muted-textonly\"\n        class=\"text-xs text-text-secondary\"\n        @click=\"handleFullUsageActivity\"\n      >\n        <i class=\"pi pi-external-link text-xs text-text-secondary\" />\n        {{ $t('subscription.fullUsageActivity') }}\n      </Button>\n      <Button\n        v-if=\"showPlansLink\"\n        variant=\"muted-textonly\"\n        class=\"text-xs text-text-secondary\"\n        @click=\"$emit('viewPlans')\"\n      >\n        <i class=\"pi pi-external-link text-xs text-text-secondary\" />\n        {{ $t('subscription.plansAndPricing') }}\n      </Button>\n      <Button\n        variant=\"muted-textonly\"\n        class=\"text-xs text-text-secondary\"\n        @click=\"handleOpenPartnerNodesInfo\"\n      >\n        <i class=\"pi pi-question-circle text-xs text-text-secondary\" />\n        {{ $t('subscription.partnerNodesPricingTable') }}\n      </Button>\n      <Button\n        variant=\"muted-textonly\"\n        class=\"text-xs text-text-secondary\"\n        :loading=\"isLoadingSupport\"\n        @click=\"handleMessageSupport\"\n      >\n        <i class=\"pi pi-comment text-xs text-text-secondary\" />\n        {{ $t('subscription.messageSupport') }}\n      </Button>\n    </div>\n\n    <Button\n      v-if=\"!isCloud && showInvoiceHistory\"\n      variant=\"muted-textonly\"\n      class=\"text-xs text-text-secondary\"\n      @click=\"handleInvoiceHistory\"\n    >\n      {{ $t('subscription.invoiceHistory') }}\n      <i class=\"pi pi-external-link text-xs text-text-secondary\" />\n    </Button>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useExternalLink } from '@/composables/useExternalLink'\nimport { useSubscriptionActions } from '@/platform/cloud/subscription/composables/useSubscriptionActions'\nimport { isCloud } from '@/platform/distribution/types'\nimport { platformLink } from '@/platform/workspace/utils/platformLink'\n\nconst {\n  showInvoiceHistory = true,\n  showUsageActivity = true,\n  showPlansLink = false\n} = defineProps<{\n  showInvoiceHistory?: boolean\n  showUsageActivity?: boolean\n  showPlansLink?: boolean\n}>()\n\ndefineEmits<{ viewPlans: [] }>()\n\nconst { buildDocsUrl, docsPaths } = useExternalLink()\n\nconst { manageSubscription } = useBillingContext()\n\nconst { isLoadingSupport, handleMessageSupport } = useSubscriptionActions()\n\nasync function handleInvoiceHistory() {\n  if (!showInvoiceHistory) return\n  await manageSubscription()\n}\n\nfunction handleFullUsageActivity() {\n  window.open(platformLink('/profile/usage'), '_blank', 'noopener')\n}\n\nfunction handleOpenPartnerNodesInfo() {\n  window.open(\n    buildDocsUrl(docsPaths.partnerNodesPricing, { includeLocale: true }),\n    '_blank'\n  )\n}\n</script>\n","<template>\n  <div class=\"flex items-center justify-between pt-3 pb-6\">\n    <div class=\"flex gap-2\">\n      <Button\n        v-if=\"showUsageActivity\"\n        variant=\"muted-textonly\"\n        class=\"text-xs text-text-secondary\"\n        @click=\"handleFullUsageActivity\"\n      >\n        <i class=\"pi pi-external-link text-xs text-text-secondary\" />\n        {{ $t('subscription.fullUsageActivity') }}\n      </Button>\n      <Button\n        v-if=\"showPlansLink\"\n        variant=\"muted-textonly\"\n        class=\"text-xs text-text-secondary\"\n        @click=\"$emit('viewPlans')\"\n      >\n        <i class=\"pi pi-external-link text-xs text-text-secondary\" />\n        {{ $t('subscription.plansAndPricing') }}\n      </Button>\n      <Button\n        variant=\"muted-textonly\"\n        class=\"text-xs text-text-secondary\"\n        @click=\"handleOpenPartnerNodesInfo\"\n      >\n        <i class=\"pi pi-question-circle text-xs text-text-secondary\" />\n        {{ $t('subscription.partnerNodesPricingTable') }}\n      </Button>\n      <Button\n        variant=\"muted-textonly\"\n        class=\"text-xs text-text-secondary\"\n        :loading=\"isLoadingSupport\"\n        @click=\"handleMessageSupport\"\n      >\n        <i class=\"pi pi-comment text-xs text-text-secondary\" />\n        {{ $t('subscription.messageSupport') }}\n      </Button>\n    </div>\n\n    <Button\n      v-if=\"!isCloud && showInvoiceHistory\"\n      variant=\"muted-textonly\"\n      class=\"text-xs text-text-secondary\"\n      @click=\"handleInvoiceHistory\"\n    >\n      {{ $t('subscription.invoiceHistory') }}\n      <i class=\"pi pi-external-link text-xs text-text-secondary\" />\n    </Button>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useExternalLink } from '@/composables/useExternalLink'\nimport { useSubscriptionActions } from '@/platform/cloud/subscription/composables/useSubscriptionActions'\nimport { isCloud } from '@/platform/distribution/types'\nimport { platformLink } from '@/platform/workspace/utils/platformLink'\n\nconst {\n  showInvoiceHistory = true,\n  showUsageActivity = true,\n  showPlansLink = false\n} = defineProps<{\n  showInvoiceHistory?: boolean\n  showUsageActivity?: boolean\n  showPlansLink?: boolean\n}>()\n\ndefineEmits<{ viewPlans: [] }>()\n\nconst { buildDocsUrl, docsPaths } = useExternalLink()\n\nconst { manageSubscription } = useBillingContext()\n\nconst { isLoadingSupport, handleMessageSupport } = useSubscriptionActions()\n\nasync function handleInvoiceHistory() {\n  if (!showInvoiceHistory) return\n  await manageSubscription()\n}\n\nfunction handleFullUsageActivity() {\n  window.open(platformLink('/profile/usage'), '_blank', 'noopener')\n}\n\nfunction handleOpenPartnerNodesInfo() {\n  window.open(\n    buildDocsUrl(docsPaths.partnerNodesPricing, { includeLocale: true }),\n    '_blank'\n  )\n}\n</script>\n","import {\n  getTierCredits,\n  getTierFeatures\n} from '@/platform/cloud/subscription/constants/tierPricing'\nimport type { TierKey } from '@/platform/cloud/subscription/constants/tierPricing'\n\ntype BenefitType = 'metric' | 'feature'\n\nexport interface TierBenefit {\n  key: string\n  type: BenefitType\n  label: string\n  value?: string\n}\n\nexport function getCommonTierBenefits(\n  key: TierKey,\n  t: (key: string, params?: Record<string, unknown>) => string,\n  n: (value: number) => string\n): TierBenefit[] {\n  const benefits: TierBenefit[] = []\n  const isFree = key === 'free'\n\n  if (isFree) {\n    const credits = getTierCredits(key)\n    if (credits) {\n      benefits.push({\n        key: 'monthlyCredits',\n        type: 'metric',\n        value: n(credits),\n        label: t('subscription.monthlyCreditsLabel')\n      })\n    }\n  }\n\n  benefits.push({\n    key: 'maxDuration',\n    type: 'metric',\n    value: t(`subscription.maxDuration.${key}`),\n    label: t('subscription.maxDurationLabel')\n  })\n\n  benefits.push({\n    key: 'gpu',\n    type: 'feature',\n    label: t('subscription.gpuLabel')\n  })\n\n  if (!isFree) {\n    benefits.push({\n      key: 'addCredits',\n      type: 'feature',\n      label: t('subscription.addCreditsLabel')\n    })\n  }\n\n  if (getTierFeatures(key).customLoRAs) {\n    benefits.push({\n      key: 'customLoRAs',\n      type: 'feature',\n      label: t('subscription.customLoRAsLabel')\n    })\n  }\n\n  return benefits\n}\n","import { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport type { MenuItem } from '@/components/ui/menu/types'\n\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useBillingRouting } from '@/composables/billing/useBillingRouting'\nimport { isSalesManagedTier } from '@/platform/cloud/subscription/constants/tierPricing'\nimport { isCloud } from '@/platform/distribution/types'\nimport { formatSubscriptionDate } from '@/platform/workspace/components/subscriptionPanelWorkspace.logic'\nimport { useBillingCapabilities } from '@/platform/workspace/composables/useBillingCapabilities'\nimport { useWorkspaceUI } from '@/platform/workspace/composables/useWorkspaceUI'\nimport { useBillingDialogs } from '@/composables/billing/useBillingDialogs'\nimport { useWorkspaceDialogs } from '@/platform/workspace/composables/useWorkspaceDialogs'\n\n/**\n * Builds the Plan & Credits overflow-menu model for the workspace subscription\n * panel. Visibility and the Delete enable/disable policy are derived from the\n * shared useWorkspaceUI state so this menu can't desync with the sibling\n * Plan & Credits panel menu.\n */\nexport function useWorkspaceMenuItems() {\n  const { t, locale } = useI18n()\n  const { billingStatus, isFreeTier, subscription } = useBillingContext()\n  const { shouldUseWorkspaceBilling } = useBillingRouting()\n  const { canCancel } = useBillingCapabilities()\n  const {\n    permissions,\n    uiConfig,\n    isInPersonalWorkspace,\n    canAccessSubscriptionFeatures,\n    isSubscriptionCancelled,\n    isDeleteDisabled,\n    deleteDisabledTooltipKey\n  } = useWorkspaceUI()\n  const { showCancelSubscriptionFlow } = useBillingDialogs()\n  const {\n    showEditWorkspaceDialog,\n    showDeleteWorkspaceDialog,\n    showLeaveWorkspaceDialog\n  } = useWorkspaceDialogs()\n\n  function editWorkspace() {\n    void showEditWorkspaceDialog()\n  }\n\n  function cancelSubscription() {\n    if (isCloud && shouldUseWorkspaceBilling.value && !canCancel.value) return\n    if (!canCancelPlan.value) return\n    void showCancelSubscriptionFlow(subscription.value?.endDate ?? undefined)\n  }\n\n  function deleteWorkspace() {\n    if (\n      !permissions.value.canManageSubscription ||\n      isInPersonalWorkspace.value ||\n      isDeleteDisabled.value\n    ) {\n      return\n    }\n    void showDeleteWorkspaceDialog()\n  }\n\n  function leaveWorkspace() {\n    if (!permissions.value.canLeaveWorkspace) return\n    void showLeaveWorkspaceDialog()\n  }\n\n  const canCancelPlan = computed(() => {\n    // can_cancel already encodes role, subscription presence/status and a\n    // scheduled cancellation, but not tier: it stays true for an active FREE\n    // plan, so the free-tier guard has to remain client-side.\n    if (isCloud && shouldUseWorkspaceBilling.value)\n      return canCancel.value && !isFreeTier.value\n    return (\n      permissions.value.canManageSubscriptionLifecycle &&\n      (canAccessSubscriptionFeatures.value ||\n        ((billingStatus.value === 'payment_failed' ||\n          billingStatus.value === 'paused') &&\n          Boolean(subscription.value?.planSlug))) &&\n      !isSubscriptionCancelled.value &&\n      !isFreeTier.value &&\n      !isSalesManagedTier(subscription.value?.tier)\n    )\n  })\n\n  // Deleting a workspace requires cancelling its plan first, and an Enterprise\n  // plan only ends through sales — so Delete would be a permanently disabled\n  // dead end. Hidden entirely per DES-782.\n  const canDeleteWorkspace = computed(\n    () =>\n      permissions.value.canManageSubscription &&\n      !isInPersonalWorkspace.value &&\n      subscription.value?.tier !== 'ENTERPRISE'\n  )\n\n  const deleteTooltip = computed(() => {\n    const planEndDate = formatSubscriptionDate(\n      subscription.value?.endDate,\n      locale.value\n    )\n    if (isDeleteDisabled.value && isSubscriptionCancelled.value && planEndDate)\n      return t('workspacePanel.menu.deleteWorkspaceAfterPlanEndsTooltip', {\n        date: planEndDate\n      })\n    const key = deleteDisabledTooltipKey.value\n    return key ? t(key) : undefined\n  })\n\n  const menuItems = computed<MenuItem[]>(() => {\n    const items: MenuItem[] = []\n\n    if (uiConfig.value.showEditWorkspaceMenuItem) {\n      items.push({\n        label: t('workspacePanel.menu.editWorkspace'),\n        command: editWorkspace\n      })\n    }\n\n    if (canCancelPlan.value) {\n      items.push({\n        label: t('subscription.cancelPlan'),\n        command: cancelSubscription\n      })\n    }\n\n    if (canDeleteWorkspace.value) {\n      items.push({\n        label: t('workspacePanel.menu.deleteWorkspace'),\n        class: isDeleteDisabled.value\n          ? 'data-disabled:cursor-not-allowed data-disabled:text-destructive-background/50 data-disabled:pointer-events-auto'\n          : 'text-destructive-background',\n        disabled: isDeleteDisabled.value,\n        tooltip: deleteTooltip.value,\n        command: isDeleteDisabled.value ? undefined : deleteWorkspace\n      })\n    }\n\n    if (permissions.value.canLeaveWorkspace) {\n      items.push({\n        label: t('workspacePanel.menu.leaveWorkspace'),\n        command: leaveWorkspace\n      })\n    }\n\n    return items\n  })\n\n  // Figma 3343-25140 renders a divider between every menu option.\n  const menuEntries = computed<MenuItem[]>(() =>\n    menuItems.value.flatMap((item, index) =>\n      index === 0 ? [item] : [{ separator: true }, item]\n    )\n  )\n\n  return { menuItems, menuEntries }\n}\n","import { computed, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport {\n  toTierKey,\n  getTierPrice\n} from '@/platform/cloud/subscription/constants/tierPricing'\nimport type { TierKey } from '@/platform/cloud/subscription/constants/tierPricing'\nimport { formatUsdCents } from '@/utils/numberUtil'\n\n/**\n * Resolves the price shown in the Plan & Credits header into a ready-to-render\n * string + unit label.\n *\n * Team pricing comes from the subscribed credit stop's per-month price (the\n * cycle `price_cents` is the authoritative recurring charge; `stop_usd` only\n * names the ladder rung). Both monthly and yearly stops are per-month figures.\n * When the subscribed stop id is absent from the resolved ladder the facade is\n * stale, so pricing warns and falls back to the per-member tier price rather\n * than silently mispricing an active plan.\n */\nexport function useWorkspacePlanPricing() {\n  const { t, locale } = useI18n()\n  const { subscription, teamCreditStops, currentTeamCreditStop, isTeamPlan } =\n    useBillingContext()\n\n  const isYearly = computed(() => subscription.value?.duration === 'ANNUAL')\n\n  // No subscription tier means an unsubscribed (Free) workspace; a present but\n  // unmapped tier falls back to the per-member standard price.\n  const tierKey = computed<TierKey>(() => {\n    const tier = subscription.value?.tier\n    if (!tier) return 'free'\n    return toTierKey(tier) ?? 'standard'\n  })\n\n  // A paid plan with no reported duration has no knowable per-month price.\n  // Free and Founders Edition prices do not depend on the cycle.\n  const isPriceCycleUnknown = computed(\n    () =>\n      !subscription.value?.duration &&\n      tierKey.value !== 'free' &&\n      tierKey.value !== 'founder'\n  )\n\n  const subscribedStop = computed(() => {\n    if (!isTeamPlan.value) return null\n    const id = currentTeamCreditStop.value?.id\n    const stops = teamCreditStops.value?.stops\n    if (!id || !stops) return null\n    return stops.find((stop) => stop.id === id) ?? null\n  })\n\n  const hasStaleCreditStop = computed(\n    () =>\n      !!currentTeamCreditStop.value &&\n      !!teamCreditStops.value &&\n      subscribedStop.value === null\n  )\n\n  const teamMonthlyCostCents = computed(() => {\n    const stop = subscribedStop.value\n    if (!stop) return null\n    return isYearly.value ? stop.yearly.price_cents : stop.monthly.price_cents\n  })\n\n  const displayPrice = computed(() => {\n    const cents =\n      teamMonthlyCostCents.value ??\n      getTierPrice(tierKey.value, isYearly.value) * 100\n    return formatUsdCents(locale.value, cents)\n  })\n\n  const priceUnitLabel = computed(() =>\n    teamMonthlyCostCents.value !== null || !isTeamPlan.value\n      ? t('subscription.usdPerMonth')\n      : t('subscription.usdPerMonthPerMember')\n  )\n\n  watch(hasStaleCreditStop, (isStale) => {\n    if (isStale) {\n      console.warn(\n        `Subscribed credit stop \"${currentTeamCreditStop.value?.id}\" not found in the resolved ladder; falling back to per-member pricing.`\n      )\n    }\n  })\n\n  return {\n    isPriceCycleUnknown,\n    displayPrice,\n    priceUnitLabel\n  }\n}\n","<template>\n  <div\n    class=\"flex grow flex-col overflow-auto pt-2\"\n    @scroll=\"handlePanelScroll\"\n  >\n    <!-- Loading state while subscription is being set up -->\n    <div\n      v-if=\"isSettingUp\"\n      class=\"rounded-2xl border border-interface-stroke p-6\"\n    >\n      <div class=\"flex items-center gap-2 py-4 text-muted-foreground\">\n        <i class=\"pi pi-spin pi-spinner\" />\n        <span>{{ $t('billingOperation.subscriptionProcessing') }}</span>\n      </div>\n      <Button\n        v-if=\"subscriptionActionUrl && permissions.canManageSubscription\"\n        variant=\"primary\"\n        size=\"lg\"\n        class=\"rounded-lg px-4 text-sm font-normal\"\n        @click=\"openSubscriptionVerification\"\n      >\n        {{ $t('subscription.preview.completeVerification') }}\n      </Button>\n    </div>\n\n    <!-- Billing data still loading: avoid rendering a false Free/$0 plan -->\n    <div\n      v-else-if=\"isLoading && !subscription\"\n      class=\"rounded-2xl border border-interface-stroke p-6\"\n    >\n      <div class=\"flex items-center gap-2 py-4 text-muted-foreground\">\n        <i class=\"pi pi-spin pi-spinner\" />\n        <span>{{ $t('g.loading') }}</span>\n      </div>\n    </div>\n\n    <!-- Billing fetch failed: offer retry rather than a misleading Free plan -->\n    <div\n      v-else-if=\"error && !subscription\"\n      class=\"flex flex-col items-start gap-3 rounded-2xl border border-interface-stroke p-6\"\n    >\n      <div class=\"flex items-center gap-2 text-text-secondary\">\n        <i class=\"pi pi-exclamation-circle text-destructive-background\" />\n        <span class=\"text-sm\">{{ $t('subscription.planLoadError') }}</span>\n      </div>\n      <Button\n        variant=\"secondary\"\n        size=\"lg\"\n        class=\"rounded-lg px-4 text-sm font-normal\"\n        :loading=\"isLoading\"\n        @click=\"handleRetry\"\n      >\n        {{ $t('subscription.planLoadErrorRetry') }}\n      </Button>\n    </div>\n\n    <template v-else>\n      <!-- Cancelled subscription info card -->\n      <div\n        v-if=\"showSubscriptionStateCard\"\n        data-testid=\"subscription-state-card\"\n        class=\"mb-6 flex gap-1 rounded-2xl border border-warning-background bg-warning-background/20 p-4\"\n      >\n        <div\n          class=\"flex size-8 shrink-0 items-center justify-center rounded-full text-warning-background\"\n        >\n          <i class=\"pi pi-info-circle\" />\n        </div>\n        <div class=\"flex flex-col gap-2\">\n          <h2 class=\"m-0 pt-1.5 text-sm font-bold text-text-primary\">\n            {{ subscriptionStateCardTitle }}\n          </h2>\n          <p class=\"m-0 text-sm text-text-secondary\">\n            {{ subscriptionStateCardDescription }}\n          </p>\n        </div>\n      </div>\n\n      <div class=\"rounded-2xl border border-interface-stroke p-6\">\n        <div>\n          <div\n            class=\"flex flex-col gap-4 md:flex-row md:items-center md:justify-between md:gap-2\"\n          >\n            <!-- OWNER Unsubscribed TEAM workspace -->\n            <template v-if=\"showTeamSubscribePrompt\">\n              <div class=\"flex flex-col gap-2\">\n                <h3\n                  :class=\"\n                    cn(\n                      'm-0 font-bold text-text-primary',\n                      showInactiveTeamSubscription ? 'text-base' : 'text-sm'\n                    )\n                  \"\n                >\n                  {{\n                    $t(\n                      showInactiveTeamSubscription\n                        ? 'subscription.inactiveTeamTitle'\n                        : 'subscription.workspaceNotSubscribed'\n                    )\n                  }}\n                </h3>\n                <div class=\"text-sm text-text-secondary\">\n                  {{\n                    $t(\n                      showInactiveTeamSubscription\n                        ? 'subscription.inactiveTeamDescription'\n                        : 'subscription.subscriptionRequiredMessage'\n                    )\n                  }}\n                </div>\n              </div>\n              <div class=\"flex flex-wrap gap-2 md:ml-auto\">\n                <Button\n                  v-if=\"\n                    permissions.canManageSubscription &&\n                    (isCloud || showInactiveTeamSubscription)\n                  \"\n                  size=\"lg\"\n                  variant=\"secondary\"\n                  class=\"rounded-lg bg-interface-menu-component-surface-selected px-4 text-sm font-normal text-text-primary\"\n                  @click=\"manageSubscription\"\n                >\n                  {{ $t('subscription.billingAndInvoices') }}\n                </Button>\n                <Button\n                  variant=\"primary\"\n                  size=\"lg\"\n                  class=\"rounded-lg px-4 py-2 text-sm font-normal\"\n                  @click=\"handleSubscribeWorkspace\"\n                >\n                  {{\n                    $t(\n                      showInactiveTeamSubscription\n                        ? 'subscription.reactivatePlan'\n                        : 'subscription.subscribeNow'\n                    )\n                  }}\n                </Button>\n                <Menu\n                  v-if=\"showInactiveTeamSubscription && menuEntries.length > 0\"\n                  :items=\"menuEntries\"\n                >\n                  <template #trigger>\n                    <Button\n                      :tooltip=\"$t('g.moreOptions')\"\n                      variant=\"secondary\"\n                      size=\"icon-lg\"\n                      icon=\"icon-[lucide--ellipsis]\"\n                      :aria-label=\"$t('g.moreOptions')\"\n                    />\n                  </template>\n                </Menu>\n              </div>\n            </template>\n\n            <!-- MEMBER View - read-only, workspace not subscribed -->\n            <template v-else-if=\"isMemberView\">\n              <div class=\"flex flex-col gap-2\">\n                <h3 class=\"m-0 text-sm font-bold text-text-primary\">\n                  {{ $t('subscription.workspaceNotSubscribed') }}\n                </h3>\n                <div class=\"text-sm text-text-secondary\">\n                  {{ $t('subscription.contactOwnerToSubscribe') }}\n                </div>\n              </div>\n            </template>\n\n            <!-- OWNER personal workspace without subscription (Free plan) -->\n            <template v-else-if=\"isPersonalFree\">\n              <div class=\"flex flex-col gap-2\">\n                <h3 class=\"m-0 text-base font-bold text-text-primary\">\n                  {{ $t('subscription.tiers.free.name') }}\n                </h3>\n                <div\n                  v-if=\"!isPriceCycleUnknown\"\n                  class=\"flex items-baseline gap-1 font-inter\"\n                >\n                  <span class=\"text-2xl font-semibold\">{{ displayPrice }}</span>\n                  <span class=\"text-base\">{{ priceUnitLabel }}</span>\n                </div>\n              </div>\n              <div class=\"flex flex-wrap gap-2 md:ml-auto\">\n                <Button\n                  v-if=\"isCloud && permissions.canManageSubscription\"\n                  size=\"lg\"\n                  variant=\"secondary\"\n                  class=\"rounded-lg bg-interface-menu-component-surface-selected px-4 text-sm font-normal text-text-primary\"\n                  @click=\"manageSubscription\"\n                >\n                  {{ $t('subscription.billingAndInvoices') }}\n                </Button>\n                <Button\n                  variant=\"primary\"\n                  size=\"lg\"\n                  class=\"rounded-lg px-4 text-sm font-normal\"\n                  @click=\"handleSubscribeWorkspace\"\n                >\n                  {{ $t('subscription.subscribe') }}\n                </Button>\n                <Menu v-if=\"menuEntries.length > 0\" :items=\"menuEntries\">\n                  <template #trigger>\n                    <Button\n                      :tooltip=\"$t('g.moreOptions')\"\n                      variant=\"secondary\"\n                      size=\"icon-lg\"\n                      icon=\"icon-[lucide--ellipsis]\"\n                      :aria-label=\"$t('g.moreOptions')\"\n                    />\n                  </template>\n                </Menu>\n              </div>\n            </template>\n\n            <!-- Normal Subscribed State (Owner with subscription, or member viewing subscribed workspace) -->\n            <template v-else>\n              <div class=\"flex flex-col gap-2\">\n                <div class=\"flex items-center gap-2\">\n                  <h3 class=\"m-0 text-base font-bold text-text-primary\">\n                    {{ planDisplayName }}\n                  </h3>\n                  <StatusBadge\n                    v-if=\"planStatusBadge\"\n                    data-testid=\"plan-status-badge\"\n                    :label=\"planStatusBadge.label\"\n                    :severity=\"planStatusBadge.severity\"\n                  />\n                </div>\n                <div\n                  v-if=\"!isNonCatalogPlan && !isPriceCycleUnknown\"\n                  class=\"flex items-baseline gap-1 font-inter\"\n                >\n                  <span class=\"text-2xl font-semibold\">{{ displayPrice }}</span>\n                  <span class=\"text-base\">{{ priceUnitLabel }}</span>\n                </div>\n                <div v-if=\"planDateDisplay\" class=\"text-sm text-text-secondary\">\n                  {{ planDateDisplay }}\n                </div>\n                <p\n                  v-if=\"isEndedEnterprise\"\n                  class=\"m-0 text-sm text-text-secondary\"\n                >\n                  {{ $t('subscription.inactiveEnterpriseDescription') }}\n                </p>\n              </div>\n\n              <div\n                v-if=\"\n                  canAccessSubscriptionFeatures ||\n                  (isCloud && permissions.canManageSubscription)\n                \"\n                class=\"flex flex-wrap gap-2 md:ml-auto\"\n              >\n                <Button\n                  v-if=\"\n                    permissions.canManageSubscription &&\n                    (isCloud || !isFreeTierPlan)\n                  \"\n                  size=\"lg\"\n                  variant=\"secondary\"\n                  class=\"rounded-lg bg-interface-menu-component-surface-selected px-4 text-sm font-normal text-text-primary\"\n                  @click=\"manageSubscription\"\n                >\n                  {{\n                    $t(\n                      isCloud\n                        ? 'subscription.billingAndInvoices'\n                        : 'subscription.manageBilling'\n                    )\n                  }}\n                </Button>\n                <!-- The server capability alone decides who may reactivate:\n                     hideLifecycleCapabilities closes this for sales-managed\n                     tiers (cloud common/billing/policy/capabilities.go). -->\n                <Button\n                  v-if=\"isSubscriptionCancelled && canReactivatePlan\"\n                  size=\"lg\"\n                  variant=\"primary\"\n                  class=\"rounded-lg px-4 text-sm font-normal\"\n                  :loading=\"isResubscribing\"\n                  @click=\"handleResubscribe\"\n                >\n                  {{ $t('subscription.reactivatePlan') }}\n                </Button>\n                <Button\n                  v-else-if=\"\n                    !isSubscriptionCancelled &&\n                    canAccessSubscriptionFeatures &&\n                    canChangePlan\n                  \"\n                  size=\"lg\"\n                  variant=\"secondary\"\n                  class=\"rounded-lg bg-interface-menu-component-surface-selected px-4 text-sm font-normal text-text-primary\"\n                  @click=\"handleUpgrade\"\n                >\n                  {{\n                    isInPersonalWorkspace && !isTeamPlan\n                      ? $t('subscription.upgradePlan')\n                      : $t('subscription.changePlan')\n                  }}\n                </Button>\n                <Menu v-if=\"menuEntries.length > 0\" :items=\"menuEntries\">\n                  <template #trigger>\n                    <Button\n                      :tooltip=\"$t('g.moreOptions')\"\n                      variant=\"secondary\"\n                      size=\"icon-lg\"\n                      icon=\"icon-[lucide--ellipsis]\"\n                      :aria-label=\"$t('g.moreOptions')\"\n                    />\n                  </template>\n                </Menu>\n              </div>\n            </template>\n          </div>\n        </div>\n\n        <div class=\"flex flex-col gap-6 pt-6 lg:flex-row lg:items-stretch\">\n          <div class=\"w-full lg:max-w-md\">\n            <CreditsTile\n              :zero-state=\"showZeroState\"\n              :inactive-plan=\"showInactiveTeamSubscription || isEndedEnterprise\"\n            />\n          </div>\n\n          <div\n            v-if=\"\n              !isNonCatalogPlan &&\n              (canAccessSubscriptionFeatures ||\n                isPersonalFree ||\n                showInactiveTeamSubscription)\n            \"\n            class=\"flex flex-col gap-2\"\n          >\n            <i18n-t\n              v-if=\"isTeamActive || showInactiveTeamSubscription\"\n              :keypath=\"\n                showInactiveTeamSubscription\n                  ? 'subscription.inactiveTeamPlanIncludes'\n                  : 'subscription.teamPlanIncludes'\n              \"\n              tag=\"div\"\n              class=\"text-sm text-muted\"\n            >\n              <template #plan>\n                <span class=\"text-text-primary\">\n                  {{ $t('subscription.tiers.pro.name') }}\n                </span>\n              </template>\n            </i18n-t>\n            <div v-else-if=\"isPersonalFree\" class=\"text-sm text-muted\">\n              {{ $t('subscription.whatsIncluded') }}\n            </div>\n            <div v-else class=\"text-sm text-text-primary\">\n              {{ $t('subscription.yourPlanIncludes') }}\n            </div>\n\n            <div class=\"flex flex-col gap-0\">\n              <div\n                v-for=\"benefit in tierBenefits\"\n                :key=\"benefit.key\"\n                class=\"flex items-center gap-2 py-2\"\n              >\n                <i\n                  v-if=\"benefit.type === 'feature'\"\n                  :class=\"\n                    cn(\n                      'pi pi-check text-xs',\n                      showInactiveTeamSubscription\n                        ? 'text-muted'\n                        : 'text-text-primary'\n                    )\n                  \"\n                />\n                <span\n                  v-else-if=\"benefit.type === 'metric' && benefit.value\"\n                  class=\"text-sm font-normal whitespace-nowrap text-text-primary\"\n                >\n                  {{ benefit.value }}\n                </span>\n                <span class=\"text-sm text-muted\">\n                  {{ benefit.label }}\n                </span>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <SubscriptionFooterLinks\n        class=\"mt-auto pt-6\"\n        :show-plans-link=\"canOpenPricingSurface\"\n        :show-invoice-history=\"permissions.canManageSubscription\"\n        :show-usage-activity=\"workspaceRole === 'owner'\"\n        @view-plans=\"handleViewMoreDetails\"\n      />\n    </template>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useSettingsHeaderCollapse } from '@/platform/settings/composables/useSettingsHeaderCollapse'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { useTimestamp } from '@vueuse/core'\nimport { storeToRefs } from 'pinia'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport CreditsTile from '@/platform/cloud/subscription/components/CreditsTile.vue'\nimport SubscriptionFooterLinks from '@/platform/cloud/subscription/components/SubscriptionFooterLinks.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport StatusBadge from '@/components/common/StatusBadge.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useSubscriptionDialog } from '@/platform/cloud/subscription/composables/useSubscriptionDialog'\nimport { useFreeTierQuota } from '@/platform/cloud/subscription/composables/useFreeTierQuota'\nimport {\n  isSalesManagedTier,\n  isWithinEnterpriseEndingNotice\n} from '@/platform/cloud/subscription/constants/tierPricing'\nimport type { TierBenefit } from '@/platform/cloud/subscription/utils/tierBenefits'\nimport { getCommonTierBenefits } from '@/platform/cloud/subscription/utils/tierBenefits'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useBillingBanner } from '@/platform/workspace/composables/useBillingBanner'\nimport { useResubscribe } from '@/platform/workspace/composables/useResubscribe'\nimport { useScheduledPlanChange } from '@/platform/workspace/composables/useScheduledPlanChange'\nimport { useBillingCapabilities } from '@/platform/workspace/composables/useBillingCapabilities'\nimport { useSubscriptionOperationView } from '@/platform/workspace/composables/useSubscriptionRail'\nimport { useWorkspaceMenuItems } from '@/platform/workspace/composables/useWorkspaceMenuItems'\nimport { useWorkspacePlanPricing } from '@/platform/workspace/composables/useWorkspacePlanPricing'\nimport { useWorkspaceUI } from '@/platform/workspace/composables/useWorkspaceUI'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport {\n  formatSubscriptionDate,\n  resolveSubscriptionTierKey\n} from './subscriptionPanelWorkspace.logic'\n\nconst { handlePanelScroll } = useSettingsHeaderCollapse()\n\nconst workspaceStore = useTeamWorkspaceStore()\nconst { isWorkspaceSubscribed, isInPersonalWorkspace } =\n  storeToRefs(workspaceStore)\nconst {\n  permissions,\n  isSubscriptionCancelled,\n  workspaceRole,\n  canReactivatePlan,\n  canOpenPricingSurface\n} = useWorkspaceUI()\nconst { canChangeSeats, canSubscribeSelfServe } = useBillingCapabilities()\nconst { maxAvailable: freeRunsAllowance, quotaEnabled: freeRunsQuotaEnabled } =\n  useFreeTierQuota()\nconst { t, n, locale } = useI18n()\n\nconst { isSettingUp, subscriptionActionUrl } = useSubscriptionOperationView()\n\nfunction openSubscriptionVerification() {\n  if (!subscriptionActionUrl.value) return\n  window.open(subscriptionActionUrl.value, '_blank', 'noopener,noreferrer')\n}\n\nconst {\n  canAccessSubscriptionFeatures,\n  isFreeTier: isFreeTierPlan,\n  isTeamPlan,\n  subscription,\n  billingStatus,\n  subscriptionStatus,\n  isLoading,\n  error,\n  showSubscriptionDialog,\n  manageSubscription,\n  initialize\n} = useBillingContext()\n\nconst { showPricingTable } = useSubscriptionDialog()\n\nconst { isResubscribing, handleResubscribe } = useResubscribe()\nconst { displayPrice, priceUnitLabel, isPriceCycleUnknown } =\n  useWorkspacePlanPricing()\nconst { menuEntries } = useWorkspaceMenuItems()\n\nconst isSubscriptionEnded = computed(() => {\n  if (subscriptionStatus.value === 'ended') return true\n  if (canAccessSubscriptionFeatures.value) return false\n  return (\n    isSubscriptionCancelled.value ||\n    (isInPersonalWorkspace.value && billingStatus.value === 'inactive')\n  )\n})\n\n// Show subscribe prompt to owners without active subscription. A cancelled plan\n// stays active until its end date, so it keeps the subscribed treatment.\nconst showSubscribePrompt = computed(() => {\n  if (\n    !(isCloud\n      ? canSubscribeSelfServe.value\n      : permissions.value.canManageSubscription)\n  )\n    return false\n  if (isSubscriptionEnded.value) return true\n  if (isSubscriptionCancelled.value) return false\n  if (\n    subscription.value &&\n    !isFreeTierPlan.value &&\n    (subscription.value.planSlug || subscription.value.tier)\n  )\n    return false\n  if (isInPersonalWorkspace.value) return !canAccessSubscriptionFeatures.value\n  return !isWorkspaceSubscribed.value\n})\n\nconst canChangePlan = computed(() =>\n  isCloud ? canChangeSeats.value : permissions.value.canManageSubscription\n)\n\n// The never-subscribed upsell is Cloud-only; on Local the policy table keeps\n// top-up available instead. An ended Team plan keeps its inactive treatment\n// everywhere so billing, invoices, and reactivation stay reachable.\nconst showTeamSubscribePrompt = computed(\n  () =>\n    showSubscribePrompt.value &&\n    !isInPersonalWorkspace.value &&\n    (isCloud || (isSubscriptionEnded.value && isTeamPlan.value))\n)\n\nconst showInactiveTeamSubscription = computed(\n  () =>\n    permissions.value.canManageSubscription &&\n    !isInPersonalWorkspace.value &&\n    isSubscriptionEnded.value &&\n    isTeamPlan.value\n)\n\nconst isPersonalFree = computed(\n  () =>\n    isInPersonalWorkspace.value &&\n    (showSubscribePrompt.value || isFreeTierPlan.value)\n)\n\nconst isTeamActive = computed(\n  () => isTeamPlan.value && canAccessSubscriptionFeatures.value\n)\n\nconst isMemberView = computed(\n  () =>\n    !permissions.value.canManageSubscription &&\n    !canAccessSubscriptionFeatures.value &&\n    !isWorkspaceSubscribed.value\n)\n\nconst showZeroState = computed(\n  () => showTeamSubscribePrompt.value || isMemberView.value\n)\n\nfunction handleSubscribeWorkspace() {\n  showSubscriptionDialog({ reason: 'settings_billing_panel' })\n}\n\nfunction handleUpgrade() {\n  if (isFreeTierPlan.value)\n    showPricingTable({ reason: 'settings_billing_panel' })\n  else showSubscriptionDialog({ reason: 'settings_billing_panel' })\n}\n\nfunction handleViewMoreDetails() {\n  window.open('https://comfy.org/cloud/pricing/', '_blank')\n}\n\nasync function handleRetry() {\n  await initialize()\n}\n\nconst isYearlySubscription = computed(\n  () => subscription.value?.duration === 'ANNUAL'\n)\n\nconst formattedRenewalDate = computed(() =>\n  formatSubscriptionDate(subscription.value?.renewalDate, locale.value)\n)\n\nconst formattedEndDate = computed(() =>\n  formatSubscriptionDate(subscription.value?.endDate, locale.value)\n)\n\nconst {\n  scheduledChange,\n  planName: scheduledPlanName,\n  formattedDate: formattedChangeDate\n} = useScheduledPlanChange()\n\nconst isNonCatalogPlan = computed(() =>\n  isSalesManagedTier(subscription.value?.tier)\n)\n\n// Strictly ENTERPRISE, not isSalesManagedTier: an unrecognized tier keeps the\n// stock cancelled treatment (isUnknownTier's contract — no borrowed claims).\nconst isEnterprisePlan = computed(\n  () => subscription.value?.tier === 'ENTERPRISE'\n)\n\nconst isEndedEnterprise = computed(\n  () => isEnterprisePlan.value && isSubscriptionEnded.value\n)\n\n// An Enterprise end date is an agreed ending — operator pilot term or\n// sales-mediated cancellation, deliberately not distinguished (see\n// deriveBillingBanner; decision on FE-2035) — often set months ahead. Only\n// its presence moves the plan onto the quiet path: no amber card or Canceled\n// badge at any point, and no \"Ends on\" line until the notice window.\n// Cancelled with no end date — or an unreadable one — falls back to the\n// stock treatment.\nconst hasScheduledEnterpriseEnd = computed(() => {\n  const endDate = subscription.value?.endDate\n  if (!isEnterprisePlan.value || !endDate) return false\n  return !Number.isNaN(Date.parse(endDate))\n})\n\n// Coarse shared clock so the notice window opens mid-session too.\nconst now = useTimestamp({ interval: 60_000 })\n\nconst isQuietEnterpriseEnding = computed(\n  () =>\n    hasScheduledEnterpriseEnd.value &&\n    !isWithinEnterpriseEndingNotice(subscription.value?.endDate, now.value)\n)\n\nconst { kind: billingBannerKind } = useBillingBanner()\n\n// An end-dated Enterprise plan never shows the amber card; inside the notice\n// window the muted ending banner carries the message instead. The banner is\n// still rolling out, so the card stays wherever the ending banner is not shown.\nconst showSubscriptionStateCard = computed(\n  () =>\n    isSubscriptionCancelled.value &&\n    !isSubscriptionEnded.value &&\n    !hasScheduledEnterpriseEnd.value &&\n    billingBannerKind.value !== 'ending'\n)\n\nconst subscriptionStateCardTitle = computed(() =>\n  t('subscription.canceledCard.title')\n)\n\nconst subscriptionStateCardDescription = computed(() =>\n  formattedEndDate.value\n    ? t('subscription.canceledCard.description', {\n        date: formattedEndDate.value\n      })\n    : t('subscription.canceledCard.descriptionWithoutDate')\n)\n\nconst planStatusBadge = computed(() => {\n  if (isSubscriptionEnded.value)\n    return {\n      label: t('subscription.inactive.badge'),\n      severity: 'secondary' as const\n    }\n  if (isSubscriptionCancelled.value && !hasScheduledEnterpriseEnd.value)\n    return { label: t('subscription.canceled'), severity: 'warn' as const }\n  return null\n})\n\nconst planDateDisplay = computed(() => {\n  if (!canAccessSubscriptionFeatures.value || isSubscriptionEnded.value)\n    return ''\n  if (isSubscriptionCancelled.value) {\n    if (isQuietEnterpriseEnding.value) return ''\n    return formattedEndDate.value\n      ? t('subscription.endsOnDate', { date: formattedEndDate.value })\n      : ''\n  }\n  if (scheduledChange.value) {\n    return scheduledPlanName.value && formattedChangeDate.value\n      ? t('subscription.changesToPlanOnDate', {\n          plan: scheduledPlanName.value,\n          date: formattedChangeDate.value\n        })\n      : ''\n  }\n  return formattedRenewalDate.value\n    ? t('subscription.renewsOnDate', { date: formattedRenewalDate.value })\n    : ''\n})\n\nconst subscriptionTierName = computed(() => {\n  const tier = subscription.value?.tier\n  if (!tier) return ''\n  const key = resolveSubscriptionTierKey(tier)\n  const baseName = t(`subscription.tiers.${key}.name`)\n  return isYearlySubscription.value\n    ? t('subscription.tierNameYearly', { name: baseName })\n    : baseName\n})\n\nconst planDisplayName = computed(() => {\n  if (isEnterprisePlan.value) return t('subscription.tiers.enterprise.name')\n  if (isNonCatalogPlan.value) return t('subscription.unknownTierName')\n  return isTeamPlan.value\n    ? t('subscription.teamPlanName')\n    : subscriptionTierName.value\n})\n\nconst tierKey = computed(() =>\n  resolveSubscriptionTierKey(subscription.value?.tier)\n)\n\nconst TEAM_PERK_KEYS = [\n  'inviteMembers',\n  'concurrentRuns',\n  'sharedCreditPool',\n  'rolePermissions'\n] as const\n\nconst tierBenefits = computed((): TierBenefit[] => {\n  if (isNonCatalogPlan.value) return []\n  if (isTeamActive.value || showInactiveTeamSubscription.value) {\n    return TEAM_PERK_KEYS.map((key) => ({\n      key,\n      type: 'feature',\n      label: t(`subscription.teamPerks.${key}`)\n    }))\n  }\n  if (isPersonalFree.value) {\n    return [\n      ...(freeRunsQuotaEnabled.value\n        ? [\n            {\n              key: 'freeRuns',\n              type: 'feature' as const,\n              label: t(\n                'subscription.freePerks.freeRuns',\n                freeRunsAllowance.value\n              )\n            }\n          ]\n        : []),\n      {\n        key: 'maxRuntime',\n        type: 'feature',\n        label: t('subscription.freePerks.maxRuntime', {\n          duration: t('subscription.maxDuration.free')\n        })\n      }\n    ]\n  }\n  return getCommonTierBenefits(tierKey.value, t, n)\n})\n</script>\n\n<style scoped>\n:deep(.bg-comfy-menu-secondary) {\n  background-color: transparent;\n}\n</style>\n","<template>\n  <div\n    class=\"flex grow flex-col overflow-auto pt-2\"\n    @scroll=\"handlePanelScroll\"\n  >\n    <!-- Loading state while subscription is being set up -->\n    <div\n      v-if=\"isSettingUp\"\n      class=\"rounded-2xl border border-interface-stroke p-6\"\n    >\n      <div class=\"flex items-center gap-2 py-4 text-muted-foreground\">\n        <i class=\"pi pi-spin pi-spinner\" />\n        <span>{{ $t('billingOperation.subscriptionProcessing') }}</span>\n      </div>\n      <Button\n        v-if=\"subscriptionActionUrl && permissions.canManageSubscription\"\n        variant=\"primary\"\n        size=\"lg\"\n        class=\"rounded-lg px-4 text-sm font-normal\"\n        @click=\"openSubscriptionVerification\"\n      >\n        {{ $t('subscription.preview.completeVerification') }}\n      </Button>\n    </div>\n\n    <!-- Billing data still loading: avoid rendering a false Free/$0 plan -->\n    <div\n      v-else-if=\"isLoading && !subscription\"\n      class=\"rounded-2xl border border-interface-stroke p-6\"\n    >\n      <div class=\"flex items-center gap-2 py-4 text-muted-foreground\">\n        <i class=\"pi pi-spin pi-spinner\" />\n        <span>{{ $t('g.loading') }}</span>\n      </div>\n    </div>\n\n    <!-- Billing fetch failed: offer retry rather than a misleading Free plan -->\n    <div\n      v-else-if=\"error && !subscription\"\n      class=\"flex flex-col items-start gap-3 rounded-2xl border border-interface-stroke p-6\"\n    >\n      <div class=\"flex items-center gap-2 text-text-secondary\">\n        <i class=\"pi pi-exclamation-circle text-destructive-background\" />\n        <span class=\"text-sm\">{{ $t('subscription.planLoadError') }}</span>\n      </div>\n      <Button\n        variant=\"secondary\"\n        size=\"lg\"\n        class=\"rounded-lg px-4 text-sm font-normal\"\n        :loading=\"isLoading\"\n        @click=\"handleRetry\"\n      >\n        {{ $t('subscription.planLoadErrorRetry') }}\n      </Button>\n    </div>\n\n    <template v-else>\n      <!-- Cancelled subscription info card -->\n      <div\n        v-if=\"showSubscriptionStateCard\"\n        data-testid=\"subscription-state-card\"\n        class=\"mb-6 flex gap-1 rounded-2xl border border-warning-background bg-warning-background/20 p-4\"\n      >\n        <div\n          class=\"flex size-8 shrink-0 items-center justify-center rounded-full text-warning-background\"\n        >\n          <i class=\"pi pi-info-circle\" />\n        </div>\n        <div class=\"flex flex-col gap-2\">\n          <h2 class=\"m-0 pt-1.5 text-sm font-bold text-text-primary\">\n            {{ subscriptionStateCardTitle }}\n          </h2>\n          <p class=\"m-0 text-sm text-text-secondary\">\n            {{ subscriptionStateCardDescription }}\n          </p>\n        </div>\n      </div>\n\n      <div class=\"rounded-2xl border border-interface-stroke p-6\">\n        <div>\n          <div\n            class=\"flex flex-col gap-4 md:flex-row md:items-center md:justify-between md:gap-2\"\n          >\n            <!-- OWNER Unsubscribed TEAM workspace -->\n            <template v-if=\"showTeamSubscribePrompt\">\n              <div class=\"flex flex-col gap-2\">\n                <h3\n                  :class=\"\n                    cn(\n                      'm-0 font-bold text-text-primary',\n                      showInactiveTeamSubscription ? 'text-base' : 'text-sm'\n                    )\n                  \"\n                >\n                  {{\n                    $t(\n                      showInactiveTeamSubscription\n                        ? 'subscription.inactiveTeamTitle'\n                        : 'subscription.workspaceNotSubscribed'\n                    )\n                  }}\n                </h3>\n                <div class=\"text-sm text-text-secondary\">\n                  {{\n                    $t(\n                      showInactiveTeamSubscription\n                        ? 'subscription.inactiveTeamDescription'\n                        : 'subscription.subscriptionRequiredMessage'\n                    )\n                  }}\n                </div>\n              </div>\n              <div class=\"flex flex-wrap gap-2 md:ml-auto\">\n                <Button\n                  v-if=\"\n                    permissions.canManageSubscription &&\n                    (isCloud || showInactiveTeamSubscription)\n                  \"\n                  size=\"lg\"\n                  variant=\"secondary\"\n                  class=\"rounded-lg bg-interface-menu-component-surface-selected px-4 text-sm font-normal text-text-primary\"\n                  @click=\"manageSubscription\"\n                >\n                  {{ $t('subscription.billingAndInvoices') }}\n                </Button>\n                <Button\n                  variant=\"primary\"\n                  size=\"lg\"\n                  class=\"rounded-lg px-4 py-2 text-sm font-normal\"\n                  @click=\"handleSubscribeWorkspace\"\n                >\n                  {{\n                    $t(\n                      showInactiveTeamSubscription\n                        ? 'subscription.reactivatePlan'\n                        : 'subscription.subscribeNow'\n                    )\n                  }}\n                </Button>\n                <Menu\n                  v-if=\"showInactiveTeamSubscription && menuEntries.length > 0\"\n                  :items=\"menuEntries\"\n                >\n                  <template #trigger>\n                    <Button\n                      :tooltip=\"$t('g.moreOptions')\"\n                      variant=\"secondary\"\n                      size=\"icon-lg\"\n                      icon=\"icon-[lucide--ellipsis]\"\n                      :aria-label=\"$t('g.moreOptions')\"\n                    />\n                  </template>\n                </Menu>\n              </div>\n            </template>\n\n            <!-- MEMBER View - read-only, workspace not subscribed -->\n            <template v-else-if=\"isMemberView\">\n              <div class=\"flex flex-col gap-2\">\n                <h3 class=\"m-0 text-sm font-bold text-text-primary\">\n                  {{ $t('subscription.workspaceNotSubscribed') }}\n                </h3>\n                <div class=\"text-sm text-text-secondary\">\n                  {{ $t('subscription.contactOwnerToSubscribe') }}\n                </div>\n              </div>\n            </template>\n\n            <!-- OWNER personal workspace without subscription (Free plan) -->\n            <template v-else-if=\"isPersonalFree\">\n              <div class=\"flex flex-col gap-2\">\n                <h3 class=\"m-0 text-base font-bold text-text-primary\">\n                  {{ $t('subscription.tiers.free.name') }}\n                </h3>\n                <div\n                  v-if=\"!isPriceCycleUnknown\"\n                  class=\"flex items-baseline gap-1 font-inter\"\n                >\n                  <span class=\"text-2xl font-semibold\">{{ displayPrice }}</span>\n                  <span class=\"text-base\">{{ priceUnitLabel }}</span>\n                </div>\n              </div>\n              <div class=\"flex flex-wrap gap-2 md:ml-auto\">\n                <Button\n                  v-if=\"isCloud && permissions.canManageSubscription\"\n                  size=\"lg\"\n                  variant=\"secondary\"\n                  class=\"rounded-lg bg-interface-menu-component-surface-selected px-4 text-sm font-normal text-text-primary\"\n                  @click=\"manageSubscription\"\n                >\n                  {{ $t('subscription.billingAndInvoices') }}\n                </Button>\n                <Button\n                  variant=\"primary\"\n                  size=\"lg\"\n                  class=\"rounded-lg px-4 text-sm font-normal\"\n                  @click=\"handleSubscribeWorkspace\"\n                >\n                  {{ $t('subscription.subscribe') }}\n                </Button>\n                <Menu v-if=\"menuEntries.length > 0\" :items=\"menuEntries\">\n                  <template #trigger>\n                    <Button\n                      :tooltip=\"$t('g.moreOptions')\"\n                      variant=\"secondary\"\n                      size=\"icon-lg\"\n                      icon=\"icon-[lucide--ellipsis]\"\n                      :aria-label=\"$t('g.moreOptions')\"\n                    />\n                  </template>\n                </Menu>\n              </div>\n            </template>\n\n            <!-- Normal Subscribed State (Owner with subscription, or member viewing subscribed workspace) -->\n            <template v-else>\n              <div class=\"flex flex-col gap-2\">\n                <div class=\"flex items-center gap-2\">\n                  <h3 class=\"m-0 text-base font-bold text-text-primary\">\n                    {{ planDisplayName }}\n                  </h3>\n                  <StatusBadge\n                    v-if=\"planStatusBadge\"\n                    data-testid=\"plan-status-badge\"\n                    :label=\"planStatusBadge.label\"\n                    :severity=\"planStatusBadge.severity\"\n                  />\n                </div>\n                <div\n                  v-if=\"!isNonCatalogPlan && !isPriceCycleUnknown\"\n                  class=\"flex items-baseline gap-1 font-inter\"\n                >\n                  <span class=\"text-2xl font-semibold\">{{ displayPrice }}</span>\n                  <span class=\"text-base\">{{ priceUnitLabel }}</span>\n                </div>\n                <div v-if=\"planDateDisplay\" class=\"text-sm text-text-secondary\">\n                  {{ planDateDisplay }}\n                </div>\n                <p\n                  v-if=\"isEndedEnterprise\"\n                  class=\"m-0 text-sm text-text-secondary\"\n                >\n                  {{ $t('subscription.inactiveEnterpriseDescription') }}\n                </p>\n              </div>\n\n              <div\n                v-if=\"\n                  canAccessSubscriptionFeatures ||\n                  (isCloud && permissions.canManageSubscription)\n                \"\n                class=\"flex flex-wrap gap-2 md:ml-auto\"\n              >\n                <Button\n                  v-if=\"\n                    permissions.canManageSubscription &&\n                    (isCloud || !isFreeTierPlan)\n                  \"\n                  size=\"lg\"\n                  variant=\"secondary\"\n                  class=\"rounded-lg bg-interface-menu-component-surface-selected px-4 text-sm font-normal text-text-primary\"\n                  @click=\"manageSubscription\"\n                >\n                  {{\n                    $t(\n                      isCloud\n                        ? 'subscription.billingAndInvoices'\n                        : 'subscription.manageBilling'\n                    )\n                  }}\n                </Button>\n                <!-- The server capability alone decides who may reactivate:\n                     hideLifecycleCapabilities closes this for sales-managed\n                     tiers (cloud common/billing/policy/capabilities.go). -->\n                <Button\n                  v-if=\"isSubscriptionCancelled && canReactivatePlan\"\n                  size=\"lg\"\n                  variant=\"primary\"\n                  class=\"rounded-lg px-4 text-sm font-normal\"\n                  :loading=\"isResubscribing\"\n                  @click=\"handleResubscribe\"\n                >\n                  {{ $t('subscription.reactivatePlan') }}\n                </Button>\n                <Button\n                  v-else-if=\"\n                    !isSubscriptionCancelled &&\n                    canAccessSubscriptionFeatures &&\n                    canChangePlan\n                  \"\n                  size=\"lg\"\n                  variant=\"secondary\"\n                  class=\"rounded-lg bg-interface-menu-component-surface-selected px-4 text-sm font-normal text-text-primary\"\n                  @click=\"handleUpgrade\"\n                >\n                  {{\n                    isInPersonalWorkspace && !isTeamPlan\n                      ? $t('subscription.upgradePlan')\n                      : $t('subscription.changePlan')\n                  }}\n                </Button>\n                <Menu v-if=\"menuEntries.length > 0\" :items=\"menuEntries\">\n                  <template #trigger>\n                    <Button\n                      :tooltip=\"$t('g.moreOptions')\"\n                      variant=\"secondary\"\n                      size=\"icon-lg\"\n                      icon=\"icon-[lucide--ellipsis]\"\n                      :aria-label=\"$t('g.moreOptions')\"\n                    />\n                  </template>\n                </Menu>\n              </div>\n            </template>\n          </div>\n        </div>\n\n        <div class=\"flex flex-col gap-6 pt-6 lg:flex-row lg:items-stretch\">\n          <div class=\"w-full lg:max-w-md\">\n            <CreditsTile\n              :zero-state=\"showZeroState\"\n              :inactive-plan=\"showInactiveTeamSubscription || isEndedEnterprise\"\n            />\n          </div>\n\n          <div\n            v-if=\"\n              !isNonCatalogPlan &&\n              (canAccessSubscriptionFeatures ||\n                isPersonalFree ||\n                showInactiveTeamSubscription)\n            \"\n            class=\"flex flex-col gap-2\"\n          >\n            <i18n-t\n              v-if=\"isTeamActive || showInactiveTeamSubscription\"\n              :keypath=\"\n                showInactiveTeamSubscription\n                  ? 'subscription.inactiveTeamPlanIncludes'\n                  : 'subscription.teamPlanIncludes'\n              \"\n              tag=\"div\"\n              class=\"text-sm text-muted\"\n            >\n              <template #plan>\n                <span class=\"text-text-primary\">\n                  {{ $t('subscription.tiers.pro.name') }}\n                </span>\n              </template>\n            </i18n-t>\n            <div v-else-if=\"isPersonalFree\" class=\"text-sm text-muted\">\n              {{ $t('subscription.whatsIncluded') }}\n            </div>\n            <div v-else class=\"text-sm text-text-primary\">\n              {{ $t('subscription.yourPlanIncludes') }}\n            </div>\n\n            <div class=\"flex flex-col gap-0\">\n              <div\n                v-for=\"benefit in tierBenefits\"\n                :key=\"benefit.key\"\n                class=\"flex items-center gap-2 py-2\"\n              >\n                <i\n                  v-if=\"benefit.type === 'feature'\"\n                  :class=\"\n                    cn(\n                      'pi pi-check text-xs',\n                      showInactiveTeamSubscription\n                        ? 'text-muted'\n                        : 'text-text-primary'\n                    )\n                  \"\n                />\n                <span\n                  v-else-if=\"benefit.type === 'metric' && benefit.value\"\n                  class=\"text-sm font-normal whitespace-nowrap text-text-primary\"\n                >\n                  {{ benefit.value }}\n                </span>\n                <span class=\"text-sm text-muted\">\n                  {{ benefit.label }}\n                </span>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <SubscriptionFooterLinks\n        class=\"mt-auto pt-6\"\n        :show-plans-link=\"canOpenPricingSurface\"\n        :show-invoice-history=\"permissions.canManageSubscription\"\n        :show-usage-activity=\"workspaceRole === 'owner'\"\n        @view-plans=\"handleViewMoreDetails\"\n      />\n    </template>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useSettingsHeaderCollapse } from '@/platform/settings/composables/useSettingsHeaderCollapse'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { useTimestamp } from '@vueuse/core'\nimport { storeToRefs } from 'pinia'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport CreditsTile from '@/platform/cloud/subscription/components/CreditsTile.vue'\nimport SubscriptionFooterLinks from '@/platform/cloud/subscription/components/SubscriptionFooterLinks.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport StatusBadge from '@/components/common/StatusBadge.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useSubscriptionDialog } from '@/platform/cloud/subscription/composables/useSubscriptionDialog'\nimport { useFreeTierQuota } from '@/platform/cloud/subscription/composables/useFreeTierQuota'\nimport {\n  isSalesManagedTier,\n  isWithinEnterpriseEndingNotice\n} from '@/platform/cloud/subscription/constants/tierPricing'\nimport type { TierBenefit } from '@/platform/cloud/subscription/utils/tierBenefits'\nimport { getCommonTierBenefits } from '@/platform/cloud/subscription/utils/tierBenefits'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useBillingBanner } from '@/platform/workspace/composables/useBillingBanner'\nimport { useResubscribe } from '@/platform/workspace/composables/useResubscribe'\nimport { useScheduledPlanChange } from '@/platform/workspace/composables/useScheduledPlanChange'\nimport { useBillingCapabilities } from '@/platform/workspace/composables/useBillingCapabilities'\nimport { useSubscriptionOperationView } from '@/platform/workspace/composables/useSubscriptionRail'\nimport { useWorkspaceMenuItems } from '@/platform/workspace/composables/useWorkspaceMenuItems'\nimport { useWorkspacePlanPricing } from '@/platform/workspace/composables/useWorkspacePlanPricing'\nimport { useWorkspaceUI } from '@/platform/workspace/composables/useWorkspaceUI'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport {\n  formatSubscriptionDate,\n  resolveSubscriptionTierKey\n} from './subscriptionPanelWorkspace.logic'\n\nconst { handlePanelScroll } = useSettingsHeaderCollapse()\n\nconst workspaceStore = useTeamWorkspaceStore()\nconst { isWorkspaceSubscribed, isInPersonalWorkspace } =\n  storeToRefs(workspaceStore)\nconst {\n  permissions,\n  isSubscriptionCancelled,\n  workspaceRole,\n  canReactivatePlan,\n  canOpenPricingSurface\n} = useWorkspaceUI()\nconst { canChangeSeats, canSubscribeSelfServe } = useBillingCapabilities()\nconst { maxAvailable: freeRunsAllowance, quotaEnabled: freeRunsQuotaEnabled } =\n  useFreeTierQuota()\nconst { t, n, locale } = useI18n()\n\nconst { isSettingUp, subscriptionActionUrl } = useSubscriptionOperationView()\n\nfunction openSubscriptionVerification() {\n  if (!subscriptionActionUrl.value) return\n  window.open(subscriptionActionUrl.value, '_blank', 'noopener,noreferrer')\n}\n\nconst {\n  canAccessSubscriptionFeatures,\n  isFreeTier: isFreeTierPlan,\n  isTeamPlan,\n  subscription,\n  billingStatus,\n  subscriptionStatus,\n  isLoading,\n  error,\n  showSubscriptionDialog,\n  manageSubscription,\n  initialize\n} = useBillingContext()\n\nconst { showPricingTable } = useSubscriptionDialog()\n\nconst { isResubscribing, handleResubscribe } = useResubscribe()\nconst { displayPrice, priceUnitLabel, isPriceCycleUnknown } =\n  useWorkspacePlanPricing()\nconst { menuEntries } = useWorkspaceMenuItems()\n\nconst isSubscriptionEnded = computed(() => {\n  if (subscriptionStatus.value === 'ended') return true\n  if (canAccessSubscriptionFeatures.value) return false\n  return (\n    isSubscriptionCancelled.value ||\n    (isInPersonalWorkspace.value && billingStatus.value === 'inactive')\n  )\n})\n\n// Show subscribe prompt to owners without active subscription. A cancelled plan\n// stays active until its end date, so it keeps the subscribed treatment.\nconst showSubscribePrompt = computed(() => {\n  if (\n    !(isCloud\n      ? canSubscribeSelfServe.value\n      : permissions.value.canManageSubscription)\n  )\n    return false\n  if (isSubscriptionEnded.value) return true\n  if (isSubscriptionCancelled.value) return false\n  if (\n    subscription.value &&\n    !isFreeTierPlan.value &&\n    (subscription.value.planSlug || subscription.value.tier)\n  )\n    return false\n  if (isInPersonalWorkspace.value) return !canAccessSubscriptionFeatures.value\n  return !isWorkspaceSubscribed.value\n})\n\nconst canChangePlan = computed(() =>\n  isCloud ? canChangeSeats.value : permissions.value.canManageSubscription\n)\n\n// The never-subscribed upsell is Cloud-only; on Local the policy table keeps\n// top-up available instead. An ended Team plan keeps its inactive treatment\n// everywhere so billing, invoices, and reactivation stay reachable.\nconst showTeamSubscribePrompt = computed(\n  () =>\n    showSubscribePrompt.value &&\n    !isInPersonalWorkspace.value &&\n    (isCloud || (isSubscriptionEnded.value && isTeamPlan.value))\n)\n\nconst showInactiveTeamSubscription = computed(\n  () =>\n    permissions.value.canManageSubscription &&\n    !isInPersonalWorkspace.value &&\n    isSubscriptionEnded.value &&\n    isTeamPlan.value\n)\n\nconst isPersonalFree = computed(\n  () =>\n    isInPersonalWorkspace.value &&\n    (showSubscribePrompt.value || isFreeTierPlan.value)\n)\n\nconst isTeamActive = computed(\n  () => isTeamPlan.value && canAccessSubscriptionFeatures.value\n)\n\nconst isMemberView = computed(\n  () =>\n    !permissions.value.canManageSubscription &&\n    !canAccessSubscriptionFeatures.value &&\n    !isWorkspaceSubscribed.value\n)\n\nconst showZeroState = computed(\n  () => showTeamSubscribePrompt.value || isMemberView.value\n)\n\nfunction handleSubscribeWorkspace() {\n  showSubscriptionDialog({ reason: 'settings_billing_panel' })\n}\n\nfunction handleUpgrade() {\n  if (isFreeTierPlan.value)\n    showPricingTable({ reason: 'settings_billing_panel' })\n  else showSubscriptionDialog({ reason: 'settings_billing_panel' })\n}\n\nfunction handleViewMoreDetails() {\n  window.open('https://comfy.org/cloud/pricing/', '_blank')\n}\n\nasync function handleRetry() {\n  await initialize()\n}\n\nconst isYearlySubscription = computed(\n  () => subscription.value?.duration === 'ANNUAL'\n)\n\nconst formattedRenewalDate = computed(() =>\n  formatSubscriptionDate(subscription.value?.renewalDate, locale.value)\n)\n\nconst formattedEndDate = computed(() =>\n  formatSubscriptionDate(subscription.value?.endDate, locale.value)\n)\n\nconst {\n  scheduledChange,\n  planName: scheduledPlanName,\n  formattedDate: formattedChangeDate\n} = useScheduledPlanChange()\n\nconst isNonCatalogPlan = computed(() =>\n  isSalesManagedTier(subscription.value?.tier)\n)\n\n// Strictly ENTERPRISE, not isSalesManagedTier: an unrecognized tier keeps the\n// stock cancelled treatment (isUnknownTier's contract — no borrowed claims).\nconst isEnterprisePlan = computed(\n  () => subscription.value?.tier === 'ENTERPRISE'\n)\n\nconst isEndedEnterprise = computed(\n  () => isEnterprisePlan.value && isSubscriptionEnded.value\n)\n\n// An Enterprise end date is an agreed ending — operator pilot term or\n// sales-mediated cancellation, deliberately not distinguished (see\n// deriveBillingBanner; decision on FE-2035) — often set months ahead. Only\n// its presence moves the plan onto the quiet path: no amber card or Canceled\n// badge at any point, and no \"Ends on\" line until the notice window.\n// Cancelled with no end date — or an unreadable one — falls back to the\n// stock treatment.\nconst hasScheduledEnterpriseEnd = computed(() => {\n  const endDate = subscription.value?.endDate\n  if (!isEnterprisePlan.value || !endDate) return false\n  return !Number.isNaN(Date.parse(endDate))\n})\n\n// Coarse shared clock so the notice window opens mid-session too.\nconst now = useTimestamp({ interval: 60_000 })\n\nconst isQuietEnterpriseEnding = computed(\n  () =>\n    hasScheduledEnterpriseEnd.value &&\n    !isWithinEnterpriseEndingNotice(subscription.value?.endDate, now.value)\n)\n\nconst { kind: billingBannerKind } = useBillingBanner()\n\n// An end-dated Enterprise plan never shows the amber card; inside the notice\n// window the muted ending banner carries the message instead. The banner is\n// still rolling out, so the card stays wherever the ending banner is not shown.\nconst showSubscriptionStateCard = computed(\n  () =>\n    isSubscriptionCancelled.value &&\n    !isSubscriptionEnded.value &&\n    !hasScheduledEnterpriseEnd.value &&\n    billingBannerKind.value !== 'ending'\n)\n\nconst subscriptionStateCardTitle = computed(() =>\n  t('subscription.canceledCard.title')\n)\n\nconst subscriptionStateCardDescription = computed(() =>\n  formattedEndDate.value\n    ? t('subscription.canceledCard.description', {\n        date: formattedEndDate.value\n      })\n    : t('subscription.canceledCard.descriptionWithoutDate')\n)\n\nconst planStatusBadge = computed(() => {\n  if (isSubscriptionEnded.value)\n    return {\n      label: t('subscription.inactive.badge'),\n      severity: 'secondary' as const\n    }\n  if (isSubscriptionCancelled.value && !hasScheduledEnterpriseEnd.value)\n    return { label: t('subscription.canceled'), severity: 'warn' as const }\n  return null\n})\n\nconst planDateDisplay = computed(() => {\n  if (!canAccessSubscriptionFeatures.value || isSubscriptionEnded.value)\n    return ''\n  if (isSubscriptionCancelled.value) {\n    if (isQuietEnterpriseEnding.value) return ''\n    return formattedEndDate.value\n      ? t('subscription.endsOnDate', { date: formattedEndDate.value })\n      : ''\n  }\n  if (scheduledChange.value) {\n    return scheduledPlanName.value && formattedChangeDate.value\n      ? t('subscription.changesToPlanOnDate', {\n          plan: scheduledPlanName.value,\n          date: formattedChangeDate.value\n        })\n      : ''\n  }\n  return formattedRenewalDate.value\n    ? t('subscription.renewsOnDate', { date: formattedRenewalDate.value })\n    : ''\n})\n\nconst subscriptionTierName = computed(() => {\n  const tier = subscription.value?.tier\n  if (!tier) return ''\n  const key = resolveSubscriptionTierKey(tier)\n  const baseName = t(`subscription.tiers.${key}.name`)\n  return isYearlySubscription.value\n    ? t('subscription.tierNameYearly', { name: baseName })\n    : baseName\n})\n\nconst planDisplayName = computed(() => {\n  if (isEnterprisePlan.value) return t('subscription.tiers.enterprise.name')\n  if (isNonCatalogPlan.value) return t('subscription.unknownTierName')\n  return isTeamPlan.value\n    ? t('subscription.teamPlanName')\n    : subscriptionTierName.value\n})\n\nconst tierKey = computed(() =>\n  resolveSubscriptionTierKey(subscription.value?.tier)\n)\n\nconst TEAM_PERK_KEYS = [\n  'inviteMembers',\n  'concurrentRuns',\n  'sharedCreditPool',\n  'rolePermissions'\n] as const\n\nconst tierBenefits = computed((): TierBenefit[] => {\n  if (isNonCatalogPlan.value) return []\n  if (isTeamActive.value || showInactiveTeamSubscription.value) {\n    return TEAM_PERK_KEYS.map((key) => ({\n      key,\n      type: 'feature',\n      label: t(`subscription.teamPerks.${key}`)\n    }))\n  }\n  if (isPersonalFree.value) {\n    return [\n      ...(freeRunsQuotaEnabled.value\n        ? [\n            {\n              key: 'freeRuns',\n              type: 'feature' as const,\n              label: t(\n                'subscription.freePerks.freeRuns',\n                freeRunsAllowance.value\n              )\n            }\n          ]\n        : []),\n      {\n        key: 'maxRuntime',\n        type: 'feature',\n        label: t('subscription.freePerks.maxRuntime', {\n          duration: t('subscription.maxDuration.free')\n        })\n      }\n    ]\n  }\n  return getCommonTierBenefits(tierKey.value, t, n)\n})\n</script>\n\n<style scoped>\n:deep(.bg-comfy-menu-secondary) {\n  background-color: transparent;\n}\n</style>\n","import { computed } from 'vue'\n\nimport type { SubscriptionInfo } from '@/composables/billing/types'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport type {\n  Plan,\n  SubscriptionDuration,\n  TeamCreditStops,\n  TeamCreditStopSummary\n} from '@/platform/workspace/api/workspaceApi'\n\nexport interface NextInvoiceInputs {\n  subscription: SubscriptionInfo | null\n  planSlug: string | null\n  plans: Plan[]\n  teamCreditStops: TeamCreditStops | null\n  currentTeamCreditStop: TeamCreditStopSummary | null\n}\n\nexport interface NextInvoice {\n  amountCents: number\n  renewalDate: string | null\n  duration: SubscriptionDuration\n}\n\n/**\n * Next invoice for the Settings > Invoices banner; annual subscriptions show\n * their yearly total and renewal date. Unit semantics: credit-stop\n * `yearly.price_cents` is a per-month figure (x12 for the invoice total)\n * while an ANNUAL plan's `price_cents` is already the yearly total.\n * `renewalDate` is BE-computed and passed through untouched — backends own\n * period math including month-end bias — and goes null once a cancellation\n * is scheduled. Cancelled/inactive return null because the cancelled Toast\n * owns that state. A non-positive resolved amount also returns null (free\n * tier can look like an active subscription with no real invoice).\n * Intentionally limited to the subscription price: usage/overage pending\n * charges are excluded until the backend exposes an authoritative\n * upcoming-invoice amount.\n */\nexport function deriveNextInvoice({\n  subscription,\n  planSlug,\n  plans,\n  teamCreditStops,\n  currentTeamCreditStop\n}: NextInvoiceInputs): NextInvoice | null {\n  if (!subscription?.isActive || subscription.isCancelled) return null\n\n  const duration = subscription.duration === 'ANNUAL' ? 'ANNUAL' : 'MONTHLY'\n  const stop = teamCreditStops?.stops.find(\n    ({ id }) => id === currentTeamCreditStop?.id\n  )\n  const plan = plans.find(\n    (candidate) =>\n      candidate.slug === planSlug && candidate.duration === duration\n  )\n  const amountCents = stop\n    ? duration === 'ANNUAL'\n      ? stop.yearly.price_cents * 12\n      : stop.monthly.price_cents\n    : plan?.price_cents\n\n  if (!amountCents || amountCents <= 0) return null\n\n  return {\n    amountCents,\n    renewalDate: subscription.renewalDate,\n    duration\n  }\n}\n\n/**\n * Callers own billing-context initialization; a null invoice hides the\n * banner.\n */\nexport function useNextInvoice() {\n  const {\n    subscription,\n    currentPlanSlug,\n    plans,\n    teamCreditStops,\n    currentTeamCreditStop\n  } = useBillingContext()\n\n  const nextInvoice = computed(() =>\n    deriveNextInvoice({\n      subscription: subscription.value,\n      planSlug: currentPlanSlug.value,\n      plans: plans.value,\n      teamCreditStops: teamCreditStops.value,\n      currentTeamCreditStop: currentTeamCreditStop.value\n    })\n  )\n\n  return { nextInvoice }\n}\n","<template>\n  <div class=\"flex min-h-0 flex-1 flex-col gap-4\">\n    <!-- Billing data still loading: avoid rendering a false $0 charge -->\n    <div\n      v-if=\"isLoading && !subscription\"\n      class=\"rounded-2xl border border-interface-stroke p-6\"\n    >\n      <div class=\"flex items-center gap-2 py-4 text-muted-foreground\">\n        <i class=\"pi pi-spin pi-spinner\" />\n        <span>{{ $t('g.loading') }}</span>\n      </div>\n    </div>\n\n    <!-- Billing fetch failed: offer retry rather than a misleading amount -->\n    <div\n      v-else-if=\"error && !subscription\"\n      class=\"flex flex-col items-start gap-3 rounded-2xl border border-interface-stroke p-6\"\n    >\n      <div class=\"flex items-center gap-2 text-text-secondary\">\n        <i class=\"pi pi-exclamation-circle text-destructive-background\" />\n        <span class=\"text-sm\">{{ $t('subscription.planLoadError') }}</span>\n      </div>\n      <Button\n        variant=\"secondary\"\n        size=\"lg\"\n        class=\"rounded-lg px-4 text-sm font-normal\"\n        :loading=\"isLoading\"\n        @click=\"handleRetry\"\n      >\n        {{ $t('subscription.planLoadErrorRetry') }}\n      </Button>\n    </div>\n\n    <!-- Invoice history and per-invoice downloads live in Stripe by design, so\n         this tab surfaces the upcoming charge and links out. The amount drops\n         out while the subscription is paused — there is no upcoming charge\n         then, and the shared billing banner already reports that state — but\n         the history link stays reachable in every state. -->\n    <div\n      v-else\n      class=\"flex flex-col gap-4 rounded-2xl border border-interface-stroke/60 p-4 @2xl:flex-row @2xl:items-center @2xl:justify-between\"\n    >\n      <div v-if=\"upcomingAmount\" class=\"flex flex-col gap-2\">\n        <span class=\"text-sm text-muted-foreground\">\n          {{ $t('workspacePanel.invoices.nextInvoice') }}\n        </span>\n        <p class=\"m-0 text-2xl font-semibold text-base-foreground\">\n          {{ upcomingAmount }}\n          <span class=\"text-base font-normal text-base-foreground\">\n            {{ $t('workspacePanel.invoices.usd') }}\n          </span>\n        </p>\n      </div>\n      <Button\n        variant=\"secondary\"\n        size=\"lg\"\n        class=\"@2xl:ml-auto\"\n        :loading=\"isOpeningHistory\"\n        @click=\"openHistory\"\n      >\n        {{ $t('workspacePanel.invoices.fullHistory') }}\n        <i class=\"icon-[lucide--external-link] size-4\" />\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useNextInvoice } from '@/composables/billing/useNextInvoice'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { formatUsdCents } from '@/utils/numberUtil'\n\nconst { locale } = useI18n()\nconst { toastErrorHandler } = useErrorHandling()\nconst {\n  billingStatus,\n  subscription,\n  isLoading,\n  error,\n  initialize,\n  manageSubscription\n} = useBillingContext()\nconst { nextInvoice } = useNextInvoice()\n\nconst upcomingAmount = computed(() => {\n  if (billingStatus.value === 'paused') return null\n\n  const invoice = nextInvoice.value\n  return invoice ? formatUsdCents(locale.value, invoice.amountCents) : null\n})\n\nconst isOpeningHistory = ref(false)\n\n// `manageSubscription` carries no in-flight guard, so a second click would\n// start another portal request and open another window. It also rethrows once\n// the request fails, and this panel only renders its own error state before\n// billing has loaded, so the failure would otherwise be silent.\nfunction openHistory() {\n  if (isOpeningHistory.value) return\n\n  isOpeningHistory.value = true\n  void manageSubscription()\n    .catch(toastErrorHandler)\n    .finally(() => {\n      isOpeningHistory.value = false\n    })\n}\n\n// `initialize` rethrows so callers can react; the failure is already mirrored\n// into `error`, which drives this panel, so swallow it rather than surfacing an\n// unhandled rejection from a click handler.\nfunction handleRetry() {\n  void initialize().catch(() => undefined)\n}\n</script>\n","<template>\n  <div class=\"flex min-h-0 flex-1 flex-col gap-4\">\n    <!-- Billing data still loading: avoid rendering a false $0 charge -->\n    <div\n      v-if=\"isLoading && !subscription\"\n      class=\"rounded-2xl border border-interface-stroke p-6\"\n    >\n      <div class=\"flex items-center gap-2 py-4 text-muted-foreground\">\n        <i class=\"pi pi-spin pi-spinner\" />\n        <span>{{ $t('g.loading') }}</span>\n      </div>\n    </div>\n\n    <!-- Billing fetch failed: offer retry rather than a misleading amount -->\n    <div\n      v-else-if=\"error && !subscription\"\n      class=\"flex flex-col items-start gap-3 rounded-2xl border border-interface-stroke p-6\"\n    >\n      <div class=\"flex items-center gap-2 text-text-secondary\">\n        <i class=\"pi pi-exclamation-circle text-destructive-background\" />\n        <span class=\"text-sm\">{{ $t('subscription.planLoadError') }}</span>\n      </div>\n      <Button\n        variant=\"secondary\"\n        size=\"lg\"\n        class=\"rounded-lg px-4 text-sm font-normal\"\n        :loading=\"isLoading\"\n        @click=\"handleRetry\"\n      >\n        {{ $t('subscription.planLoadErrorRetry') }}\n      </Button>\n    </div>\n\n    <!-- Invoice history and per-invoice downloads live in Stripe by design, so\n         this tab surfaces the upcoming charge and links out. The amount drops\n         out while the subscription is paused — there is no upcoming charge\n         then, and the shared billing banner already reports that state — but\n         the history link stays reachable in every state. -->\n    <div\n      v-else\n      class=\"flex flex-col gap-4 rounded-2xl border border-interface-stroke/60 p-4 @2xl:flex-row @2xl:items-center @2xl:justify-between\"\n    >\n      <div v-if=\"upcomingAmount\" class=\"flex flex-col gap-2\">\n        <span class=\"text-sm text-muted-foreground\">\n          {{ $t('workspacePanel.invoices.nextInvoice') }}\n        </span>\n        <p class=\"m-0 text-2xl font-semibold text-base-foreground\">\n          {{ upcomingAmount }}\n          <span class=\"text-base font-normal text-base-foreground\">\n            {{ $t('workspacePanel.invoices.usd') }}\n          </span>\n        </p>\n      </div>\n      <Button\n        variant=\"secondary\"\n        size=\"lg\"\n        class=\"@2xl:ml-auto\"\n        :loading=\"isOpeningHistory\"\n        @click=\"openHistory\"\n      >\n        {{ $t('workspacePanel.invoices.fullHistory') }}\n        <i class=\"icon-[lucide--external-link] size-4\" />\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useNextInvoice } from '@/composables/billing/useNextInvoice'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { formatUsdCents } from '@/utils/numberUtil'\n\nconst { locale } = useI18n()\nconst { toastErrorHandler } = useErrorHandling()\nconst {\n  billingStatus,\n  subscription,\n  isLoading,\n  error,\n  initialize,\n  manageSubscription\n} = useBillingContext()\nconst { nextInvoice } = useNextInvoice()\n\nconst upcomingAmount = computed(() => {\n  if (billingStatus.value === 'paused') return null\n\n  const invoice = nextInvoice.value\n  return invoice ? formatUsdCents(locale.value, invoice.amountCents) : null\n})\n\nconst isOpeningHistory = ref(false)\n\n// `manageSubscription` carries no in-flight guard, so a second click would\n// start another portal request and open another window. It also rethrows once\n// the request fails, and this panel only renders its own error state before\n// billing has loaded, so the failure would otherwise be silent.\nfunction openHistory() {\n  if (isOpeningHistory.value) return\n\n  isOpeningHistory.value = true\n  void manageSubscription()\n    .catch(toastErrorHandler)\n    .finally(() => {\n      isOpeningHistory.value = false\n    })\n}\n\n// `initialize` rethrows so callers can react; the failure is already mirrored\n// into `error`, which drives this panel, so swallow it rather than surfacing an\n// unhandled rejection from a click handler.\nfunction handleRetry() {\n  void initialize().catch(() => undefined)\n}\n</script>\n","<template>\n  <div class=\"flex min-h-0 flex-1 flex-col\">\n    <Teleport\n      defer\n      to=\"#settings-header-controls\"\n      :disabled=\"!isHeaderCollapsed\"\n    >\n      <div\n        :class=\"\n          cn(\n            'flex w-full gap-3',\n            isHeaderCollapsed\n              ? 'min-w-0 flex-1 flex-row items-center gap-9'\n              : 'mb-4 flex-col @2xl:flex-row @2xl:items-center @2xl:gap-9'\n          )\n        \"\n      >\n        <div class=\"flex min-w-0 flex-1 items-center gap-2\">\n          <Button\n            v-for=\"tab in tabs\"\n            :key=\"tab.key\"\n            :variant=\"activeView === tab.key ? 'secondary' : 'muted-textonly'\"\n            size=\"lg\"\n            @click=\"activeView = tab.key\"\n          >\n            {{ tab.label }}\n          </Button>\n        </div>\n      </div>\n    </Teleport>\n\n    <template v-if=\"activeView === 'overview'\">\n      <SubscriptionPanelContentWorkspace v-if=\"isCloud\" />\n      <div\n        v-else\n        class=\"flex min-h-0 flex-1 flex-col gap-8 overflow-y-auto\"\n        @scroll=\"handlePanelScroll\"\n      >\n        <CreditsPanel embedded />\n        <SubscriptionFooterLinks\n          class=\"mt-auto shrink-0\"\n          :show-invoice-history=\"false\"\n          :show-usage-activity=\"false\"\n        />\n      </div>\n    </template>\n    <WorkspaceInvoicesContent v-else-if=\"activeView === 'invoices'\" />\n    <UsageLogsTable v-else ref=\"usageLogsTable\" />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useSettingsHeaderCollapse } from '@/platform/settings/composables/useSettingsHeaderCollapse'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { computed, ref, useTemplateRef, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport CreditsPanel from '@/components/dialog/content/setting/CreditsPanel.vue'\nimport UsageLogsTable from '@/components/dialog/content/setting/UsageLogsTable.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport SubscriptionFooterLinks from '@/platform/cloud/subscription/components/SubscriptionFooterLinks.vue'\nimport { isCloud } from '@/platform/distribution/types'\nimport SubscriptionPanelContentWorkspace from '@/platform/workspace/components/SubscriptionPanelContentWorkspace.vue'\nimport WorkspaceInvoicesContent from '@/platform/workspace/components/dialogs/settings/WorkspaceInvoicesContent.vue'\nimport { useWorkspaceUI } from '@/platform/workspace/composables/useWorkspaceUI'\n\ntype View = 'overview' | 'activity' | 'invoices'\n\nconst { isHeaderCollapsed, handlePanelScroll, resetHeaderCollapse } =\n  useSettingsHeaderCollapse()\n\nconst { t } = useI18n()\nconst { permissions } = useWorkspaceUI()\n\n// Invoices covers a workspace-wide charge, so it is billing-manager only, and\n// the upcoming amount and Stripe portal only exist on cloud.\nconst canSeeInvoices = computed(\n  () => isCloud && permissions.value.canManageSubscription\n)\n\nconst tabs = computed<{ key: View; label: string }[]>(() => [\n  { key: 'overview', label: t('workspacePanel.planCredits.tabs.overview') },\n  { key: 'activity', label: t('workspacePanel.planCredits.tabs.activity') },\n  ...(canSeeInvoices.value\n    ? [\n        {\n          key: 'invoices' as const,\n          label: t('workspacePanel.planCredits.tabs.invoices')\n        }\n      ]\n    : [])\n])\n\nconst activeView = ref<View>('overview')\n\n// Switching workspaces can drop the billing-manager role while the dialog\n// stays open; leaving Invoices selected would keep the panel rendered after\n// its tab disappeared.\nwatch(canSeeInvoices, (allowed) => {\n  if (!allowed && activeView.value === 'invoices') activeView.value = 'overview'\n})\n\n// Each view owns a different scroller, so a collapsed header would otherwise\n// survive the switch and sit above content at scrollTop 0.\nwatch(activeView, resetHeaderCollapse)\n\nconst usageLogsTable = useTemplateRef('usageLogsTable')\nwatch(usageLogsTable, (table) => {\n  table?.refresh().catch(() => {\n    console.error('Error refreshing usage logs')\n  })\n})\n</script>\n","<template>\n  <div class=\"flex min-h-0 flex-1 flex-col\">\n    <Teleport\n      defer\n      to=\"#settings-header-controls\"\n      :disabled=\"!isHeaderCollapsed\"\n    >\n      <div\n        :class=\"\n          cn(\n            'flex w-full gap-3',\n            isHeaderCollapsed\n              ? 'min-w-0 flex-1 flex-row items-center gap-9'\n              : 'mb-4 flex-col @2xl:flex-row @2xl:items-center @2xl:gap-9'\n          )\n        \"\n      >\n        <div class=\"flex min-w-0 flex-1 items-center gap-2\">\n          <Button\n            v-for=\"tab in tabs\"\n            :key=\"tab.key\"\n            :variant=\"activeView === tab.key ? 'secondary' : 'muted-textonly'\"\n            size=\"lg\"\n            @click=\"activeView = tab.key\"\n          >\n            {{ tab.label }}\n          </Button>\n        </div>\n      </div>\n    </Teleport>\n\n    <template v-if=\"activeView === 'overview'\">\n      <SubscriptionPanelContentWorkspace v-if=\"isCloud\" />\n      <div\n        v-else\n        class=\"flex min-h-0 flex-1 flex-col gap-8 overflow-y-auto\"\n        @scroll=\"handlePanelScroll\"\n      >\n        <CreditsPanel embedded />\n        <SubscriptionFooterLinks\n          class=\"mt-auto shrink-0\"\n          :show-invoice-history=\"false\"\n          :show-usage-activity=\"false\"\n        />\n      </div>\n    </template>\n    <WorkspaceInvoicesContent v-else-if=\"activeView === 'invoices'\" />\n    <UsageLogsTable v-else ref=\"usageLogsTable\" />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useSettingsHeaderCollapse } from '@/platform/settings/composables/useSettingsHeaderCollapse'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { computed, ref, useTemplateRef, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport CreditsPanel from '@/components/dialog/content/setting/CreditsPanel.vue'\nimport UsageLogsTable from '@/components/dialog/content/setting/UsageLogsTable.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport SubscriptionFooterLinks from '@/platform/cloud/subscription/components/SubscriptionFooterLinks.vue'\nimport { isCloud } from '@/platform/distribution/types'\nimport SubscriptionPanelContentWorkspace from '@/platform/workspace/components/SubscriptionPanelContentWorkspace.vue'\nimport WorkspaceInvoicesContent from '@/platform/workspace/components/dialogs/settings/WorkspaceInvoicesContent.vue'\nimport { useWorkspaceUI } from '@/platform/workspace/composables/useWorkspaceUI'\n\ntype View = 'overview' | 'activity' | 'invoices'\n\nconst { isHeaderCollapsed, handlePanelScroll, resetHeaderCollapse } =\n  useSettingsHeaderCollapse()\n\nconst { t } = useI18n()\nconst { permissions } = useWorkspaceUI()\n\n// Invoices covers a workspace-wide charge, so it is billing-manager only, and\n// the upcoming amount and Stripe portal only exist on cloud.\nconst canSeeInvoices = computed(\n  () => isCloud && permissions.value.canManageSubscription\n)\n\nconst tabs = computed<{ key: View; label: string }[]>(() => [\n  { key: 'overview', label: t('workspacePanel.planCredits.tabs.overview') },\n  { key: 'activity', label: t('workspacePanel.planCredits.tabs.activity') },\n  ...(canSeeInvoices.value\n    ? [\n        {\n          key: 'invoices' as const,\n          label: t('workspacePanel.planCredits.tabs.invoices')\n        }\n      ]\n    : [])\n])\n\nconst activeView = ref<View>('overview')\n\n// Switching workspaces can drop the billing-manager role while the dialog\n// stays open; leaving Invoices selected would keep the panel rendered after\n// its tab disappeared.\nwatch(canSeeInvoices, (allowed) => {\n  if (!allowed && activeView.value === 'invoices') activeView.value = 'overview'\n})\n\n// Each view owns a different scroller, so a collapsed header would otherwise\n// survive the switch and sit above content at scrollTop 0.\nwatch(activeView, resetHeaderCollapse)\n\nconst usageLogsTable = useTemplateRef('usageLogsTable')\nwatch(usageLogsTable, (table) => {\n  table?.refresh().catch(() => {\n    console.error('Error refreshing usage logs')\n  })\n})\n</script>\n","import type { MenuItem } from '@/components/ui/menu/types'\nimport { storeToRefs } from 'pinia'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { useSubscriptionDialog } from '@/platform/cloud/subscription/composables/useSubscriptionDialog'\nimport type { ServerFact } from '@/platform/serverFacts/serverFact'\nimport { narrowServerFact } from '@/platform/serverFacts/serverFact'\nimport type { WorkspaceRole } from '@/platform/workspace/api/workspaceApi'\nimport { useBillingCapabilities } from '@/platform/workspace/composables/useBillingCapabilities'\nimport { usePlanEnded } from '@/platform/workspace/composables/usePlanEnded'\nimport { useTeamPlan } from '@/platform/workspace/composables/useTeamPlan'\nimport { useWorkspaceUI } from '@/platform/workspace/composables/useWorkspaceUI'\nimport type {\n  WorkspacePendingInvite,\n  WorkspaceMember\n} from '@/platform/workspace/stores/teamWorkspaceStore'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport { useWorkspaceDialogs } from '@/platform/workspace/composables/useWorkspaceDialogs'\n\ntype ActiveView = 'active' | 'pending'\ntype SortField = 'inviteDate' | 'expiryDate'\ntype SortDirection = 'asc' | 'desc'\n\ninterface MemberGates {\n  canViewPendingInvites: ServerFact<'can_manage_members'>\n  canInviteMembers: ServerFact<'can_invite_members'>\n  canManageInvites: ServerFact<'can_manage_members'>\n  canManageMembers: ServerFact<'can_manage_members'>\n}\n\ntype MembersPanelPermissions = Omit<\n  ReturnType<typeof useWorkspaceUI>['permissions']['value'],\n  keyof MemberGates\n> &\n  MemberGates\n\nexport function sortMembers(\n  members: WorkspaceMember[],\n  currentUserEmail: string | null,\n  originalOwnerId: string | null = null\n): WorkspaceMember[] {\n  return [...members].sort((a, b) => {\n    const aIsOriginalOwner = a.id === originalOwnerId\n    const bIsOriginalOwner = b.id === originalOwnerId\n    if (aIsOriginalOwner && !bIsOriginalOwner) return -1\n    if (!aIsOriginalOwner && bIsOriginalOwner) return 1\n\n    if (a.role !== b.role) return a.role === 'owner' ? -1 : 1\n\n    const aIsCurrent = a.email.toLowerCase() === currentUserEmail?.toLowerCase()\n    const bIsCurrent = b.email.toLowerCase() === currentUserEmail?.toLowerCase()\n    if (aIsCurrent && !bIsCurrent) return -1\n    if (!aIsCurrent && bIsCurrent) return 1\n\n    return b.joinDate.getTime() - a.joinDate.getTime()\n  })\n}\n\nexport function filterBySearch<T extends { email: string; name?: string }>(\n  items: T[],\n  query: string\n): T[] {\n  if (!query) return items\n  const q = query.toLowerCase()\n  return items.filter(\n    (item) =>\n      item.email.toLowerCase().includes(q) ||\n      ('name' in item && item.name?.toLowerCase().includes(q))\n  )\n}\n\nexport function sortPendingInvites(\n  invites: WorkspacePendingInvite[],\n  sortField: SortField,\n  sortDirection: SortDirection\n): WorkspacePendingInvite[] {\n  return [...invites].sort((a, b) => {\n    const aDate = getInviteDate(a, sortField)\n    const bDate = getInviteDate(b, sortField)\n    if (!aDate || !bDate) return 0\n    const aValue = aDate.getTime()\n    const bValue = bDate.getTime()\n    return sortDirection === 'asc' ? aValue - bValue : bValue - aValue\n  })\n}\n\nfunction getInviteDate(\n  invite: WorkspacePendingInvite,\n  field: SortField\n): Date | undefined {\n  return invite[field]\n}\n\nexport function useMembersPanel() {\n  const { t } = useI18n()\n  const toast = useToast()\n  const { userPhotoUrl, userEmail, userDisplayName } = useCurrentUser()\n  const { flags } = useFeatureFlags()\n  const {\n    showRemoveMemberDialog,\n    showRevokeInviteDialog,\n    showChangeMemberRoleDialog,\n    showSetMemberCreditLimitDialog,\n    showInviteMemberDialog\n  } = useWorkspaceDialogs()\n  const workspaceStore = useTeamWorkspaceStore()\n  const {\n    activeWorkspace,\n    isInPersonalWorkspace,\n    members,\n    membersLoaded,\n    pendingInvites,\n    pendingInvitesLoaded,\n    originalOwnerId\n  } = storeToRefs(workspaceStore)\n  const totalMembers = computed(\n    () => activeWorkspace.value?.totalMembers ?? members.value.length\n  )\n  const { resendInvite } = workspaceStore\n  const { permissions: workspacePermissions, uiConfig: workspaceUiConfig } =\n    useWorkspaceUI()\n  const { hasTeamPlan, isOnTeamPlan, hasMemberSeats, isPlanLoading } =\n    useTeamPlan()\n  const subscriptionDialog = useSubscriptionDialog()\n  const { maxSeats } = useBillingContext()\n  const { canManageMembers, canInviteMembers } = useBillingCapabilities()\n\n  const { isPlanEnded, isSalesManagedPlan, isEnterprisePlan } = usePlanEnded()\n\n  const permissions = computed((): MembersPanelPermissions => {\n    const canManage = canManageMembers.value\n\n    return {\n      ...workspacePermissions.value,\n      canViewOtherMembers: membersLoaded.value,\n      canViewPendingInvites: canManage,\n      canInviteMembers: canInviteMembers.value,\n      canManageInvites: canManage,\n      canManageMembers: canManage\n    }\n  })\n\n  const hasMultipleMembers = computed(() => members.value.length > 1)\n\n  const showMinimalMemberLayout = computed(\n    () =>\n      !membersLoaded.value ||\n      (isInPersonalWorkspace.value && members.value.length === 1)\n  )\n\n  const uiConfig = computed(() => {\n    if (showMinimalMemberLayout.value) {\n      return {\n        ...workspaceUiConfig.value,\n        showMembersList: false,\n        showPendingTab: permissions.value.canViewPendingInvites,\n        showSearch: false,\n        showRoleColumn: false,\n        showCreditsColumn: false,\n        membersGridCols: 'grid-cols-1',\n        pendingGridCols: 'grid-cols-[50%_20%_20%_10%]',\n        headerGridCols: 'grid-cols-1'\n      }\n    }\n\n    if (canManageMembers.value) {\n      return {\n        ...workspaceUiConfig.value,\n        showMembersList: true,\n        showPendingTab: true,\n        showSearch: true,\n        showRoleColumn: true,\n        membersGridCols: workspaceUiConfig.value.showCreditsColumn\n          ? workspaceUiConfig.value.membersGridCols\n          : 'grid-cols-[50%_40%_10%]',\n        pendingGridCols: 'grid-cols-[50%_20%_20%_10%]',\n        headerGridCols: workspaceUiConfig.value.showCreditsColumn\n          ? workspaceUiConfig.value.headerGridCols\n          : 'grid-cols-[50%_40%_10%]'\n      }\n    }\n\n    return {\n      ...workspaceUiConfig.value,\n      showMembersList: true,\n      showPendingTab: false,\n      showSearch: true,\n      showRoleColumn: true,\n      membersGridCols: 'grid-cols-[1fr_auto]',\n      pendingGridCols: 'grid-cols-[50%_20%_20%_10%]',\n      headerGridCols: 'grid-cols-[1fr_auto]'\n    }\n  })\n\n  const showSearch = computed(\n    () => uiConfig.value.showSearch && hasMultipleMembers.value\n  )\n\n  const hasTabContent = computed(\n    () => hasMultipleMembers.value || pendingInvites.value.length > 0\n  )\n\n  const showViewTabs = computed(() =>\n    narrowServerFact(\n      permissions.value.canViewPendingInvites,\n      hasTabContent.value\n    )\n  )\n\n  const showInviteButton = computed(() => canInviteMembers.value)\n\n  function handleInviteMember() {\n    if (canInviteMembers.value) void showInviteMemberDialog()\n  }\n\n  const personalWorkspaceMember = computed<WorkspaceMember>(() => ({\n    id: 'self',\n    name: userDisplayName.value ?? '',\n    email: userEmail.value ?? '',\n    role: 'owner' as const,\n    joinDate: new Date(0),\n    isOriginalOwner: true\n  }))\n\n  const searchQuery = ref('')\n  const activeView = ref<ActiveView>('active')\n  const sortField = ref<SortField>('inviteDate')\n  const sortDirection = ref<SortDirection>('desc')\n\n  function memberMenuItems(member: WorkspaceMember): MenuItem[] {\n    if (!permissions.value.canManageMembers) return []\n\n    const creditLimitItem: MenuItem = {\n      label: t('workspacePanel.members.actions.setCreditLimit'),\n      command: () =>\n        void showSetMemberCreditLimitDialog({\n          memberId: member.id,\n          memberName: member.name,\n          creditsUsed: member.creditsUsedThisMonth,\n          currentLimit: member.monthlyCreditLimit\n        })\n    }\n\n    if (isCurrentUser(member) || isOriginalOwner(member)) {\n      return []\n    }\n\n    return [\n      {\n        label: t('workspacePanel.members.actions.changeRole'),\n        radioGroup: {\n          value: member.role,\n          options: [\n            {\n              value: 'owner',\n              label: t('workspaceSwitcher.roleOwner'),\n              command: () => handleChangeRole(member, 'owner')\n            },\n            {\n              value: 'member',\n              label: t('workspaceSwitcher.roleMember'),\n              command: () => handleChangeRole(member, 'member')\n            }\n          ]\n        }\n      },\n      ...(flags.memberCreditLimitsEnabled && member.role === 'member'\n        ? [creditLimitItem]\n        : []),\n      {\n        label: t('workspacePanel.members.actions.removeMember'),\n        command: () => handleRemoveMember(member)\n      }\n    ]\n  }\n\n  function isCurrentUser(member: WorkspaceMember): boolean {\n    return member.email.toLowerCase() === userEmail.value?.toLowerCase()\n  }\n\n  function isOriginalOwner(member: WorkspaceMember): boolean {\n    return (\n      activeWorkspace.value?.type === 'personal' &&\n      member.id === originalOwnerId.value\n    )\n  }\n\n  const filteredMembers = computed(() => {\n    const searched = filterBySearch(members.value, searchQuery.value)\n    return sortMembers(searched, userEmail.value ?? null, originalOwnerId.value)\n  })\n\n  // Built once per member list rather than per row on every render, so an\n  // unrelated re-render (e.g. typing in the search box) doesn't rebuild every\n  // row's menu and churn MemberListItem's props.\n  const memberMenus = computed(\n    () => new Map(filteredMembers.value.map((m) => [m.id, memberMenuItems(m)]))\n  )\n\n  const filteredPendingInvites = computed(() => {\n    const searched = filterBySearch(pendingInvites.value, searchQuery.value)\n    return sortPendingInvites(searched, sortField.value, sortDirection.value)\n  })\n\n  function toggleSort(field: SortField) {\n    if (sortField.value === field) {\n      sortDirection.value = sortDirection.value === 'asc' ? 'desc' : 'asc'\n    } else {\n      sortField.value = field\n      sortDirection.value = 'desc'\n    }\n  }\n\n  async function handleResendInvite(invite: WorkspacePendingInvite) {\n    if (!permissions.value.canManageInvites) return\n    try {\n      await resendInvite(invite.id)\n      toast.success(t('workspacePanel.toast.inviteResent'), { duration: 2000 })\n    } catch {\n      toast.error(t('workspacePanel.toast.inviteResendFailed'))\n    }\n  }\n\n  function handleRevokeInvite(invite: WorkspacePendingInvite) {\n    if (!permissions.value.canManageInvites) return\n    void showRevokeInviteDialog(invite.id)\n  }\n\n  function handleRemoveMember(member: WorkspaceMember) {\n    if (!permissions.value.canManageMembers) return\n    void showRemoveMemberDialog(member.id)\n  }\n\n  function handleChangeRole(\n    member: WorkspaceMember,\n    targetRole: WorkspaceRole\n  ) {\n    if (!permissions.value.canManageMembers) return\n    if (member.role === targetRole) return\n    void showChangeMemberRoleDialog({\n      memberId: member.id,\n      memberName: member.name,\n      targetRole\n    })\n  }\n\n  function showTeamPlans() {\n    subscriptionDialog.show({ planMode: 'team', reason: 'team_members_panel' })\n  }\n\n  return {\n    searchQuery,\n    activeView,\n    sortField,\n    sortDirection,\n    maxSeats,\n    isInPersonalWorkspace,\n    hasTeamPlan,\n    isOnTeamPlan,\n    isPlanEnded,\n    isSalesManagedPlan,\n    isEnterprisePlan,\n    hasMemberSeats,\n    isPlanLoading,\n    hasMultipleMembers,\n    showSearch,\n    showViewTabs,\n    showInviteButton,\n    handleInviteMember,\n    personalWorkspaceMember,\n    filteredMembers,\n    filteredPendingInvites,\n    memberMenuItems,\n    memberMenus,\n    members,\n    membersLoaded,\n    totalMembers,\n    pendingInvites,\n    pendingInvitesLoaded,\n    permissions,\n    uiConfig,\n    userPhotoUrl,\n    isCurrentUser,\n    isOriginalOwner,\n    toggleSort,\n    showTeamPlans,\n    handleResendInvite,\n    handleRevokeInvite,\n    handleRemoveMember,\n    handleChangeRole\n  }\n}\n","<template>\n  <Menu :items=\"menuItems\">\n    <template #trigger>\n      <Button\n        :tooltip=\"$t('g.moreOptions')\"\n        variant=\"muted-textonly\"\n        size=\"icon-lg\"\n        :aria-label=\"$t('g.moreOptions')\"\n        icon=\"icon-[lucide--ellipsis]\"\n      />\n    </template>\n  </Menu>\n</template>\n\n<script setup lang=\"ts\">\nimport type { MenuItem } from '@/components/ui/menu/types'\nimport { storeToRefs } from 'pinia'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useWorkspaceUI } from '@/platform/workspace/composables/useWorkspaceUI'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport { useWorkspaceDialogs } from '@/platform/workspace/composables/useWorkspaceDialogs'\n\nconst { t } = useI18n()\nconst {\n  showLeaveWorkspaceDialog,\n  showDeleteWorkspaceDialog,\n  showEditWorkspaceDialog\n} = useWorkspaceDialogs()\nconst { isWorkspaceSubscribed } = storeToRefs(useTeamWorkspaceStore())\nconst { permissions, uiConfig } = useWorkspaceUI()\n\n// Disable delete when the workspace has an active subscription (prevents\n// accidental deletion); uses the workspace's own status, not the global one.\nconst isDeleteDisabled = computed(\n  () =>\n    uiConfig.value.workspaceMenuAction === 'delete' &&\n    isWorkspaceSubscribed.value\n)\n\nconst deleteTooltip = computed(() => {\n  if (!isDeleteDisabled.value) return undefined\n  const tooltipKey = uiConfig.value.workspaceMenuDisabledTooltip\n  return tooltipKey ? t(tooltipKey) : undefined\n})\n\nfunction leaveWorkspace() {\n  if (!permissions.value.canLeaveWorkspace) return\n  void showLeaveWorkspaceDialog()\n}\n\nfunction deleteWorkspace() {\n  if (\n    !permissions.value.canManageSubscription ||\n    uiConfig.value.workspaceMenuAction !== 'delete' ||\n    isDeleteDisabled.value\n  ) {\n    return\n  }\n  void showDeleteWorkspaceDialog()\n}\n\nconst menuItems = computed<MenuItem[]>(() => {\n  const items: MenuItem[] = []\n\n  if (uiConfig.value.showEditWorkspaceMenuItem) {\n    items.push({\n      label: t('workspacePanel.menu.editWorkspace'),\n      icon: 'pi pi-pencil',\n      command: () => showEditWorkspaceDialog()\n    })\n  }\n\n  if (\n    uiConfig.value.workspaceMenuAction === 'delete' &&\n    permissions.value.canManageSubscription\n  ) {\n    items.push({\n      label: t('workspacePanel.menu.deleteWorkspace'),\n      icon: 'pi pi-trash',\n      variant: 'destructive',\n      disabled: isDeleteDisabled.value,\n      tooltip: deleteTooltip.value,\n      command: isDeleteDisabled.value ? undefined : deleteWorkspace\n    })\n  }\n\n  if (permissions.value.canLeaveWorkspace) {\n    items.push({\n      label: t('workspacePanel.menu.leaveWorkspace'),\n      icon: 'pi pi-sign-out',\n      command: leaveWorkspace\n    })\n  }\n\n  return items\n})\n</script>\n","<template>\n  <Menu :items=\"menuItems\">\n    <template #trigger>\n      <Button\n        :tooltip=\"$t('g.moreOptions')\"\n        variant=\"muted-textonly\"\n        size=\"icon-lg\"\n        :aria-label=\"$t('g.moreOptions')\"\n        icon=\"icon-[lucide--ellipsis]\"\n      />\n    </template>\n  </Menu>\n</template>\n\n<script setup lang=\"ts\">\nimport type { MenuItem } from '@/components/ui/menu/types'\nimport { storeToRefs } from 'pinia'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useWorkspaceUI } from '@/platform/workspace/composables/useWorkspaceUI'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport { useWorkspaceDialogs } from '@/platform/workspace/composables/useWorkspaceDialogs'\n\nconst { t } = useI18n()\nconst {\n  showLeaveWorkspaceDialog,\n  showDeleteWorkspaceDialog,\n  showEditWorkspaceDialog\n} = useWorkspaceDialogs()\nconst { isWorkspaceSubscribed } = storeToRefs(useTeamWorkspaceStore())\nconst { permissions, uiConfig } = useWorkspaceUI()\n\n// Disable delete when the workspace has an active subscription (prevents\n// accidental deletion); uses the workspace's own status, not the global one.\nconst isDeleteDisabled = computed(\n  () =>\n    uiConfig.value.workspaceMenuAction === 'delete' &&\n    isWorkspaceSubscribed.value\n)\n\nconst deleteTooltip = computed(() => {\n  if (!isDeleteDisabled.value) return undefined\n  const tooltipKey = uiConfig.value.workspaceMenuDisabledTooltip\n  return tooltipKey ? t(tooltipKey) : undefined\n})\n\nfunction leaveWorkspace() {\n  if (!permissions.value.canLeaveWorkspace) return\n  void showLeaveWorkspaceDialog()\n}\n\nfunction deleteWorkspace() {\n  if (\n    !permissions.value.canManageSubscription ||\n    uiConfig.value.workspaceMenuAction !== 'delete' ||\n    isDeleteDisabled.value\n  ) {\n    return\n  }\n  void showDeleteWorkspaceDialog()\n}\n\nconst menuItems = computed<MenuItem[]>(() => {\n  const items: MenuItem[] = []\n\n  if (uiConfig.value.showEditWorkspaceMenuItem) {\n    items.push({\n      label: t('workspacePanel.menu.editWorkspace'),\n      icon: 'pi pi-pencil',\n      command: () => showEditWorkspaceDialog()\n    })\n  }\n\n  if (\n    uiConfig.value.workspaceMenuAction === 'delete' &&\n    permissions.value.canManageSubscription\n  ) {\n    items.push({\n      label: t('workspacePanel.menu.deleteWorkspace'),\n      icon: 'pi pi-trash',\n      variant: 'destructive',\n      disabled: isDeleteDisabled.value,\n      tooltip: deleteTooltip.value,\n      command: isDeleteDisabled.value ? undefined : deleteWorkspace\n    })\n  }\n\n  if (permissions.value.canLeaveWorkspace) {\n    items.push({\n      label: t('workspacePanel.menu.leaveWorkspace'),\n      icon: 'pi pi-sign-out',\n      comma