uted(() => {\n  if (variant === 'reactivate')\n    return t('workspacePanel.members.upsellBannerReactivate')\n  if (variant === 'contactSales')\n    return enterprise\n      ? t('workspacePanel.members.upsellBannerEnterpriseEnded')\n      : t('workspacePanel.members.upsellBannerPlanEnded')\n  return t('workspacePanel.members.upsellBanner')\n})\n\nconst cta = computed(() => {\n  // Not the ending banner's \"Resume subscription\": an ended plan is past\n  // resuming — this CTA starts a new subscription through the pricing table.\n  if (variant === 'reactivate') return t('workspacePanel.members.resubscribe')\n  if (variant === 'contactSales')\n    return t('workspacePanel.members.contactSales')\n  return t('workspacePanel.members.upgradeToTeam')\n})\n</script>\n","<template>\n  <div class=\"@container mb-4\">\n    <div\n      role=\"status\"\n      class=\"flex flex-col gap-3 rounded-2xl border border-interface-stroke/60 bg-base-background p-4 @2xl:flex-row @2xl:items-center @2xl:gap-2\"\n    >\n      <div class=\"flex min-w-0 flex-1 flex-col gap-1\">\n        <div class=\"flex items-center gap-2\">\n          <i\n            class=\"icon-[lucide--circle-alert] size-4 shrink-0 text-muted-foreground\"\n          />\n          <span v-if=\"title\" class=\"text-sm text-base-foreground\">\n            {{ title }}\n          </span>\n          <span v-else class=\"text-sm text-muted-foreground\">{{ body }}</span>\n        </div>\n        <p v-if=\"title\" class=\"m-0 pl-6 text-sm text-muted-foreground\">\n          {{ body }}\n        </p>\n      </div>\n      <div class=\"flex shrink-0 flex-wrap items-center gap-2 pl-6 @2xl:pl-0\">\n        <Button variant=\"secondary\" size=\"lg\" @click=\"$emit('action')\">\n          {{ cta }}\n        </Button>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\n\n// 'upgrade': personal workspace pitching the Team plan (no title — a pitch,\n// not a state change). 'reactivate' / 'contactSales': the plan has ended\n// (billing_status inactive) and the route back differs by tier — self-serve\n// resumes in-product, Enterprise goes through sales (DES-1200).\n// `enterprise` discriminates the contactSales copy only: unrecognized tiers\n// route to sales too, but must not be named Enterprise (no borrowed claims).\nconst { variant, enterprise = false } = defineProps<{\n  variant: 'upgrade' | 'reactivate' | 'contactSales'\n  enterprise?: boolean\n}>()\n\ndefineEmits<{\n  action: []\n}>()\n\nconst { t } = useI18n()\n\nconst title = computed(() => {\n  if (variant === 'reactivate')\n    return t('workspacePanel.members.endedTeamTitle')\n  if (variant === 'contactSales')\n    return enterprise\n      ? t('workspacePanel.members.endedEnterpriseTitle')\n      : t('workspacePanel.members.endedPlanTitle')\n  return null\n})\n\nconst body = computed(() => {\n  if (variant === 'reactivate')\n    return t('workspacePanel.members.upsellBannerReactivate')\n  if (variant === 'contactSales')\n    return enterprise\n      ? t('workspacePanel.members.upsellBannerEnterpriseEnded')\n      : t('workspacePanel.members.upsellBannerPlanEnded')\n  return t('workspacePanel.members.upsellBanner')\n})\n\nconst cta = computed(() => {\n  // Not the ending banner's \"Resume subscription\": an ended plan is past\n  // resuming — this CTA starts a new subscription through the pricing table.\n  if (variant === 'reactivate') return t('workspacePanel.members.resubscribe')\n  if (variant === 'contactSales')\n    return t('workspacePanel.members.contactSales')\n  return t('workspacePanel.members.upgradeToTeam')\n})\n</script>\n","<template>\n  <div>\n    <div\n      v-for=\"invite in invites\"\n      :key=\"invite.id\"\n      :class=\"\n        cn(\n          'grid w-full items-center border-b border-interface-stroke/30 p-2 last:border-0',\n          gridCols\n        )\n      \"\n    >\n      <div\n        :class=\"\n          cn('flex items-center gap-3', isExpired(invite) && 'opacity-60')\n        \"\n      >\n        <div\n          class=\"flex size-8 shrink-0 items-center justify-center rounded-full bg-secondary-background\"\n        >\n          <span class=\"text-sm text-muted-foreground\">\n            {{ getInviteInitial(invite.email) }}\n          </span>\n        </div>\n        <div class=\"flex min-w-0 flex-1 flex-col gap-1\">\n          <span class=\"text-sm text-base-foreground\">\n            {{ getInviteDisplayName(invite.email) }}\n          </span>\n          <span class=\"text-sm text-muted-foreground\">\n            {{ invite.email }}\n          </span>\n        </div>\n      </div>\n      <span class=\"text-sm text-muted-foreground\">\n        {{ formatDate(invite.inviteDate) }}\n      </span>\n      <span\n        :class=\"\n          cn(\n            'text-sm',\n            isExpired(invite)\n              ? 'text-warning-background'\n              : 'text-muted-foreground'\n          )\n        \"\n      >\n        {{\n          isExpired(invite)\n            ? $t('workspacePanel.members.expiredOn', {\n                date: formatDate(invite.expiryDate)\n              })\n            : formatDate(invite.expiryDate)\n        }}\n      </span>\n      <div class=\"flex items-center justify-end\">\n        <Menu :items=\"getInviteMenuItems(invite)\" align=\"end\">\n          <template #trigger>\n            <Button\n              size=\"icon\"\n              variant=\"muted-textonly\"\n              :aria-label=\"$t('g.moreOptions')\"\n              icon=\"icon-[lucide--ellipsis]\"\n            />\n          </template>\n        </Menu>\n      </div>\n    </div>\n    <div\n      v-if=\"loaded && invites.length === 0\"\n      class=\"flex w-full items-center justify-center py-8 text-sm text-muted-foreground\"\n    >\n      {{\n        searchQuery.trim()\n          ? $t('workspacePanel.members.noInvitesMatch', {\n              query: searchQuery.trim()\n            })\n          : $t('workspacePanel.members.noInvites')\n      }}\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport type { MenuItem } from '@/components/ui/menu/types'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport type { WorkspacePendingInvite } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport {\n  buildInviteLink,\n  copyTextSilently\n} from '@/platform/workspace/utils/inviteLinks'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst toast = useToast()\n\nconst { searchQuery = '', loaded = false } = defineProps<{\n  invites: WorkspacePendingInvite[]\n  gridCols: string\n  searchQuery?: string\n  loaded?: boolean\n}>()\n\nconst emit = defineEmits<{\n  resend: [invite: WorkspacePendingInvite]\n  revoke: [invite: WorkspacePendingInvite]\n}>()\n\nconst { d, t } = useI18n()\n\nfunction getInviteDisplayName(email: string): string {\n  return email.split('@')[0]\n}\n\nfunction getInviteInitial(email: string): string {\n  return email.charAt(0).toUpperCase()\n}\n\nfunction formatDate(date: Date): string {\n  return d(date, { dateStyle: 'medium' })\n}\n\n// Same predicate that gates the Copy invite link item: the BE returns a token\n// only for non-expired invites, so the marker always explains the missing action.\nfunction isExpired(invite: WorkspacePendingInvite): boolean {\n  return !invite.token\n}\n\nasync function copyInviteLink(invite: WorkspacePendingInvite) {\n  if (!invite.token) return\n  if (await copyTextSilently(buildInviteLink(invite.token))) {\n    toast.success(t('workspacePanel.inviteLinks.copiedToast'), {\n      duration: 3000\n    })\n  } else {\n    toast.error(t('workspacePanel.inviteLinks.copyFailedToast'))\n  }\n}\n\nfunction getInviteMenuItems(invite: WorkspacePendingInvite): MenuItem[] {\n  return [\n    {\n      label: () => t('workspacePanel.members.actions.copyInviteLink'),\n      icon: 'icon-[lucide--link]',\n      visible: Boolean(invite.token),\n      command: () => copyInviteLink(invite)\n    },\n    {\n      label: () => t('workspacePanel.members.actions.resendInvite'),\n      icon: 'icon-[lucide--mail-plus]',\n      command: () => emit('resend', invite)\n    },\n    {\n      label: () => t('workspacePanel.members.actions.cancelInvite'),\n      icon: 'icon-[lucide--mail-x]',\n      command: () => emit('revoke', invite)\n    }\n  ]\n}\n</script>\n","<template>\n  <div>\n    <div\n      v-for=\"invite in invites\"\n      :key=\"invite.id\"\n      :class=\"\n        cn(\n          'grid w-full items-center border-b border-interface-stroke/30 p-2 last:border-0',\n          gridCols\n        )\n      \"\n    >\n      <div\n        :class=\"\n          cn('flex items-center gap-3', isExpired(invite) && 'opacity-60')\n        \"\n      >\n        <div\n          class=\"flex size-8 shrink-0 items-center justify-center rounded-full bg-secondary-background\"\n        >\n          <span class=\"text-sm text-muted-foreground\">\n            {{ getInviteInitial(invite.email) }}\n          </span>\n        </div>\n        <div class=\"flex min-w-0 flex-1 flex-col gap-1\">\n          <span class=\"text-sm text-base-foreground\">\n            {{ getInviteDisplayName(invite.email) }}\n          </span>\n          <span class=\"text-sm text-muted-foreground\">\n            {{ invite.email }}\n          </span>\n        </div>\n      </div>\n      <span class=\"text-sm text-muted-foreground\">\n        {{ formatDate(invite.inviteDate) }}\n      </span>\n      <span\n        :class=\"\n          cn(\n            'text-sm',\n            isExpired(invite)\n              ? 'text-warning-background'\n              : 'text-muted-foreground'\n          )\n        \"\n      >\n        {{\n          isExpired(invite)\n            ? $t('workspacePanel.members.expiredOn', {\n                date: formatDate(invite.expiryDate)\n              })\n            : formatDate(invite.expiryDate)\n        }}\n      </span>\n      <div class=\"flex items-center justify-end\">\n        <Menu :items=\"getInviteMenuItems(invite)\" align=\"end\">\n          <template #trigger>\n            <Button\n              size=\"icon\"\n              variant=\"muted-textonly\"\n              :aria-label=\"$t('g.moreOptions')\"\n              icon=\"icon-[lucide--ellipsis]\"\n            />\n          </template>\n        </Menu>\n      </div>\n    </div>\n    <div\n      v-if=\"loaded && invites.length === 0\"\n      class=\"flex w-full items-center justify-center py-8 text-sm text-muted-foreground\"\n    >\n      {{\n        searchQuery.trim()\n          ? $t('workspacePanel.members.noInvitesMatch', {\n              query: searchQuery.trim()\n            })\n          : $t('workspacePanel.members.noInvites')\n      }}\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport type { MenuItem } from '@/components/ui/menu/types'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport type { WorkspacePendingInvite } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport {\n  buildInviteLink,\n  copyTextSilently\n} from '@/platform/workspace/utils/inviteLinks'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst toast = useToast()\n\nconst { searchQuery = '', loaded = false } = defineProps<{\n  invites: WorkspacePendingInvite[]\n  gridCols: string\n  searchQuery?: string\n  loaded?: boolean\n}>()\n\nconst emit = defineEmits<{\n  resend: [invite: WorkspacePendingInvite]\n  revoke: [invite: WorkspacePendingInvite]\n}>()\n\nconst { d, t } = useI18n()\n\nfunction getInviteDisplayName(email: string): string {\n  return email.split('@')[0]\n}\n\nfunction getInviteInitial(email: string): string {\n  return email.charAt(0).toUpperCase()\n}\n\nfunction formatDate(date: Date): string {\n  return d(date, { dateStyle: 'medium' })\n}\n\n// Same predicate that gates the Copy invite link item: the BE returns a token\n// only for non-expired invites, so the marker always explains the missing action.\nfunction isExpired(invite: WorkspacePendingInvite): boolean {\n  return !invite.token\n}\n\nasync function copyInviteLink(invite: WorkspacePendingInvite) {\n  if (!invite.token) return\n  if (await copyTextSilently(buildInviteLink(invite.token))) {\n    toast.success(t('workspacePanel.inviteLinks.copiedToast'), {\n      duration: 3000\n    })\n  } else {\n    toast.error(t('workspacePanel.inviteLinks.copyFailedToast'))\n  }\n}\n\nfunction getInviteMenuItems(invite: WorkspacePendingInvite): MenuItem[] {\n  return [\n    {\n      label: () => t('workspacePanel.members.actions.copyInviteLink'),\n      icon: 'icon-[lucide--link]',\n      visible: Boolean(invite.token),\n      command: () => copyInviteLink(invite)\n    },\n    {\n      label: () => t('workspacePanel.members.actions.resendInvite'),\n      icon: 'icon-[lucide--mail-plus]',\n      command: () => emit('resend', invite)\n    },\n    {\n      label: () => t('workspacePanel.members.actions.cancelInvite'),\n      icon: 'icon-[lucide--mail-x]',\n      command: () => emit('revoke', invite)\n    }\n  ]\n}\n</script>\n","<template>\n  <div class=\"flex h-full flex-col\">\n    <!-- Upsell Banner -->\n    <MemberUpsellBanner\n      v-if=\"\n        !isPlanLoading &&\n        ((isInPersonalWorkspace && maxSeats === 1) || isPlanEnded) &&\n        permissions.canManageSubscription\n      \"\n      :variant=\"\n        showsEndedUpsell\n          ? isSalesManagedPlan\n            ? 'contactSales'\n            : 'reactivate'\n          : 'upgrade'\n      \"\n      :enterprise=\"isEnterprisePlan\"\n      @action=\"\n        showsEndedUpsell && isSalesManagedPlan\n          ? handleContactSales()\n          : showTeamPlans()\n      \"\n    />\n    <!-- Controls row: tabs, search, invite (outside the table frame). Once the\n         panel scrolls it moves into the dialog header, left of the close\n         button, so the workspace name can scroll away. -->\n    <Teleport\n      defer\n      to=\"#settings-header-controls\"\n      :disabled=\"!isHeaderCollapsed\"\n    >\n      <div\n        ref=\"controlsRef\"\n        :class=\"\n          cn(\n            'flex w-full items-center gap-4',\n            isHeaderCollapsed ? 'min-w-0 flex-1' : 'mb-6'\n          )\n        \"\n      >\n        <div\n          v-if=\"showViewTabs && uiConfig.showPendingTab\"\n          class=\"flex items-center gap-2\"\n        >\n          <Button\n            :variant=\"activeView === 'active' ? 'secondary' : 'muted-textonly'\"\n            size=\"lg\"\n            @click=\"activeView = 'active'\"\n          >\n            {{ $t('workspacePanel.members.tabs.active') }}\n          </Button>\n          <Button\n            v-if=\"uiConfig.showPendingTab\"\n            :variant=\"activeView === 'pending' ? 'secondary' : 'muted-textonly'\"\n            size=\"lg\"\n            @click=\"activeView = 'pending'\"\n          >\n            {{\n              $t('workspacePanel.members.tabs.pendingCount', livePendingCount)\n            }}\n          </Button>\n        </div>\n        <div class=\"ml-auto flex items-center gap-2\">\n          <SearchInput\n            v-if=\"showSearch\"\n            v-model=\"searchQuery\"\n            :placeholder=\"$t('workspacePanel.members.searchPlaceholder')\"\n            size=\"lg\"\n            class=\"w-64\"\n          />\n          <Tooltip v-if=\"showInviteButton\">\n            <TooltipTrigger as-child>\n              <span class=\"inline-flex\">\n                <Button\n                  variant=\"secondary\"\n                  size=\"lg\"\n                  :aria-label=\"$t('workspacePanel.inviteMember')\"\n                  @click=\"handleInviteMember\"\n                >\n                  {{ $t('workspacePanel.invite') }}\n                  <i class=\"pi pi-plus text-sm\" />\n                </Button>\n              </span>\n            </TooltipTrigger>\n            <TooltipContent>{{\n              $t('workspacePanel.inviteMember')\n            }}</TooltipContent>\n          </Tooltip>\n          <WorkspaceMenuButton v-if=\"permissions.canAccessWorkspaceMenu\" />\n        </div>\n      </div>\n    </Teleport>\n    <div\n      class=\"flex min-h-0 w-full flex-1 flex-col gap-2 rounded-2xl border border-interface-stroke p-6\"\n    >\n      <!-- Members Content -->\n      <div class=\"flex min-h-0 flex-1 flex-col\">\n        <div class=\"min-h-0 flex-1 overflow-y-auto\" @scroll=\"handlePanelScroll\">\n          <!-- Table Header with Tab Buttons and Column Headers -->\n          <div\n            v-if=\"\n              uiConfig.showMembersList && (showViewTabs || hasMultipleMembers)\n            \"\n            :class=\"\n              cn(\n                'sticky -top-px z-10 grid w-full items-center bg-base-background px-2 pt-[calc(--spacing(2)+1px)] pb-2',\n                activeView === 'pending'\n                  ? uiConfig.pendingGridCols\n                  : uiConfig.headerGridCols\n              )\n            \"\n          >\n            <!-- Email column header -->\n            <span class=\"text-xs text-muted-foreground\">\n              {{ $t('workspacePanel.members.columns.email') }}\n            </span>\n            <!-- Date column headers -->\n            <template v-if=\"activeView === 'pending'\">\n              <Button\n                variant=\"muted-textonly\"\n                size=\"sm\"\n                class=\"w-fit justify-self-start\"\n                @click=\"toggleSort('inviteDate')\"\n              >\n                {{ $t('workspacePanel.members.columns.inviteDate') }}\n                <i class=\"icon-[lucide--chevrons-up-down] size-4\" />\n              </Button>\n              <Button\n                variant=\"muted-textonly\"\n                size=\"sm\"\n                class=\"w-fit justify-self-start\"\n                @click=\"toggleSort('expiryDate')\"\n              >\n                {{ $t('workspacePanel.members.columns.expiryDate') }}\n                <i class=\"icon-[lucide--chevrons-up-down] size-4\" />\n              </Button>\n              <div />\n            </template>\n            <template v-else>\n              <span\n                :class=\"\n                  cn(\n                    'text-xs text-muted-foreground',\n                    uiConfig.showCreditsColumn\n                      ? 'justify-self-start'\n                      : 'justify-self-end'\n                  )\n                \"\n              >\n                {{ $t('workspacePanel.members.columns.role') }}\n              </span>\n              <div\n                v-if=\"uiConfig.showCreditsColumn\"\n                class=\"flex items-center gap-1 text-xs text-muted-foreground\"\n              >\n                <i class=\"icon-[lucide--coins] size-4\" />\n                {{ $t('workspacePanel.members.columns.creditsUsed') }}\n              </div>\n              <!-- Empty cell for action column header (OWNER only) -->\n              <div v-if=\"permissions.canManageMembers\" />\n            </template>\n          </div>\n\n          <!-- Members List -->\n          <!-- Empty States -->\n          <p\n            v-if=\"emptyStateMessage\"\n            class=\"p-6 text-center text-sm text-muted-foreground\"\n          >\n            {{ emptyStateMessage }}\n          </p>\n\n          <!-- Active Members -->\n          <template v-if=\"activeView === 'active'\">\n            <template\n              v-if=\"\n                isInPersonalWorkspace && maxSeats === 1 && !hasMultipleMembers\n              \"\n            >\n              <MemberListItem\n                :member=\"personalWorkspaceMember\"\n                :is-current-user=\"true\"\n                :photo-url=\"userPhotoUrl ?? undefined\"\n                :grid-cols=\"uiConfig.membersGridCols\"\n                :is-single-seat-plan=\"maxSeats === 1\"\n              />\n            </template>\n\n            <template v-else>\n              <MemberListItem\n                v-for=\"member in filteredMembers\"\n                :key=\"member.id\"\n                :member=\"member\"\n                :is-current-user=\"isCurrentUser(member)\"\n                :photo-url=\"\n                  isCurrentUser(member)\n                    ? (userPhotoUrl ?? undefined)\n                    : undefined\n                \"\n                :grid-cols=\"uiConfig.membersGridCols\"\n                :show-role-column=\"\n                  uiConfig.showRoleColumn && hasMultipleMembers\n                \"\n                :show-credits-column=\"uiConfig.showCreditsColumn\"\n                :can-manage-members=\"permissions.canManageMembers\"\n                :menu-items=\"memberMenus.get(member.id)\"\n              />\n            </template>\n          </template>\n\n          <!-- Pending Invites -->\n          <PendingInvitesList\n            v-if=\"activeView === 'pending' && permissions.canViewPendingInvites\"\n            :invites=\"filteredPendingInvites\"\n            :grid-cols=\"uiConfig.pendingGridCols\"\n            :search-query=\"searchQuery\"\n            :loaded=\"pendingInvitesLoaded\"\n            @resend=\"handleResendInvite\"\n            @revoke=\"handleRevokeInvite\"\n          />\n        </div>\n      </div>\n    </div>\n    <div v-if=\"isPlanEnded\" class=\"flex shrink-0 items-center gap-1 pt-2 pb-6\">\n      <p class=\"text-sm text-muted-foreground\">\n        {{ $t('workspacePanel.members.planEndedFooter') }}\n      </p>\n      <Button\n        v-if=\"permissions.canManageSubscription\"\n        variant=\"muted-textonly\"\n        size=\"sm\"\n        class=\"text-sm text-base-foreground\"\n        @click=\"isSalesManagedPlan ? handleContactSales() : showTeamPlans()\"\n      >\n        {{\n          isSalesManagedPlan\n            ? $t('workspacePanel.members.contactSales')\n            : $t('workspacePanel.members.resubscribe')\n        }}\n      </Button>\n    </div>\n    <!-- Need More Members Footer -->\n    <div\n      v-else-if=\"hasMemberSeats && membersLoaded\"\n      class=\"flex shrink-0 items-center gap-1 pt-2 pb-6\"\n    >\n      <p class=\"text-sm text-muted-foreground\">\n        {{\n          maxSeats === 0\n            ? $t(\n                'workspacePanel.members.totalMembersUnlimited',\n                { count: totalMembers },\n                totalMembers\n              )\n            : $t('workspacePanel.members.totalMembersCount', {\n                count: totalMembers,\n                maxSeats: maxSeats\n              })\n        }}\n        {{ $t('workspacePanel.members.needMoreMembers') }}\n      </p>\n      <Button\n        variant=\"muted-textonly\"\n        size=\"sm\"\n        class=\"text-sm text-base-foreground\"\n        @click=\"handleContactUs\"\n      >\n        {{ $t('workspacePanel.members.contactUs') }}\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, nextTick, useTemplateRef, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useSettingsHeaderCollapse } from '@/platform/settings/composables/useSettingsHeaderCollapse'\n\nimport SearchInput from '@/components/ui/search-input/SearchInput.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\nimport WorkspaceMenuButton from '@/platform/workspace/components/dialogs/settings/WorkspaceMenuButton.vue'\nimport MemberListItem from '@/platform/workspace/components/dialogs/settings/MemberListItem.vue'\nimport MemberUpsellBanner from '@/platform/workspace/components/dialogs/settings/MemberUpsellBanner.vue'\nimport PendingInvitesList from '@/platform/workspace/components/dialogs/settings/PendingInvitesList.vue'\nimport { ENTERPRISE_URL } from '@/platform/cloud/subscription/constants/tierPricing'\nimport { useMembersPanel } from '@/platform/workspace/composables/useMembersPanel'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst TEAM_PLAN_REQUEST_URL =\n  'https://comfysupport.portal.usepylon.com/forms/team-plan-requests'\n\nconst {\n  searchQuery,\n  membersLoaded,\n  totalMembers,\n  pendingInvitesLoaded,\n  activeView,\n  maxSeats,\n  isInPersonalWorkspace,\n  isPlanEnded,\n  isSalesManagedPlan,\n  isEnterprisePlan,\n  hasMemberSeats,\n  isPlanLoading,\n  hasMultipleMembers,\n  showSearch,\n  showViewTabs,\n  showInviteButton,\n  handleInviteMember,\n  personalWorkspaceMember,\n  filteredMembers,\n  filteredPendingInvites,\n  memberMenus,\n  pendingInvites,\n  permissions,\n  uiConfig,\n  userPhotoUrl,\n  isCurrentUser,\n  toggleSort,\n  showTeamPlans,\n  handleResendInvite,\n  handleRevokeInvite\n} = useMembersPanel()\n\nconst { isHeaderCollapsed, handlePanelScroll } = useSettingsHeaderCollapse()\n\nconst controlsRef = useTemplateRef<HTMLElement>('controlsRef')\n\n// Teleporting re-parents these controls, which blurs whatever is focused and\n// aborts an in-progress IME composition. Restore focus after the move so a\n// half-typed filter survives the header collapsing.\nwatch(isHeaderCollapsed, async () => {\n  const active = document.activeElement\n  const wasInside =\n    active instanceof HTMLElement && !!controlsRef.value?.contains(active)\n  if (!wasInside) return\n  await nextTick()\n  active.focus()\n})\n\nconst { t } = useI18n()\n\n// A personal workspace always pitches the Team plan here; its own plan\n// lifecycle lives on the Plan & Credits tab.\nconst showsEndedUpsell = computed(\n  () => isPlanEnded.value && !isInPersonalWorkspace.value\n)\n\nconst emptyStateMessage = computed(() => {\n  if (!uiConfig.value.showMembersList) return null\n  if (!membersLoaded.value) return null\n  if (activeView.value !== 'active') return null\n  if (\n    isInPersonalWorkspace.value &&\n    maxSeats.value === 1 &&\n    !hasMultipleMembers.value\n  )\n    return null\n  if (filteredMembers.value.length > 0) return null\n\n  const query = searchQuery.value.trim()\n  return query\n    ? t('workspacePanel.members.noMembersMatch', { query })\n    : t('workspacePanel.members.noMembers')\n})\n\nconst livePendingCount = computed(\n  () => pendingInvites.value.filter((invite) => invite.token).length\n)\n\nfunction handleContactUs() {\n  window.open(TEAM_PLAN_REQUEST_URL, '_blank', 'noopener,noreferrer')\n}\n\n// The ended banner and footer action: a sales-managed plan's route back is the\n// enterprise page, not the team-plan request form the Contact us link uses.\nfunction handleContactSales() {\n  window.open(ENTERPRISE_URL, '_blank', 'noopener,noreferrer')\n}\n</script>\n","<template>\n  <div class=\"flex h-full flex-col\">\n    <!-- Upsell Banner -->\n    <MemberUpsellBanner\n      v-if=\"\n        !isPlanLoading &&\n        ((isInPersonalWorkspace && maxSeats === 1) || isPlanEnded) &&\n        permissions.canManageSubscription\n      \"\n      :variant=\"\n        showsEndedUpsell\n          ? isSalesManagedPlan\n            ? 'contactSales'\n            : 'reactivate'\n          : 'upgrade'\n      \"\n      :enterprise=\"isEnterprisePlan\"\n      @action=\"\n        showsEndedUpsell && isSalesManagedPlan\n          ? handleContactSales()\n          : showTeamPlans()\n      \"\n    />\n    <!-- Controls row: tabs, search, invite (outside the table frame). Once the\n         panel scrolls it moves into the dialog header, left of the close\n         button, so the workspace name can scroll away. -->\n    <Teleport\n      defer\n      to=\"#settings-header-controls\"\n      :disabled=\"!isHeaderCollapsed\"\n    >\n      <div\n        ref=\"controlsRef\"\n        :class=\"\n          cn(\n            'flex w-